 308         private void RenderPerfOverlay()
 309         {
 310             if (world == null) return;
 311 
 312             // Обновляем строки только раз в 10 кадров — рендер каждый кадр, текст нет
 313             _perfOverlayFrame++;
 314             bool refresh = (_perfOverlayFrame % 10 == 0);
 315 
 316             float sw = Size.X;
 317             float panelW = 420f;
 318             float panelX = sw - panelW - 10f;
 319             float panelY = 10f;
 320             float lineH = 34f;
 321             float textScale = 0.38f;
 322 
 323             var proj = uiRenderer.GetProjection(); // один раз
 324 
 325             int totalLines = 16;
 326             float totalH = totalLines * lineH + 16f;
 327 
 328             uiRenderer.Prepare();
 329             uiRenderer.DrawRect(panelX - 8, panelY - 6, panelW + 16, totalH,
 330                 new Vector3(0f, 0f, 0f), 0.72f);
 331 
 332             float curY = panelY + 4f;
 333 
 334             // Заголовок — всегда
 335             textRenderer.UpdateText("── PERF OVERLAY (F7) ──");
 336             textRenderer.Render(panelX + 4, curY, 0.40f, proj);
 337             curY += lineH;
 338 
 339             Vector3 ColorFor(double ms, float g, float y, float r)
 340             {
 341                 if (ms <= g) return new Vector3(0.2f, 1f, 0.3f);
 342                 if (ms <= y) return new Vector3(1f, 0.85f, 0.1f);
 343                 if (ms <= r) return new Vector3(1f, 0.3f, 0.1f);
 344                 return new Vector3(0.5f, 0.5f, 0.5f);
 345             }
 346 
 347             // Если надо обновить — пересобираем кэш строк
 348             if (refresh || _perfLines == null)
 349             {
 350                 ServerDebugSnapshot serverDbg = gameServer != null
 351                     ? gameServer.GetDebugSnapshot()
 352                     : new ServerDebugSnapshot("None", 0, 0, 0, "-", "-", "-", "-", default, default);
 353 
 354                 _perfLines = new (string text, string val, Vector3 col)[]
 355                 {
 356             ("Frame total",  $"{_perfFrameMs:0.00} ms",       ColorFor(_perfFrameMs,       16.6f, 33.3f, 50f)),
 357             ("Update logic", $"{_perfUpdateMs:0.00} ms",      ColorFor(_perfUpdateMs,      10f,   20f,   33f)),
 358             ("Chunk update", $"{_perfChunkUpdateMs:0.00} ms", ColorFor(_perfChunkUpdateMs, 3f,    8f,    15f)),
 359             ("GL Upload",    $"{_perfUploadMs:0.00} ms",      ColorFor(_perfUploadMs,      2f,    5f,    10f)),
 360             ("Frustum cull", $"{_perfCullingMs:0.00} ms",     ColorFor(_perfCullingMs,     1f,    3f,    6f)),
 361             ("Terrain gen",  $"{_perfTerrainGenMs:0.00} ms",  ColorFor(_perfTerrainGenMs,  50f,   150f,  300f)),
 362             ("Lighting",     $"{_perfLightMs:0.00} ms",       ColorFor(_perfLightMs,       30f,   100f,  200f)),
 363             ("Mesh build",   $"{_perfMeshMs:0.00} ms",        ColorFor(_perfMeshMs,        20f,   80f,   200f)),
 364             ("Render (CPU)", $"{_perfRenderMs:0.00} ms",      ColorFor(_perfRenderMs,      8f,    16f,   33f)),
 365             ("---", "", Vector3.Zero),
 366             ($"FPS: {fps}  Chunks: {world.ActiveChunksList.Count}/{world.Chunks.Count}", "", Vector3.One),
 367             ($"DrawCalls  solid:{_perfDrawCallsSolid}  water:{_perfDrawCallsWater}", "", Vector3.One),
 368             ($"Threads  gen:{world.DbgActiveGen}  remesh:{world.DbgActiveRemesh}", "", Vector3.One),
 369             ($"Upload avg:{world._avgUploadMs:0.00}ms  max/frame:{world._maxUploadsPerFrame}", "", Vector3.One),
 370             ($"Server {serverDbg.Mode}  ticks:{serverDbg.TickCount}  in:{serverDbg.ProcessedIncomingPackets}", "", Vector3.One),
 371             ($"Net tx/rx client:{serverDbg.ClientConnection.PacketsSent}/{serverDbg.ClientConnection.PacketsReceived} server:{serverDbg.ServerConnection.PacketsSent}/{serverDbg.ServerConnection.PacketsReceived}", "", Vector3.One),
 372                 };
 373             }
 374 
 375             float valX = panelX + panelW - 115f;
 376             foreach (var (text, val, col) in _perfLines)
 377             {
 378                 if (text == "---")
 379                 {
 380                     uiRenderer.DrawRect(panelX, curY + lineH * 0.4f, panelW, 1,
 381                         new Vector3(0.4f, 0.4f, 0.4f), 0.8f);
 382                     curY += lineH * 0.6f;
 383                     continue;
 384                 }
 385 
 386                 textRenderer.UpdateText(text);
 387                 textRenderer.Render(panelX + 4, curY, textScale, proj);
 388 
 389                 if (val != "")
 390                 {
 391                     uiRenderer.DrawRect(valX - 16, curY + 3, 10, 16, col, 1f);
 392                     textRenderer.UpdateText(val);
 393                     textRenderer.Render(valX, curY, textScale, proj);
 394                 }
