2529         private void RenderGame()
2530         {
2531             GL.Enable(EnableCap.DepthTest);
2532             GL.Enable(EnableCap.CullFace);
2533 
2534             Vector3 eyePos = camera.GetEyePosition();
2535             bool isUnderwater = world != null && world.IsWater(eyePos.X, eyePos.Y, eyePos.Z);
2536 
2537             // Настройка бирюзового подводного тумана
2538             Vector3 finalFogColor = isUnderwater ? new Vector3(0.01f, 0.22f, 0.32f) : worldTime.SkyColor;
2539 
2540             // Расчет свечения тумана на закате/рассвете (Survivalcraft Style)
2541             if (!isUnderwater && world != null && worldTime.RainIntensity < 0.05f)
2542             {
2543                 Vector3 sunDir = new Vector3(MathF.Cos(worldTime.SunAngle), MathF.Sin(worldTime.SunAngle), 0f).Normalized();
2544                 float dotSun = Vector3.Dot(camera.Front, sunDir);
2545 
2546                 if (dotSun > 0.0f && (worldTime.CurrentTime > 600f || worldTime.CurrentTime < 200f))
2547                 {
2548                     float glowIntensity = MathF.Pow(dotSun, 4.0f) * 0.45f;
2549                     Vector3 sunsetGlowColor = new Vector3(0.95f, 0.40f, 0.12f);
2550                     finalFogColor = Vector3.Lerp(finalFogColor, sunsetGlowColor, glowIntensity);
2551                 }
2552             }
2553 
2554             if (worldTime.RainIntensity > 0.01f && !isUnderwater)
2555             {
2556                 // Проверяем температуру для цвета тумана
2557                 float temp = world.Generator.GetTemperature(camera.position.X, camera.position.Z);
2558                 Vector3 weatherFog = (temp < 0.35f) ? new Vector3(0.85f, 0.9f, 0.95f) : new Vector3(0.45f, 0.5f, 0.55f);
2559 
2560                 finalFogColor = Vector3.Lerp(finalFogColor, weatherFog, worldTime.RainIntensity * 0.9f);
2561             }
2562 
2563             if (isBurning) finalFogColor = Vector3.Lerp(finalFogColor, new Vector3(0.6f, 0.1f, 0.0f), 0.5f);
2564 
2565             GL.ClearColor(finalFogColor.X, finalFogColor.Y, finalFogColor.Z, 1.0f);
2566 
2567             if (!isUnderwater && world != null)
2568             {
2569                 skyRenderer.Render(camera, worldTime, _lastDt); // Используем _lastDt
2570             }
2571 
