3974         private void PerformSaveAndExit()
3975         {
3976             // Очищаем GPU буферы сущностей и предметов перед удалением мира
3977             if (world != null)
3978             {
3979                 foreach (var item in world.ItemEntities) item.Delete();
3980                 foreach (var ent in world.Entities)
3981                 {
3982                     if (ent is SlimeEntity slime) slime.Delete();
3983                     else if (ent is TntEntity tnt) tnt.Delete();
3984                     else if (ent is FallingBlockEntity fb) fb.Delete();
3985                     else if (ent is PigEntity pig) pig.Delete();
3986                 }
3987             }
3988 
3989             if (isMultiplayerSession)
3990             {
3991                 multiplayerClient?.Dispose();
3992                 multiplayerClient = null;
3993                 isMultiplayerSession = false;
3994             }
3995             else if (world != null && !string.IsNullOrEmpty(currentWorldFolder))
3996             {
3997                 GL.Clear(ClearBufferMask.ColorBufferBit | ClearBufferMask.DepthBufferBit);
3998                 shader.Bind();
3999 
4000                 Vector3 eyePos = camera.GetEyePosition();
4001                 bool underwater = world != null && world.IsWater(eyePos.X, eyePos.Y, eyePos.Z);
4002 
4003                 GL.Uniform3(
4004                     GL.GetUniformLocation(shader.ID, "fogColor"),
4005                     underwater
4006                         ? new Vector3(0, 0.1f, 0.4f)
4007                         : new Vector3(0.5f, 0.7f, 1f)
4008                 );
4009 
4010                 GL.Uniform1(
4011                     GL.GetUniformLocation(shader.ID, "fogDensity"),
4012                     underwater ? 0.15f : 0.007f
4013                 );
4014 
4015                 Matrix4 model = Matrix4.Identity;
4016                 Matrix4 view = camera.GetViewMatrix();
4017                 Matrix4 projection = camera.GetProjectionMatrix();
4018 
4019                 GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "model"), true, ref model);
4020                 GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "view"), true, ref view);
4021                 GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "projection"), true, ref projection);
4022 
4023                 Matrix4 viewProj = view * projection;
4024                 world.RenderSolid(shader, viewProj, camera.position, globalTextureArray, hzbManager);
4025                 world.RenderTransparent(shader, viewProj, camera.position, globalTextureArray, hzbManager);
4026 
4027 
4028                 SaveManager.CaptureIcon(currentWorldFolder, Size.X, Size.Y);
4029 
4030                 PlayerData pd = new PlayerData();
4031                 // --- SAVE BURNING STATE ---
