using OpenTK.Windowing.Common;

namespace EarthBound.States
{
    public interface IGameState
    {
        void Enter();
        void Exit();
        void Update(FrameEventArgs args);
        void Render(FrameEventArgs args);
    }
}

using OpenTK.Windowing.Common;
using System.Collections.Generic;

namespace EarthBound.States
{
    public class GameStateManager
    {
        private readonly Dictionary<GameState, IGameState> _states = new Dictionary<GameState, IGameState>();
        private IGameState _currentState;

        public void AddState(GameState stateName, IGameState state)
        {
            _states[stateName] = state;
        }

        public void SetState(GameState stateName)
        {
            _currentState?.Exit();
            if (_states.TryGetValue(stateName, out var newState))
            {
                _currentState = newState;
                _currentState.Enter();
            }
        }

        public void Update(FrameEventArgs args)
        {
            _currentState?.Update(args);
        }

        public void Render(FrameEventArgs args)
        {
            _currentState?.Render(args);
        }
    }
}

