using OpenTK.Windowing.GraphicsLibraryFramework;
using OpenTK.Mathematics;
using EarthBound.Audio;
using EarthBound.World;

namespace EarthBound
{
    public class InputManager
    {
        private readonly Game _game;

        public InputManager(Game game)
        {
            _game = game;
        }

        public void Update(float dt)
        {
            var keyboard = _game.KeyboardState;
            var mouse = _game.MouseState;

            if (_game.CurrentState == GameState.Playing)
            {
                HandlePlayingInput(keyboard, mouse, dt);
            }

            HandleGlobalHotkeys(keyboard);
        }

        private void HandleGlobalHotkeys(KeyboardState keyboard)
        {
            if (keyboard.IsKeyPressed(Keys.F3)) _game.ToggleDebugInfo();
            if (keyboard.IsKeyPressed(Keys.F1)) _game.ToggleFrameGraph();
            if (keyboard.IsKeyPressed(Keys.F8)) _game.ToggleWindDebug();
            if (keyboard.IsKeyPressed(Keys.F7)) _game.TogglePerfOverlay();

            if (Settings.DevModeEnabled)
            {
                if (keyboard.IsKeyPressed(Keys.F11)) _game.ToggleNetworkOverlay();
                if (keyboard.IsKeyPressed(Keys.F4)) _game.RescuePlayer();
                if (keyboard.IsKeyPressed(Keys.F5)) _game.ToggleWireframe();
                if (keyboard.IsKeyPressed(Keys.F6)) _game.ToggleChunkBorders();
                if (keyboard.IsKeyPressed(Keys.F9)) _game.ReloadShadersAndChunks();
                if (keyboard.IsKeyPressed(Keys.F12)) _game.ToggleAdvancedProfiler();
                if (keyboard.IsKeyPressed(Keys.F2)) _game.ToggleDevMenu();
                if (keyboard.IsKeyPressed(Keys.F10)) _game.ToggleFreeCam();
            }
        }

        private void HandlePlayingInput(KeyboardState keyboard, MouseState mouse, float dt)
        {
            // Hotbar selection
            if (mouse.ScrollDelta.Y > 0) _game.SelectPreviousHotbarSlot();
            if (mouse.ScrollDelta.Y < 0) _game.SelectNextHotbarSlot();

            for (int i = 0; i < 9; i++)
            {
                if (keyboard.IsKeyPressed(Keys.D1 + i)) _game.SelectHotbarSlot(i);
            }

            if (keyboard.IsKeyPressed(Keys.G)) _game.DropItem();
            if (keyboard.IsKeyPressed(Keys.E)) _game.OpenInventory();
            if (keyboard.IsKeyPressed(Keys.Escape)) _game.PauseGame();

            // Mouse interaction (Left/Right click)
            if (mouse.IsButtonDown(MouseButton.Left))
            {
                _game.HandleLeftClick(dt);
            }
            else
            {
                _game.ResetBreaking();
            }

            if (mouse.IsButtonPressed(MouseButton.Right))
            {
                _game.HandleRightClick();
            }
        }
    }
}

