            // 1. Перекомпилируем все шейдеры с диска
            shader.Reload("Default.vert", "Default.frag");
            cloudShader.Reload("Clouds.vert", "Clouds.frag");
            weatherShader.Reload("Weather.vert", "Weather.frag");
            solidShader.Reload("Default.vert", "Solid.frag");

            // Сбрасываем кеш локаций в WorldClass
            world?.ResetUniformCache();

            // 2. Ребилдим все меши чанков
            if (world != null)
            {
                foreach (var c in world.Chunks.Values)
                    world.QueueUpdatePublic(c.Coord);
            }

