        public void HandleLeftClick(float dt)
        {
            if (handSwing == 0) handSwing = 1.0f;

            // Логика зажигалки
            ItemStack held = inventory.GetStack(selectedHotbarSlot);

            // This part was inside IsButtonPressed, but HandleLeftClick is called when IsButtonDown.
            // I need to check if it was just pressed for the lighter logic.
            if (MouseState.IsButtonPressed(MouseButton.Left))
            {
                if (held != null)
                {
                    if (held.Type == BlockType.LIGHTER) { held.Type = BlockType.LIGHTER_ON; audio.PlayPlaceSound(BlockType.IRON_ORE, camera.position); return; }
                    else if (held.Type == BlockType.LIGHTER_ON) { held.Type = BlockType.LIGHTER; audio.PlayPlaceSound(BlockType.IRON_ORE, camera.position); return; }
                }

                // === COMBAT: БЬЁМ СУЩНОСТЕЙ ===
                bool entityHit = false;
                foreach (var ent in world.Entities)
                {
                    if (ent is SlimeEntity slime && !slime.IsDead) // Проверяем слайма
                    {
                        Vector3 toEnt = slime.Position - camera.position;
                        float dist = toEnt.Length;
                        if (dist < 4.0f) // Радиус удара
                        {
                            toEnt.Normalize();
                            float dot = Vector3.Dot(camera.Front, toEnt);
                            if (dot > 0.85f) // Если смотрим прямо на него
                            {
                                if (slime.HurtTimer <= 0)
                                {
                                    slime.Health -= 5.0f; // Урон 5 ХП (всего 15)
                                    slime.HurtTimer = 0.5f; // Отключаем урон на 0.5 сек, заодно триггерим моргание
                                                            // ОТБРАСЫВАНИЕ!
                                    slime.Velocity = camera.Front * 5.0f + new Vector3(0, 5.0f, 0);

                                    audio.PlayHitSound("grass", slime.Position); // Шлепающий звук

                                    entityHit = true;

                                    if (slime.Health <= 0)
                                    {
                                        slime.IsDead = true;
                                        // Дроп с моба
                                        world.SpawnItem(slime.Position, BlockType.MUSHROOM_RED, 1);
                                        world.SpawnItem(slime.Position + new Vector3(0, 0.5f, 0), BlockType.MUSHROOM_BROWN, 1);
                                    }
                                }
                            }
                        }
                    }
                }

                // Если мы кого-то ударили - мы не ломаем блоки в этот клик
                if (entityHit) return;
            }

            RaycastResult hit = Physics.Raycast(camera.GetEyePosition(), camera.Front, 5.0f, world);

            if (hit.Hit)
            {
                BlockType targetType = world.GetBlock(new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z));

                // Тушим огонь сразу
                if (targetType == BlockType.FIRE)
                {
                    world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z, BlockType.AIR);
                    audio.PlayFootstep("grass", camera.position);
                    isBreaking = false;
                }
                else
                {
                    // Обычное ломание
                    if (!isBreaking || breakingTarget != hit.BlockPos)
                    {
                        isBreaking = true;
                        breakingTarget = hit.BlockPos;
                        breakingTimer = 0;
                        hitSoundTimer = 0;
                    }

                    // ИСПОЛЬЗУЕМ НОВЫЙ МЕНЕДЖЕР
                    float hardness = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).Hardness;
                    ItemStack heldItem = inventory.GetStack(selectedHotbarSlot);
                    BlockType toolType = (heldItem != null) ? heldItem.Type : BlockType.AIR;

                    // Используем локальный метод (мы его добавили скриптом)
                    float speedMultiplier = GetMiningSpeed(toolType, targetType);

                    breakingTimer += dt * speedMultiplier;
                    // --- ЧАСТИЦЫ ПРЯМО ВО ВРЕМЯ ЛОМАНИЯ БЛОКА ---
                    if (new Random().NextDouble() < 0.35)
                    {
                        int layer = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).GetTextureLayer(Faces.FRONT, 0);
                        Vector3 blockColor = Vector3.One;

                        if (targetType == BlockType.GRASS || targetType == BlockType.LEAVES) blockColor = new Vector3(0.4f, 0.8f, 0.3f);

                        // ФИКС ЦЕНТРА: Убрали + 0.5f
                        Vector3 spawnPos = new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z)
                                           + new Vector3(hit.FaceNormal.X, hit.FaceNormal.Y, hit.FaceNormal.Z) * 0.5f;

                        particleEmitter.EmitDebris(spawnPos, layer, blockColor, 3);
                    }

                    hitSoundTimer -= dt;
                    if (hitSoundTimer <= 0)
                    {
                        string mat = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).SoundCategory;
                        // ФИКС ЦЕНТРА: Убрали + 0.5f
                        Vector3 hitPos = new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z);
                        audio.PlayHitSound(mat, hitPos);
                        hitSoundTimer = 0.25f;
                    }

                    if (breakingTimer >= hardness)
                    {
                        // --- ЛОГИКА МУЛЬТИ-БЛОКОВ (ЕЛКА) ---
                        if (targetType == BlockType.CHRISTMAS_TREE)
                        {
                            byte data = world.GetBlockData(hit.BlockPos);
                            if (data == 0) world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y + 1, hit.BlockPos.Z, BlockType.AIR);
                            else if (data == 1) world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y - 1, hit.BlockPos.Z, BlockType.AIR);
                        }
                        byte wData = 0;
                        if (targetType == BlockType.WHEAT_BLOCK) wData = world.GetBlockData(hit.BlockPos);

                        // --- BLOCK BREAK PARTICLES ---
                        int layer = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).GetTextureLayer(Faces.FRONT, 0);
                        Vector3 blockColor = Vector3.One;
                        if (targetType == BlockType.GRASS || targetType == BlockType.LEAVES) blockColor = new Vector3(0.4f, 0.8f, 0.3f);

                        // ФИКС ЦЕНТРА: Передаем точные координаты без смещений
                        Vector3 exactCenter = new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z);
                        particleEmitter.EmitBlockBreak(exactCenter, layer, blockColor);

                        // ТЕПЕРЬ УДАЛЯЕМ БЛОК
                        world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z, BlockType.AIR);

                        // --- NEW DROP LOGIC ---
                        BlockType dropType = targetType;
                        int dropCount = 1;

                        if (targetType == BlockType.COAL_ORE) dropType = BlockType.COAL;
                        else if (targetType == BlockType.DIAMOND_ORE) dropType = BlockType.DIAMOND;
                        else if (targetType == BlockType.IRON_ORE) dropType = BlockType.IRON_INGOT;
                        else if (targetType == BlockType.GOLD_ORE) dropType = BlockType.GOLD_INGOT;
                        else if (targetType == BlockType.STONE) dropType = BlockType.COBBLESTONE;
                        else if (targetType == BlockType.TALL_GRASS || targetType == BlockType.TALL_GRASS_TOP)
                        {
                            dropType = BlockType.AIR; // Блок травы никогда не выпадает!
                                                      // Даем 10% шанс выбить семена пшеницы
                            if (new Random().NextDouble() < 0.1)
                                world.SpawnItem(exactCenter, BlockType.WHEAT_SEED, 1);
                        }
                        else if (targetType == BlockType.GRASS || targetType == BlockType.FARMLAND)
                        {
                            dropType = BlockType.DIRT;
                            if (new Random().NextDouble() < 0.1) world.SpawnItem(exactCenter, BlockType.WHEAT_SEED, 1);
                        }
                        else if (targetType == BlockType.LEAVES)
                        {
                            if (new Random().NextDouble() < 0.1) dropType = BlockType.STICK;
                            else dropType = BlockType.AIR;
                        }
                        else if (targetType == BlockType.GLASS) dropType = BlockType.AIR;
                        else if (targetType == BlockType.GRAVEL)
                        {
                            if (new Random().NextDouble() < 0.1) dropType = BlockType.FLINT;
                        }
                        else if (targetType == BlockType.LEAVES || targetType == BlockType.SPRUCE_LEAVES)
                        {
                            if (new Random().NextDouble() < 0.1) dropType = BlockType.STICK;
                            else dropType = BlockType.AIR;
                        }
                        else if (targetType == BlockType.WHEAT_BLOCK)
                        {
                            int growth = wData & 0x07;
                            int visualGrowth = Math.Min(growth, 4);

                            if (visualGrowth == 4)
                            {
                                dropType = BlockType.WHEAT_EAR; dropCount = new Random().Next(6, 13);
                                world.SpawnItem(exactCenter, BlockType.WHEAT_SEED, new Random().Next(1, 3));
                            }
                            else if (visualGrowth == 3)
                            {
                                dropType = BlockType.WHEAT_EAR; dropCount = new Random().Next(4, 8);
                                world.SpawnItem(exactCenter, BlockType.WHEAT_SEED, new Random().Next(1, 3));
                            }
                            else { dropType = BlockType.WHEAT_SEED; dropCount = 1; }
                        }

                        if (dropType != BlockType.AIR) world.SpawnItem(exactCenter, dropType, dropCount);

                        string mat = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).SoundCategory;
                        audio.PlayBreakSound(mat, exactCenter);

                        isBreaking = false;
                        breakingTimer = 0;
                    }
                }
            }
            else { isBreaking = false; breakingTimer = 0; }
        }

        public void HandleRightClick()
        {
            if (handSwing == 0) handSwing = 1.0f;

            RaycastResult hit = Physics.Raycast(camera.GetEyePosition(), camera.Front, 5.0f, world);

            if (hit.Hit)
            {
                BlockType targetType = world.GetBlock(new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z));

                // === INTERACTION ===
                if (targetType == BlockType.WORKBENCH && !KeyboardState.IsKeyDown(Keys.LeftControl)) // Sprinting (Shift) ignores interaction to place blocks
                {
                    CurrentState = GameState.WorkbenchOpen;
                    CursorState = CursorState.Normal;
                    // Очищаем крафт сетку при открытии (или оставляем, если хочешь сохранять)
                    inventory.ClearCrafting();
                    return; // Выход, чтобы не поставить блок
                }
                if (targetType == BlockType.TOMOLKA && !KeyboardState.IsKeyDown(Keys.LeftControl))
                {
                    t_millRotation = 0f; t_millVelocity = 0f;
                    t_seedsInside = 0f; t_flourInside = 0f;
                    t_flourFraction = 0f; t_draggingHandle = false;
                    t_splats.Clear();

                    // Берем текстуру блока, на котором стоят жернова
                    BlockType belowType = world.GetBlock(new Vector3(hit.BlockPos.X, hit.BlockPos.Y - 1, hit.BlockPos.Z));
                    activeTomolkaBaseBlock = (belowType != BlockType.AIR) ? belowType : BlockType.PLANKS;

                    // Open the UI menu
                    CurrentState = GameState.TomolkaOpen;
                    CursorState = CursorState.Normal;
                    return;
                }
                ItemStack current = inventory.GetStack(selectedHotbarSlot);
                if (current != null)
                {
                    // --- ЛОГИКА ВЕДЕР ---
                    if (current.Type == BlockType.WOODEN_BUCKET || current.Type == BlockType.METAL_BUCKET || current.Type == BlockType.WATER_WOODEN_BUCKET || current.Type == BlockType.WATER_METAL_BUCKET || current.Type == BlockType.LAVA_METAL_BUCKET)
                    {
                        Vector3i placePos = hit.BlockPos + hit.FaceNormal;

                        BlockType hitTarget = world.GetBlock(new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z));
                        BlockType placeTarget = world.GetBlock(new Vector3(placePos.X, placePos.Y, placePos.Z));

                        Vector3i targetPos = hit.BlockPos;
                        BlockType targetFluid = hitTarget;

                        if ((hitTarget != BlockType.WATER && hitTarget != BlockType.LAVA) &&
                            (placeTarget == BlockType.WATER || placeTarget == BlockType.LAVA))
                        {
                            targetPos = placePos;
                            targetFluid = placeTarget;
                        }

                        // 1. Pickup fluid
                        if ((current.Type == BlockType.WOODEN_BUCKET || current.Type == BlockType.METAL_BUCKET) && (targetFluid == BlockType.WATER || targetFluid == BlockType.LAVA))
                        {
                            byte fluidData = world.GetBlockData(targetPos);

                            // Convert partial source markers back to real levels
                            byte actualLevel = fluidData;
                            if (fluidData == 0 || fluidData == 8) actualLevel = 8;
                            else if (fluidData > 8) actualLevel = (byte)(fluidData - 8);

                            int volumeLiters = (actualLevel >= 8) ? 1000 : actualLevel * 125;

                            if (targetFluid == BlockType.WATER)
                            {
                                world.SetBlock(targetPos.X, targetPos.Y, targetPos.Z, BlockType.AIR);
                                current.Type = current.Type == BlockType.WOODEN_BUCKET ? BlockType.WATER_WOODEN_BUCKET : BlockType.WATER_METAL_BUCKET;
                                current.Volume = volumeLiters;
                                audio.PlayBucketSound(true, camera.position);
                            }
                            else if (targetFluid == BlockType.LAVA)
                            {
                                if (current.Type == BlockType.WOODEN_BUCKET)
                                {
                                    if (actualLevel >= 8) world.SetBlock(targetPos.X, targetPos.Y, targetPos.Z, BlockType.LAVA, 15);
                                    else if (fluidData > 1) world.SetBlock(targetPos.X, targetPos.Y, targetPos.Z, BlockType.LAVA, (byte)(fluidData - 1));
                                    else world.SetBlock(targetPos.X, targetPos.Y, targetPos.Z, BlockType.AIR);

                                    current.Type = BlockType.BURNING_WOODEN_BUCKET;
                                    current.CurrentDurability = 1500;
                                    audio.PlaySteamSound(camera.position);
                                }
                                else
                                {
                                    world.SetBlock(targetPos.X, targetPos.Y, targetPos.Z, BlockType.AIR);
                                    current.Type = BlockType.LAVA_METAL_BUCKET;
                                    current.Volume = volumeLiters;
                                    audio.PlayBucketSound(true, camera.position);
                                }
                            }
                            handSwing = 1.0f; return;
                        }

                        // 2. Place fluid
                        if ((current.Type == BlockType.WATER_WOODEN_BUCKET || current.Type == BlockType.WATER_METAL_BUCKET || current.Type == BlockType.LAVA_METAL_BUCKET))
                        {
                            BlockType pt = world.GetBlock(new Vector3(placePos.X, placePos.Y, placePos.Z));
                            if (pt == BlockType.AIR || pt == BlockType.FIRE || pt == BlockType.DEAD_BUSH || pt == BlockType.FLOWER_RED || pt == BlockType.FLOWER_YELLOW || pt == BlockType.SNOW_LAYER)
                            {
                                BlockType fluidToPlace = current.Type == BlockType.LAVA_METAL_BUCKET ? BlockType.LAVA : BlockType.WATER;

                                byte dataToPlace = (byte)(current.Volume / 125);
                                if (dataToPlace >= 8) dataToPlace = 8;
                                if (dataToPlace <= 0) dataToPlace = 1;

                                // MARK AS MINI-SOURCE (+8 offset)
                                if (dataToPlace < 8) dataToPlace += 8;

                                world.SetBlock(placePos.X, placePos.Y, placePos.Z, fluidToPlace, dataToPlace);

                                current.CurrentDurability--;
                                if (current.CurrentDurability <= 0)
                                {
                                    inventory.ConsumeItem(selectedHotbarSlot, 1);
                                }
                                else
                                {
                                    current.Type = current.Type == BlockType.WATER_WOODEN_BUCKET ? BlockType.WOODEN_BUCKET : BlockType.METAL_BUCKET;
                                    current.Volume = 0;
                                }

                                audio.PlayBucketSound(false, camera.position);
                                handSwing = 1.0f; return;
                            }
                        }
                    }

                    // --- IGNITE LOGIC ---
                    if (current.Type == BlockType.LIGHTER_ON || current.Type == BlockType.LIGHTER)
                    {
                        if (current.Type == BlockType.LIGHTER) { current.Type = BlockType.LIGHTER_ON; return; }

                        BlockType hitBlock = world.GetBlock(new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z));
                        if (hitBlock == BlockType.TNT)
                        {
                            // Удаляем TNT из мира
                            world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z, BlockType.AIR);

