using OpenTK.Windowing.Common;
using OpenTK.Mathematics;
using EarthBound.World;
using EarthBound.World.Blocks;
using EarthBound.Audio;
using System;

namespace EarthBound.States
{
    public class PlayingState : IGameState
    {
        private readonly Game _game;

        public PlayingState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Grabbed;
            _game.camera.ResetMouse();
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
            float dt = (float)args.Time;

            if (_game.IsFocused && _game.CursorState == CursorState.Grabbed)
            {
                // Check Fall Damage from Camera
                // 1. Урон от падения
                if (_game.camera.PendingDamage > 0)
                {
                    _game.ApplyDamage(_game.camera.PendingDamage);
                    _game.camera.PendingDamage = 0;

                    if (_game.playerHealth <= 0)
                    {
                        _game.playerHealth = 0;
                        _game.CurrentState = GameState.Dead;
                        _game.CursorState = CursorState.Normal;
                    }
                }

                // --- ВОДА И ВСПЛЕСКИ (Теперь всегда проверяется!) ---
                float rSplash = 0.25f;
                bool feetInWater = _game.world.IsWater(_game.camera.position.X, _game.camera.position.Y + 0.2f, _game.camera.position.Z) ||
                                   _game.world.IsWater(_game.camera.position.X - rSplash, _game.camera.position.Y + 0.2f, _game.camera.position.Z - rSplash) ||
                                   _game.world.IsWater(_game.camera.position.X + rSplash, _game.camera.position.Y + 0.2f, _game.camera.position.Z + rSplash);
                bool eyesInWater = _game.world.IsWater(_game.camera.position.X, _game.camera.position.Y + 1.8f, _game.camera.position.Z);
                bool isInLiquid = feetInWater || eyesInWater;
                // Средняя точка погружения (для плавности намокания)
                bool waistInWater = _game.world.IsWater(_game.camera.position.X, _game.camera.position.Y + 1.0f, _game.camera.position.Z);

                // ---- СИСТЕМА ПРОМОКАНИЯ И СУШКИ ИГРОКА ----
                if (isInLiquid)
                {
                    _game.camera.WaterTimer += dt;
                    if (_game.camera.WaterTimer > 0.15f) // 0.1-0.2 секундная задержка перед началом намокания
                    {
                        float wetSpeed = 0.1f;
                        if (eyesInWater) wetSpeed = 1.0f;        // Полное погружение -> промокает за 1 секунду
                        else if (waistInWater) wetSpeed = 0.5f;   // По пояс в воде -> намокание за 2 секунды
                        else if (feetInWater) wetSpeed = 0.25f;   // Ноги в воде -> намокание за 4 секунды

                        _game.camera.Wetness = MathHelper.Clamp(_game.camera.Wetness + wetSpeed * dt, 0.0f, 1.0f);
                    }
                }
                else
                {
                    _game.camera.WaterTimer = 0.0f; // Сбрасываем таймер входа в воду

                    int px = (int)MathF.Floor(_game.camera.position.X);
                    int pz = (int)MathF.Floor(_game.camera.position.Z);
                    int py = (int)MathF.Floor(_game.camera.position.Y);
                    int groundY = _game.world.GetHighestSolidBlockY(px, pz);
                    bool hasRoof = groundY > py + 1;

                    if (_game.worldTime.RainIntensity > 0.01f && !hasRoof)
                    {
                        // Игрок промокает под дождем
                        _game.camera.Wetness = MathHelper.Clamp(_game.camera.Wetness + 0.08f * _game.worldTime.RainIntensity * dt, 0.0f, 1.0f);
                    }
                    else
                    {
                        // Естественное высыхание в сухом месте
                        float drySpeed = 0.015f;

                        // Быстрая сушка возле огня или лавы (в радиусе 3 блоков)
                        bool nearHeat = false;
                        int rRange = 3;
                        for (int dx = -rRange; dx <= rRange && !nearHeat; dx++)
                            for (int dy = -rRange; dy <= rRange && !nearHeat; dy++)
                                for (int dz = -rRange; dz <= rRange; dz++)
                                {
                                    BlockType b = _game.world.GetBlock(new Vector3(px + dx, py + dy, pz + dz));
                                    if (b == BlockType.FIRE || b == BlockType.LAVA)
                                    {
                                        nearHeat = true;
                                        break;
                                    }
                                }

                        if (nearHeat)
                        {
                            drySpeed = 0.25f; // Около огня сохнет в 15 раз быстрее
                        }

                        _game.camera.Wetness = MathHelper.Clamp(_game.camera.Wetness - drySpeed * dt, 0.0f, 1.0f);
                    }
                }
                // Срабатывает при меньшей скорости падения (-2.0f)
                if (isInLiquid && !_game.wasInWater && _game.camera.velocity.Y < -2.0f)
                {
                    // Множитель скорости увеличен с 0.3f до 1.5f (чем быстрее летел, тем ОГРОМНЕЕ всплеск)
                    _game.particleEmitter.EmitSplash(_game.camera.position + new Vector3(0, 0.5f, 0), Math.Abs(_game.camera.velocity.Y) * 1.5f);
                    _game.audio.PlayFootstep("water", _game.camera.position, 1.0f);
                }
                _game.wasInWater = isInLiquid;

                // 2. Логика Огня и Лавы
                Vector3 pPos = _game.camera.position;
                BlockType feetBlock = _game.world.GetBlock(pPos);
                BlockType legBlock = _game.world.GetBlock(new Vector3(pPos.X, pPos.Y - 1, pPos.Z));

                bool inWater = feetBlock == BlockType.WATER || legBlock == BlockType.WATER;

                // Если мы в воде, мы в безопасности, огонь тушится мгновенно
                if (inWater)
                {
                    if (_game.isBurning)
                    {
                        _game.isBurning = false;
                        _game.burnTimer = 0;
                        _game.audio.PlayFootstep("water", pPos); // Звук пшшш сыграет ОДИН раз
                    }
                }
                else
                {
                    if (feetBlock == BlockType.LAVA || legBlock == BlockType.LAVA)
                    {
                        _game.isBurning = true;
                        _game.burnTimer = 10.0f;
                        if (_game.hitSoundTimer <= 0) { _game.ApplyDamage(4.0f); _game.hitSoundTimer = 0.5f; }
                    }
                    else if (feetBlock == BlockType.FIRE || legBlock == BlockType.FIRE)
                    {
                        _game.isBurning = true;
                        _game.burnTimer = 5.0f;
                    }
                }

                if (_game.isBurning)
                {
                    _game.burnTimer -= dt;
                    if (_game.burnTimer <= 0) _game.isBurning = false;
                    if (_game.totalTicks % 20 == 0) _game.ApplyDamage(1.0f);
                }

                // 3. Обновление камеры и аудио (Камера должна быть плавной, оставляем в Update)
                if (_game.isDebugCam)
                {
                    bool oldNoClip = Settings.NoClip;
                    Settings.NoClip = true; // Форсируем полет (без гравитации)
                    _game.debugCamera.Update(_game.KeyboardState, _game.MouseState, args, null, false);
                    Settings.NoClip = oldNoClip;
                }
                else
                {
                    _game.camera.Update(_game.KeyboardState, _game.MouseState, args, _game.world, false);
                }

                // Правильный математический расчет вектора "Макушки" (Up) для 3D эмбиента
                Vector3 camRight = Vector3.Normalize(Vector3.Cross(_game.camera.Front, Vector3.UnitY));
                if (camRight.LengthSquared < 0.001f) camRight = Vector3.UnitX; // Защита от NaN, если смотрим строго вниз
                Vector3 camUp = Vector3.Normalize(Vector3.Cross(camRight, _game.camera.Front));

                // Поднимаем уши на уровень глаз! (иначе звук ручьев будет казаться выше нас)
                _game.audio.UpdateListener(_game.camera.GetEyePosition(), _game.camera.Front, camUp);

                Vector3 headPos = _game.camera.GetEyePosition();
                int headSunLight = _game.world.GetSunLight((int)headPos.X, (int)headPos.Y, (int)headPos.Z);
                int headBlockLight = _game.world.GetBlockLight((int)headPos.X, (int)headPos.Y, (int)headPos.Z);

                // Вычисляем, насколько светло сейчас голове игрока
                float ambientSun = (headSunLight / 15.0f) * _game.worldTime.GlobalLight.X;
                float ambientBlock = headBlockLight / 15.0f;
                float currentHeadLight = Math.Max(ambientSun, ambientBlock);

                // Если вышли на свет - слепнем (привыкаем) быстро. Если зашли в тьму - привыкаем медленно.
                float adaptSpeed = (currentHeadLight > _game.eyeAdaptation) ? 3.0f : 0.4f;
                _game.eyeAdaptation = MathHelper.Lerp(_game.eyeAdaptation, currentHeadLight, dt * adaptSpeed);
                // Обновляем логику облаков
                if (Settings.CloudMode == 2)
                {
                    _game.cloudRenderer.Update(dt, _game.camera.position, _game.worldTime.WindStrength, _game.worldTime.WindDir);
                }

                // 4. ЗВУК ПРИЗЕМЛЕНИЯ
                if (_game.camera.JustLanded)
                {
                    _game.camera.JustLanded = false;

                    // Если зажат пробел, мы УЖЕ подпрыгнули на долю блока. 
                    // Проверяем прямо под ногами (-0.1f), а если там воздух — проверяем ниже (-1.1f)
                    Vector3 checkPos = _game.camera.position - new Vector3(0, 0.1f, 0);
                    BlockType bLand = _game.world.GetBlock(checkPos);

                    if (bLand == BlockType.AIR || bLand == BlockType.WATER || bLand == BlockType.FIRE)
                    {
                        checkPos = _game.camera.position - new Vector3(0, 1.1f, 0);
                        bLand = _game.world.GetBlock(checkPos);
                    }

                    if (bLand != BlockType.AIR && bLand != BlockType.WATER)
                    {
                        string mat = EarthBound.World.Blocks.BlocksManager.GetBlock(bLand).SoundCategory;
                        _game.audio.PlayFootstep(mat, _game.camera.position, 0.5f, 1.2f);
                    }
                }

                // 5. FOOTSTEP SOUNDS
                if (_game.camera.WalkDistance > _game.nextStepDistance)
                {
                    _game.nextStepDistance = _game.camera.WalkDistance + 1.5f;
                    bool feetInWater = _game.world.IsWater(_game.camera.position.X, _game.camera.position.Y - 0.5f, _game.camera.position.Z);

                    // Убираем костыль! camera.position — это УЖЕ координаты ног. Если вычесть 1.6, звук играл глубоко под землей.
                    Vector3 feetPos = _game.camera.position;

                    if (feetInWater)
                    {
                        _game.audio.PlayFootstep("water", feetPos, 1.0f);
                    }
                    else
                    {
                        Vector3 underFeet = _game.camera.position - new Vector3(0, 0.1f, 0);
                        BlockType bType = _game.world.GetBlock(underFeet);

                        if (bType == BlockType.AIR || bType == BlockType.WATER || bType == BlockType.FIRE)
                        {
                            Vector3 below = _game.camera.position - new Vector3(0, 1.1f, 0);
                            bType = _game.world.GetBlock(below);
                        }

                        if (bType != BlockType.AIR && bType != BlockType.WATER)
                        {
                            string mat = EarthBound.World.Blocks.BlocksManager.GetBlock(bType).SoundCategory;
                            _game.audio.PlayFootstep(mat, feetPos, 1.0f);
                        }
                    }
                }

                // --- MUSIC LOGIC ---
                _game.musicTimer -= dt;
                if (_game.musicTimer <= 0)
                {
                    // ИСПОЛЬЗУЕМ НОВЫЙ МЕТОД (0.35f - это базовая громкость трека)
                    _game.audio.PlayGameMusic("assets/audio/music/minecraft_track (1).ogg", 0.35f);
                    _game.musicTimer = 300f + (float)new Random().NextDouble() * 300f;
                }

                // --- WATER AMBIENCE LOGIC (Continuous) ---
                _game.waterAmbienceTimer += dt;
                if (_game.waterAmbienceTimer > 0.2f)
                {
                    _game.waterAmbienceTimer = 0;
                    int waterSourceCount = 0;
                    int waterFlowCount = 0;
                    int lavaCount = 0; // Считаем лаву
                    int radius = 4;
                    Vector3 closestLava = _game.camera.position;
                    float minDist = 999f;

                    int px = (int)_game.camera.position.X; int py = (int)_game.camera.position.Y; int pz = (int)_game.camera.position.Z;

                    for (int x = -radius; x <= radius; x++)
                        for (int y = -2; y <= 2; y++)
                            for (int z = -radius; z <= radius; z++)
                            {
                                BlockType b = _game.world.GetBlock(new Vector3(px + x, py + y, pz + z));
                                if (b == BlockType.WATER)
                                {
                                    byte data = _game.world.GetBlockData(new Vector3(px + x, py + y, pz + z));
                                    if (data == 8 || data == 0) waterSourceCount++; else waterFlowCount++;
                                }
                                else if (b == BlockType.LAVA)
                                {
                                    lavaCount++;
                                    float d = new Vector3(x, y, z).Length;
                                    if (d < minDist) { minDist = d; closestLava = new Vector3(px + x, py + y, pz + z); }
                                }
                            }
                    _game.audio.UpdateWaterStream(_game.currentStreamVol, _game.camera.position);
                    _game.audio.UpdateWaterAmbience(Math.Clamp(waterSourceCount / 20.0f, 0.0f, 0.5f));
                    _game.currentStreamVol = Math.Clamp(waterFlowCount / 5.0f, 0.0f, 0.8f);

                    // Эмбиент лавы
                    _game.audio.UpdateLavaAmbience(lavaCount > 0 ? 0.6f : 0.0f, closestLava);
                }

                // Чанки обновляем каждый кадр для плавности загрузки
                _game.world.UpdateChunksAroundPlayer(_game.camera.position, _game.camera.Front, Settings.RenderDistance);

                // --- RAIN AMBIENCE LOGIC ---
                if (_game.worldTime.RainIntensity > 0.01f)
                {
                    int px = (int)MathF.Floor(_game.camera.position.X);
                    int pz = (int)MathF.Floor(_game.camera.position.Z);
                    int py = (int)MathF.Floor(_game.camera.position.Y);
                    float temp = _game.world.Generator.GetTemperature(px, pz);

                    if (temp >= 0.35f)
                    {
                        // Целевая громкость = реальная плотность частиц дождя × интенсивность
                        float rainDensity = _game.weatherRenderer.GetRainDensityNorm();
                        float splashNorm = rainDensity * _game.worldTime.RainIntensity;
                        // Плавный lerp: нарастает медленно (как и количество частиц), убывает чуть быстрее
                        float lerpUp = dt * 0.15f;  // медленно нарастаем — синхронно с партиклами
                        float lerpDown = dt * 0.4f;
                        _game.rainSoundAccumulator = _game.rainSoundAccumulator < splashNorm
                            ? Math.Min(_game.rainSoundAccumulator + lerpUp, splashNorm)
                            : Math.Max(_game.rainSoundAccumulator - lerpDown, splashNorm);

                        int groundY = _game.world.GetHighestSolidBlockY(px, pz);
                        bool hasRoof = groundY > py + 1;

                        // Позиция звука — фиксированная точка над землёй, не двигается с игроком каждый кадр
                        // Lerp к новой позиции медленно — убирает "бегающий звук"
                        Vector3 targetSoundPos = hasRoof
                            ? new Vector3(px, py + 8f, pz)
                            : new Vector3(px, groundY + 0.5f, pz);

                        float targetVol = hasRoof
                            ? 0.15f * _game.rainSoundAccumulator
                            : _game.rainSoundAccumulator;

                        _game.audio.UpdateRainAmbience(targetVol, targetSoundPos);
                    }
                    else
                    {
                        // Снег — плавно сбрасываем аккумулятор
                        _game.rainSoundAccumulator = Math.Max(_game.rainSoundAccumulator - dt * 0.15f, 0f);
                        _game.audio.UpdateRainAmbience(0.0f, _game.camera.position);
                    }
                }
                else
                {
                    // Дождь кончился — плавно сбрасываем
                    _game.rainSoundAccumulator = Math.Max(_game.rainSoundAccumulator - dt * 0.1f, 0f);
                    if (_game.rainSoundAccumulator > 0.01f)
                        _game.audio.UpdateRainAmbience(_game.rainSoundAccumulator * 0.5f, _game.camera.position);
                    else
                        _game.audio.UpdateRainAmbience(0.0f, _game.camera.position);
                }

                // Время обновляем плавно для неба
                _game.worldTime.Update(dt);

                // Обновление физического симулятора воздушных потоков ветра
                if (_game.windEngine != null)
                {
                    _game.windEngine.Update(dt, _game.camera.position, _game.world, _game.worldTime.WindStrength, _game.worldTime.WindDir);
                }

                // --- ТАЙМЕР ГОРЯЩЕГО ВЕДРА В ИНВЕНТАРЕ ---
                for (int i = 0; i < 9; i++)
                {
                    ItemStack st = _game.inventory.GetStack(i);
                    if (st != null && st.Type == BlockType.BURNING_WOODEN_BUCKET)
                    {
                        st.CurrentDurability -= (int)(dt * 1000); // Используем durability как таймер (1-2 сек)
                        if (st.CurrentDurability <= 0)
                        {
                            _game.inventory.ConsumeItem(i, 1); // Ведро сгорело
                            _game.audio.PlaySteamSound(_game.camera.position);
                        }
                    }
                }
            }
        }

        public void Render(FrameEventArgs args)
        {
            _game.RenderGameMethod();
        }
    }
