namespace EarthBound.States
{
    public class MainMenuState : IGameState
    {
        private readonly Game _game;

        public MainMenuState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
        }

        public void Render(FrameEventArgs args)
        {
            _game.uiRenderer.Prepare();
            _game.uiRenderer.DrawTiledBackground(_game.Size.X, _game.Size.Y);

            // Заголовок
            string title = "EARTHBOUND";
            // Учитываем масштаб 1.5 при расчете ширины!
            float rawW = _game.textRenderer.UpdateText(title);
            float realW = rawW * 1.5f;
            _game.textRenderer.Render((_game.Size.X - realW) / 2, 100, 1.5f, _game.uiRenderer.GetProjection());

            float cx = (_game.Size.X - 400) / 2;
            float startY = _game.Size.Y / 2 - 50;

            if (_game.DrawButtonMethod("PLAY", cx, startY, 400, 50))
            {
                _game.SetState(GameState.WorldSelect);
                _game.savedWorlds = SaveManager.GetWorlds();
                _game.selectedWorldIndex = -1;
            }
            if (_game.DrawButtonMethod("MULTIPLAYER", cx, startY + 60, 400, 50))
            {
                _game.OpenMultiplayerMenuMethod();
            }
            if (_game.DrawButtonMethod("SETTINGS", cx, startY + 120, 400, 50))
            {
                _game.previousStateMethod = GameState.MainMenu;
                _game.SetState(GameState.Settings);
            }
            if (_game.DrawButtonMethod("EXIT", cx, startY + 180, 400, 50))
            {
                _game.Close();
            }
            if (Settings.DevModeEnabled)
            {
                if (_game.DrawButtonMethod("UI REDACTOR", cx, startY + 240, 400, 50))
                {
                    _game.SetState(GameState.UIRedactor);
                    _game.CursorState = CursorState.Normal;
                }
            }


            // --- КНОПКА ЛИЦЕНЗИЙ ---
            float docSize = 50;
            // СДВИНУЛ ЛЕВЕЕ: Было -20, стало -60
            float docX = _game.Size.X - docSize - 60;
            float docY = 20;

            bool hoverDoc = _game.MouseState.Position.X >= docX && _game.MouseState.Position.X <= docX + docSize &&
                            _game.MouseState.Position.Y >= docY && _game.MouseState.Position.Y <= docY + docSize;

            _game.uiRenderer.DrawButton(docX, docY, docSize, docSize, hoverDoc);

            float iconPad = 10;
            float iconSize = docSize - (iconPad * 2);
            float ix = docX + iconPad;
            float iy = docY + iconPad;

            _game.uiRenderer.RenderQuadCustomVerts(
                new float[] {
                    ix,            iy,             0, 1, 0,
                    ix + iconSize, iy,             1, 1, 0,
                    ix + iconSize, iy + iconSize,  1, 0, 0,
                    ix,            iy + iconSize,  0, 0, 0
                },
                _game.texBtnDocument, Vector3.One, 1.0f);

            if (hoverDoc && _game.MouseState.IsButtonPressed(MouseButton.Left))
            {
                _game.LoadLicensesMethod();
                _game.SetState(GameState.LicenseMenu);
            }
        }
    }
}

