using OpenTK.Windowing.Common;
using OpenTK.Windowing.GraphicsLibraryFramework;

namespace EarthBound.States
{
    public class PausedState : IGameState
    {
        private readonly Game _game;

        public PausedState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
            if (_game.KeyboardState.IsKeyPressed(Keys.Escape))
            {
                _game.SetState(GameState.Playing);
            }
        }

        public void Render(FrameEventArgs args)
        {
            // Render the game behind the pause menu
            _game.RenderGameMethod();

            // Draw overlay
            _game.uiRenderer.Prepare();
            _game.uiRenderer.DrawRect(0, 0, _game.Size.X, _game.Size.Y, new OpenTK.Mathematics.Vector4(0, 0, 0, 0.5f));

            string title = "PAUSED";
            float realW = _game.textRenderer.UpdateText(title) * 1.5f;
            _game.textRenderer.Render((_game.Size.X - realW) / 2, _game.Size.Y / 2 - 100, 1.5f, _game.uiRenderer.GetProjection());

            float cx = (_game.Size.X - 400) / 2;
            float cy = _game.Size.Y / 2;

            if (_game.DrawButtonMethod("RESUME", cx, cy - 30, 400, 50))
            {
                _game.SetState(GameState.Playing);
            }

            if (_game.DrawButtonMethod("SETTINGS", cx, cy + 30, 400, 50))
            {
                _game.previousStateMethod = GameState.Paused;
                _game.SetState(GameState.Settings);
            }

            if (_game.DrawButtonMethod("MAIN MENU", cx, cy + 90, 400, 50))
            {
                _game.ExitGameToMainMenuMethod();
            }
        }
    }
}

