using OpenTK.Windowing.Common;
using OpenTK.Windowing.GraphicsLibraryFramework;
using OpenTK.Mathematics;
using EarthBound.World;
using EarthBound.World.Blocks;
using System;

namespace EarthBound.States
{
    public class InventoryOpenState : IGameState
    {
        private readonly Game _game;

        public InventoryOpenState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
            _game.craftW = 2; // Inventory uses 2x2 craft grid
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
            if (_game.KeyboardState.IsKeyPressed(Keys.E) || _game.KeyboardState.IsKeyPressed(Keys.Escape))
            {
                _game.SetState(GameState.Playing);
                return;
            }

            HandleInventoryInput(false); // false means not workbench
        }

        public void Render(FrameEventArgs args)
        {
            _game.RenderGameMethod();

            _game.uiRenderer.Prepare();
            // Рисуем инвентарь с крафтом 2x2
            _game.uiRenderer.RenderInventory(_game.inventory, _game.selectedHotbarSlot, true, _game.textRenderer, _game.ClientSize.X, _game.ClientSize.Y, _game.globalTextureArray, _game.lastHoverType, _game.lastHoverIdx);

            if (_game.inventory.DragStack != null)
            {
                _game.uiRenderer.RenderDraggedItem(_game.inventory.DragStack, _game.MouseState.Position.X, _game.MouseState.Position.Y, _game.textRenderer, _game.globalTextureArray);
            }
        }

        private void HandleInventoryInput(bool isWorkbench)
        {
            int craftW = isWorkbench ? 3 : 2;
            int craftSize = craftW * craftW;

            float scale = _game.uiRenderer.Scale;
            float slotSize = 18 * scale;

            // 1. Координаты сетки инвентаря
            float gridW = 9 * slotSize;
            float gridH = 3 * slotSize;
            float gridStartX = (_game.Size.X - gridW) / 2;
            float gridStartY = (_game.Size.Y - gridH) / 2 + (20 * scale); // Сдвинули чуть вниз

            // 2. Координаты Хотбара
            float hbY = gridStartY + gridH + (5 * scale);

            // 3. Координаты Крафта
            float totalCraftW = (craftW * slotSize) + (isWorkbench ? (30 * scale) : (25 * scale)); // С учетом стрелки и результата
            float craftX = (_game.Size.X - totalCraftW) / 2;
            float craftY = gridStartY - (craftW * slotSize) - (15 * scale); // Над инвентарем

            // 3. Координаты Результата
            // Если это верстак, стрелка чуть дальше, если инвентарь - ближе
            float arrowXOffset = (isWorkbench) ? (3 * slotSize) + (10 * scale) : (2.5f * slotSize);
            float arrowX = craftX + arrowXOffset;

            float resX = arrowX + (25 * scale);

            // Подгонка высоты
            float resY;
            if (isWorkbench) resY = craftY + (1.0f * slotSize) - (2 * scale);
            else resY = craftY + (0.5f * slotSize) + (2 * scale); // +2 scale matching the render tweak

            // --- ХИТ ТЕСТ (КЛИКИ) ---
            Vector2 m = _game.MouseState.Position;
            int hoveredType = -1; // 0=Inv, 1=Craft, 2=Result
            int hoveredIndex = -1;

            // Inv Main
            for (int i = 9; i < 36; i++)
            {
                int r = (i - 9) / 9; int c = (i - 9) % 9;
                float sx = gridStartX + c * slotSize;
                float sy = gridStartY + r * slotSize;
                if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
            }
            // Inv Hotbar
            for (int i = 0; i < 9; i++)
            {
                float sx = gridStartX + i * slotSize;
                float sy = hbY;
                if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
            }

            // Craft Grid
            for (int y = 0; y < craftW; y++)
            {
                for (int x = 0; x < craftW; x++)
                {
                    int idx = y * craftW + x;
                    float sx = craftX + x * slotSize;
                    float sy = craftY + y * slotSize;
                    if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 1; hoveredIndex = idx; }
                }
            }

            // Result Slot
            if (m.X >= resX && m.X < resX + slotSize && m.Y >= resY && m.Y < resY + slotSize) { hoveredType = 2; hoveredIndex = 0; }

            // --- ЛОГИКА (Нажатия) ---
            bool leftClick = _game.MouseState.IsButtonPressed(MouseButton.Left);
            bool rightClick = _game.MouseState.IsButtonPressed(MouseButton.Right);

            if (leftClick || rightClick)
            {
                if (hoveredType == 0) // Inventory
                {
                    _game.audio.PlayClick(); // ЗВУК ТУТ
                    _game.ProcessSlotClickMethod(_game.inventory.Slots, hoveredIndex, leftClick, rightClick);
                }
                else if (hoveredType == 1) // Crafting
                {
                    _game.audio.PlayClick(); // ЗВУК ТУТ
                    _game.ProcessSlotClickMethod(_game.inventory.CraftingGrid, hoveredIndex, leftClick, rightClick);
                    _game.inventory.CraftResult = CraftingSystem.CheckRecipe(_game.inventory.CraftingGrid, craftW);
                }
                else if (hoveredType == 2 && _game.inventory.CraftResult != null) // Result
                {
                    if (leftClick || rightClick)
                    {
                        _game.audio.PlayClick(); // ЗВУК ТУТ

                        if (_game.inventory.DragStack == null ||
                           (_game.inventory.DragStack.Type == _game.inventory.CraftResult.Type &&
                            _game.inventory.DragStack.Count + _game.inventory.CraftResult.Count <= ItemStack.GetMaxStack(_game.inventory.CraftResult.Type)))
                        {
                            if (_game.inventory.DragStack == null)
                                _game.inventory.DragStack = new ItemStack(_game.inventory.CraftResult.Type, _game.inventory.CraftResult.Count);
                            else
                                _game.inventory.DragStack.Count += _game.inventory.CraftResult.Count;

                            for (int i = 0; i < craftSize; i++)
                            {
                                if (_game.inventory.CraftingGrid[i] != null)
                                {
                                    _game.inventory.CraftingGrid[i].Count--;
                                    if (_game.inventory.CraftingGrid[i].Count <= 0) _game.inventory.CraftingGrid[i] = null;
                                }
                            }

                            _game.inventory.CraftResult = CraftingSystem.CheckRecipe(_game.inventory.CraftingGrid, craftW);
                            _game.audio.PlayPlaceSound(_game.inventory.DragStack.Type, _game.camera.position);
                        }
                    }
                }
            }

            _game.lastHoverType = hoveredType;
            _game.lastHoverIdx = hoveredIndex;
        }
    }
}

using OpenTK.Windowing.Common;
using OpenTK.Windowing.GraphicsLibraryFramework;
using OpenTK.Mathematics;
using EarthBound.World;
using EarthBound.World.Blocks;
using System;

namespace EarthBound.States
{
    public class WorkbenchOpenState : IGameState
    {
        private readonly Game _game;

        public WorkbenchOpenState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
            _game.craftW = 3; // Workbench uses 3x3 craft grid
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
            if (_game.KeyboardState.IsKeyPressed(Keys.E) || _game.KeyboardState.IsKeyPressed(Keys.Escape))
            {
                _game.SetState(GameState.Playing);
                return;
            }

            HandleInventoryInput(true); // true means workbench
        }

        public void Render(FrameEventArgs args)
        {
            _game.RenderGameMethod();

            _game.uiRenderer.Prepare();
            // Рисуем верстак 3x3
            _game.uiRenderer.RenderWorkbench(_game.inventory, _game.textRenderer, _game.ClientSize.X, _game.ClientSize.Y, _game.globalTextureArray, _game.lastHoverType, _game.lastHoverIdx);

            if (_game.inventory.DragStack != null)
            {
                _game.uiRenderer.RenderDraggedItem(_game.inventory.DragStack, _game.MouseState.Position.X, _game.MouseState.Position.Y, _game.textRenderer, _game.globalTextureArray);
            }
        }

        // This method is identical to the one in InventoryOpenState, except for the craftW and craftSize calculation based on isWorkbench.
        // In a real project, this should be shared. For this refactoring, I'll duplicate it to keep states independent for now.
        private void HandleInventoryInput(bool isWorkbench)
        {
            int craftW = isWorkbench ? 3 : 2;
            int craftSize = craftW * craftW;

            float scale = _game.uiRenderer.Scale;
            float slotSize = 18 * scale;

            // 1. Координаты сетки инвентаря
            float gridW = 9 * slotSize;
            float gridH = 3 * slotSize;
            float gridStartX = (_game.Size.X - gridW) / 2;
            float gridStartY = (_game.Size.Y - gridH) / 2 + (20 * scale); // Сдвинули чуть вниз

            // 2. Координаты Хотбара
            float hbY = gridStartY + gridH + (5 * scale);

            // 3. Координаты Крафта
            float totalCraftW = (craftW * slotSize) + (isWorkbench ? (30 * scale) : (25 * scale)); // С учетом стрелки и результата
            float craftX = (_game.Size.X - totalCraftW) / 2;
            float craftY = gridStartY - (craftW * slotSize) - (15 * scale); // Над инвентарем

            // 3. Координаты Результата
            // Если это верстак, стрелка чуть дальше, если инвентарь - ближе
            float arrowXOffset = (isWorkbench) ? (3 * slotSize) + (10 * scale) : (2.5f * slotSize);
            float arrowX = craftX + arrowXOffset;

            float resX = arrowX + (25 * scale);

            // Подгонка высоты
            float resY;
            if (isWorkbench) resY = craftY + (1.0f * slotSize) - (2 * scale);
            else resY = craftY + (0.5f * slotSize) + (2 * scale); // +2 scale matching the render tweak

            // --- ХИТ ТЕСТ (КЛИКИ) ---
            Vector2 m = _game.MouseState.Position;
            int hoveredType = -1; // 0=Inv, 1=Craft, 2=Result
            int hoveredIndex = -1;

            // Inv Main
            for (int i = 9; i < 36; i++)
            {
                int r = (i - 9) / 9; int c = (i - 9) % 9;
                float sx = gridStartX + c * slotSize;
                float sy = gridStartY + r * slotSize;
                if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
            }
            // Inv Hotbar
            for (int i = 0; i < 9; i++)
            {
                float sx = gridStartX + i * slotSize;
                float sy = hbY;
                if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
            }

            // Craft Grid
            for (int y = 0; y < craftW; y++)
            {
                for (int x = 0; x < craftW; x++)
                {
                    int idx = y * craftW + x;
                    float sx = craftX + x * slotSize;
                    float sy = craftY + y * slotSize;
                    if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 1; hoveredIndex = idx; }
                }
            }

            // Result Slot
            if (m.X >= resX && m.X < resX + slotSize && m.Y >= resY && m.Y < resY + slotSize) { hoveredType = 2; hoveredIndex = 0; }

            // --- ЛОГИКА (Нажатия) ---
            bool leftClick = _game.MouseState.IsButtonPressed(MouseButton.Left);
            bool rightClick = _game.MouseState.IsButtonPressed(MouseButton.Right);

            if (leftClick || rightClick)
            {
                if (hoveredType == 0) // Inventory
                {
                    _game.audio.PlayClick(); // ЗВУК ТУТ
                    _game.ProcessSlotClickMethod(_game.inventory.Slots, hoveredIndex, leftClick, rightClick);
                }
                else if (hoveredType == 1) // Crafting
                {
                    _game.audio.PlayClick(); // ЗВУК ТУТ
                    _game.ProcessSlotClickMethod(_game.inventory.CraftingGrid, hoveredIndex, leftClick, rightClick);
                    _game.inventory.CraftResult = CraftingSystem.CheckRecipe(_game.inventory.CraftingGrid, craftW);
                }
                else if (hoveredType == 2 && _game.inventory.CraftResult != null) // Result
                {
                    if (leftClick || rightClick)
                    {
                        _game.audio.PlayClick(); // ЗВУК ТУТ

                        if (_game.inventory.DragStack == null ||
                           (_game.inventory.DragStack.Type == _game.inventory.CraftResult.Type &&
                            _game.inventory.DragStack.Count + _game.inventory.CraftResult.Count <= ItemStack.GetMaxStack(_game.inventory.CraftResult.Type)))
                        {
                            if (_game.inventory.DragStack == null)
                                _game.inventory.DragStack = new ItemStack(_game.inventory.CraftResult.Type, _game.inventory.CraftResult.Count);
                            else
                                _game.inventory.DragStack.Count += _game.inventory.CraftResult.Count;

                            for (int i = 0; i < craftSize; i++)
                            {
                                if (_game.inventory.CraftingGrid[i] != null)
                                {
                                    _game.inventory.CraftingGrid[i].Count--;
                                    if (_game.inventory.CraftingGrid[i].Count <= 0) _game.inventory.CraftingGrid[i] = null;
                                }
                            }

                            _game.inventory.CraftResult = CraftingSystem.CheckRecipe(_game.inventory.CraftingGrid, craftW);
                            _game.audio.PlayPlaceSound(_game.inventory.DragStack.Type, _game.camera.position);
                        }
                    }
                }
            }

            _game.lastHoverType = hoveredType;
            _game.lastHoverIdx = hoveredIndex;
        }
    }
}

using OpenTK.Windowing.Common;
using OpenTK.Mathematics;

namespace EarthBound.States
{
    public class DeadState : IGameState
    {
        private readonly Game _game;

        public DeadState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
        }

        public void Render(FrameEventArgs args)
        {
            _game.uiRenderer.Prepare();
            // Красный полупрозрачный фон
            _game.uiRenderer.DrawRect(0, 0, _game.Size.X, _game.Size.Y, new Vector4(0.6f, 0.1f, 0.1f, 0.5f));

            string title = "YOU DIED!";
            float realW = _game.textRenderer.UpdateText(title) * 2.0f;
            _game.textRenderer.Render((_game.Size.X - realW) / 2, _game.Size.Y / 2 - 100, 2.0f, _game.uiRenderer.GetProjection());

            float cx = (_game.Size.X - 400) / 2;
            float cy = _game.Size.Y / 2;

            if (_game.DrawButtonMethod("RESPAWN", cx, cy, 400, 50))
            {
