using OpenTK.Windowing.Common;

namespace EarthBound.States
{
    public class LoadingState : IGameState
    {
        private readonly Game _game;

        public LoadingState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
        }

        public void Render(FrameEventArgs args)
        {
            _game.uiRenderer.Prepare();
            _game.uiRenderer.DrawTiledBackground(_game.Size.X, _game.Size.Y);
            float p = _game.world.GetLoadingProgress();
            _game.textRenderer.UpdateText($"Loading... {(int)(p * 100)}%");
            _game.textRenderer.Render((_game.Size.X / 2) - 150, (_game.Size.Y / 2) - 50, 0.8f, _game.uiRenderer.GetProjection());
            _game.uiRenderer.RenderLoadingBar(_game.Size.X, _game.Size.Y, p);
        }
    }
}

