using OpenTK.Windowing.Common;
using OpenTK.Windowing.GraphicsLibraryFramework;
using OpenTK.Mathematics;
using EarthBound.World;
using EarthBound.World.Blocks;
using System;
using System.Collections.Generic;

namespace EarthBound.States
{
    public class TomolkaOpenState : IGameState
    {
        private readonly Game _game;

        public TomolkaOpenState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
            if (_game.KeyboardState.IsKeyPressed(Keys.Escape) || _game.KeyboardState.IsKeyPressed(Keys.E))
            {
                _game.SetState(GameState.Playing);
                return;
            }

            UpdateTomolkaLogic(args);
            HandleTomolkaInventoryInput();
        }

        public void Render(FrameEventArgs args)
        {
            _game.RenderGameMethod(); // Render game behind the menu
            RenderTomolkaMenu();
        }

        private void UpdateTomolkaLogic(FrameEventArgs args)
        {
            float dt_t = (float)args.Time;
            if (dt_t > 0.1f) dt_t = 0.1f;
            var mouse_t = _game.MouseState;
            Vector2 mPos = mouse_t.Position;

            float sw = _game.Size.X; float sh = _game.Size.Y;
            float cx = sw / 2; float cy = sh / 2;
            float millRadius = 160f;
            float handleRadius = 25f;

            // 1. АВТО-ЗАГРУЗКА СЕМЯН
            if (_game.tomolkaInput != null && _game.tomolkaInput.Type == BlockType.WHEAT_SEED)
            {
                _game.t_seedsInside += _game.tomolkaInput.Count * 25f;
                _game.tomolkaInput = null;
                _game.audio.PlayPlaceSound(BlockType.DIRT, _game.camera.position);
            }
            else if (_game.tomolkaInput != null)
            {
                _game.world.SpawnItem(_game.camera.position, _game.tomolkaInput.Type, _game.tomolkaInput.Count);
                _game.tomolkaInput = null;
            }

            // 2. ВРАЩЕНИЕ И ИНЕРЦИЯ (УВЕЛИЧЕНО СОПРОТИВЛЕНИЕ)
            Vector2 handlePos = new Vector2(
                cx + MathF.Cos(_game.t_millRotation) * (millRadius - 30f),
                cy + MathF.Sin(_game.t_millRotation) * (millRadius - 30f)
            );

            bool hoverHandle = Vector2.Distance(mPos, handlePos) < handleRadius * 1.5f;

            if (mouse_t.IsButtonPressed(MouseButton.Left) && hoverHandle)
            {
                _game.t_draggingHandle = true;
                _game.t_prevAngle = MathF.Atan2(mPos.Y - cy, mPos.X - cx);
            }
            if (mouse_t.IsButtonReleased(MouseButton.Left)) _game.t_draggingHandle = false;

            if (_game.t_draggingHandle)
            {
                float currAngle = MathF.Atan2(mPos.Y - cy, mPos.X - cx);
                float deltaAngle = currAngle - _game.t_prevAngle;
                if (deltaAngle > MathF.PI) deltaAngle -= 2 * MathF.PI;
                if (deltaAngle < -MathF.PI) deltaAngle += 2 * MathF.PI;

                _game.t_millVelocity = deltaAngle / dt_t;
                _game.t_prevAngle = currAngle;
            }

            // Применяем инерцию и СИЛЬНОЕ трение (0.85f вместо 0.95f)
            _game.t_millRotation += _game.t_millVelocity * dt_t;
            _game.t_millVelocity *= 0.85f;

            float rotationSpeed = MathF.Abs(_game.t_millVelocity);

            // 3. ПОМОЛ МУКИ
            if (rotationSpeed > 0.5f && _game.t_seedsInside > 0)
            {
                float grindAmount = rotationSpeed * dt_t * 12.0f;
                grindAmount = Math.Min(grindAmount, _game.t_seedsInside);

                _game.t_seedsInside -= grindAmount;
                _game.t_flourInside += grindAmount * 0.4f;
                float spillAmount = grindAmount * 0.6f;

                if (spillAmount > 0 && new Random().NextDouble() < 0.4)
                {
                    float spawnAngle = (float)new Random().NextDouble() * MathF.PI * 2;
                    float spawnDist = millRadius + 5f + (float)new Random().NextDouble() * 50f;

                    _game.t_splats.Add(new Game.FlourSplat
                    {
                        Pos = new Vector2(cx + MathF.Cos(spawnAngle) * spawnDist, cy + MathF.Sin(spawnAngle) * spawnDist),
                        Size = 15f + (float)new Random().NextDouble() * 30f,
                        Rotation = (float)new Random().NextDouble() * MathF.PI * 2f,
                        Amount = spillAmount * 4f
                    });
                }

                _game.t_grindSoundTimer -= dt_t;
                if (_game.t_grindSoundTimer <= 0)
                {
                    float pitch = Math.Clamp(0.5f + (rotationSpeed / 15f), 0.6f, 1.8f);
                    float volume = Math.Clamp(rotationSpeed / 10f, 0.1f, 1.0f);
                    _game.audio.PlayUISound("assets/audio/footsteps/stone/1.ogg", pitch, volume * 0.6f);
                    _game.t_grindSoundTimer = 0.25f / Math.Max(1f, rotationSpeed * 0.3f);
                }
            }

            // 4. СБОР МУКИ (СТРОГО ТОЛЬКО В МЕШОК)
            bool isCollecting = mouse_t.IsButtonDown(MouseButton.Left) && !_game.t_draggingHandle;

            // Жесткая проверка: собираем ТОЛЬКО если есть мешок
            bool hasSack = _game.tomolkaOutput != null && _game.tomolkaOutput.Type == BlockType.LEATHER_SACK;
            int spaceLeft = hasSack ? (5700 - _game.tomolkaOutput.Volume) : 0;

            if (isCollecting && hasSack && spaceLeft > 0)
            {
                float mouseSpeed = mouse_t.Delta.Length / dt_t;
                bool collectedSomething = false;

                for (int i = _game.t_splats.Count - 1; i >= 0; i--)
                {
                    var splat = _game.t_splats[i];
                    // Чуть увеличил радиус сбора, чтобы не надо было пиксельхантерством заниматься
                    if (Vector2.Distance(mPos, splat.Pos) < splat.Size + 40f)
                    {
                        float collectRate = 400f * dt_t;
                        float grabbed = Math.Min(collectRate, splat.Amount);
                        grabbed = Math.Min(grabbed, spaceLeft - _game.t_flourFraction);

                        if (grabbed > 0)
                        {
                            splat.Amount -= grabbed;
                            splat.Size -= grabbed * 0.15f;
                            _game.t_flourFraction += grabbed;
                            collectedSomething = true;
                        }

                        if (splat.Amount <= 0 || splat.Size <= 0) _game.t_splats.RemoveAt(i);
                    }
                }

                if (collectedSomething)
                {
                    int wholeFlour = (int)_game.t_flourFraction;
                    if (wholeFlour > 0)
                    {
                        _game.tomolkaOutput.Volume += wholeFlour;
                        _game.t_flourFraction -= wholeFlour;
                    }

                    _game.t_powderSoundTimer -= dt_t;
                    if (_game.t_powderSoundTimer <= 0)
                    {
                        float pitch = Math.Clamp(0.8f + (mouseSpeed / 2000f), 0.8f, 1.5f);
                        float volume = Math.Clamp(mouseSpeed / 800f, 0.2f, 1.0f);
                        _game.audio.PlayUISound("assets/audio/sfx/garden/powder.ogg", pitch, volume);
                        _game.t_powderSoundTimer = 0.4f;
                    }
                }
            }
        }

        private void RenderTomolkaMenu()
        {
            _game.uiRenderer.Prepare();
            float sw = _game.Size.X; float sh = _game.Size.Y;
            float cx = sw / 2; float cy = sh / 2;

            // Размеры основного окна
            float winW = 860; float winH = 540;
            float winX = cx - winW / 2; float winY = cy - winH / 2;

            // Деревянный фон (заменяем menu_bg)
            _game.uiRenderer.RenderQuad(winX, winY, winW, winH, _game.uiRenderer.TexBackground, new Vector3(0.6f), 1.0f, new Vector2(winW / 64f, winH / 64f));

            // Центральная панель-ограничитель
            float panelW = 460; float panelH = 460;
            float panelX = cx - panelW / 2; float panelY = cy - panelH / 2;
            _game.uiRenderer.RenderQuad(panelX, panelY, panelW, panelH, _game.uiRenderer.TexPanelMedium, Vector3.One, 1.0f, new Vector2(1, 1));

            _game.textRenderer.UpdateText("Milstone");
            _game.textRenderer.Render(cx - 70, winY + 25, 0.6f, _game.uiRenderer.GetProjection());

            float slotSize = 80;
            float inX = winX + 70; float inY = cy - slotSize / 2;
            float outX = winX + winW - 70 - slotSize; float outY = cy - slotSize / 2;

            // INPUT
            _game.textRenderer.UpdateText("Input (Seeds)");
            _game.textRenderer.Render(inX - 25, inY - 30, 0.4f, _game.uiRenderer.GetProjection());
            _game.uiRenderer.RenderQuad(inX, inY, slotSize, slotSize, _game.uiRenderer.TexSlot, Vector3.One, 1.0f, new Vector2(1, 1));
            if (_game.tomolkaInput != null)
            {
                _game.uiRenderer.RenderIcon3D(inX + 10, inY + 10, slotSize - 20, _game.tomolkaInput, _game.globalTextureArray);
                _game.textRenderer.UpdateText(_game.tomolkaInput.Count.ToString());
                _game.textRenderer.Render(inX + 5, inY + 5, 0.5f, _game.uiRenderer.GetProjection());
            }

            // OUTPUT (ТЕКСТ ИСПРАВЛЕН)
            _game.textRenderer.UpdateText("Output (Sack)");
            _game.textRenderer.Render(outX - 15, outY - 30, 0.4f, _game.uiRenderer.GetProjection());
            _game.uiRenderer.RenderQuad(outX, outY, slotSize, slotSize, _game.uiRenderer.TexSlot, Vector3.One, 1.0f, new Vector2(1, 1));
            if (_game.tomolkaOutput != null)
            {
                _game.uiRenderer.RenderIcon3D(outX + 10, outY + 10, slotSize - 20, _game.tomolkaOutput, _game.globalTextureArray);
                if (_game.tomolkaOutput.Type == BlockType.LEATHER_SACK)
                {
                    _game.textRenderer.UpdateText($"{_game.tomolkaOutput.Volume}g/5700g");
                    _game.textRenderer.Render(outX - 10, outY + slotSize + 10, 0.35f, _game.uiRenderer.GetProjection());
                }
            }

            // --- MILLSTONE VISUALS ---
            float millRadius = 160f;
            float holeRadius = 35f;

            // 1. Отрисовка блока, на котором стоят жернова (чуть больше самого камня)
            int baseLayer = EarthBound.World.Blocks.BlocksManager.GetBlock(_game.activeTomolkaBaseBlock).GetTextureLayer(Faces.TOP, 0);
            _game.uiRenderer.DrawTexturedCircleArray(cx, cy, millRadius + 15f, _game.globalTextureArray, baseLayer, new Vector3(0.7f), 1.0f);

            // === ЛИМИТ ВЫЛЕТА (ОБРЕЗКА ПИКСЕЛЕЙ) ===
            GL.Enable(EnableCap.ScissorTest);
            int sY = (int)(sh - (panelY + panelH)); // В OpenGL отсчет Y снизу вверх!
            GL.Scissor((int)panelX, sY, (int)panelW, (int)panelH);

            // 2. Брызги муки (пикселями, а не кругами)
            foreach (var splat in _game.t_splats)
            {
                float alpha = Math.Min(1.0f, splat.Amount / 15f);
                int numPixels = (int)splat.Size * 2;

                Random prng = new Random((int)(splat.Pos.X * 1000 + splat.Pos.Y));
                for (int i = 0; i < numPixels; i++)
                {
                    float px = splat.Pos.X + ((float)prng.NextDouble() - 0.5f) * splat.Size;
                    float py = splat.Pos.Y + ((float)prng.NextDouble() - 0.5f) * splat.Size;
                    _game.uiRenderer.DrawRect(px, py, 4f, 4f, new Vector3(0.95f, 0.95f, 0.9f), alpha);
                }
            }
            GL.Disable(EnableCap.ScissorTest); // Отключаем лимит, чтобы рисовать остальное
            // ========================================

            // 3. Millstone Base (shadow)
            _game.uiRenderer.DrawTexturedCircle(cx + 8, cy + 8, millRadius, _game.uiRenderer.TexStone, new Vector3(0.3f), 1.0f, 0f);
            // 4. Millstone Top
            _game.uiRenderer.DrawTexturedCircle(cx, cy, millRadius, _game.uiRenderer.TexStone, Vector3.One, 1.0f, _game.t_millRotation);
            // 5. Center Hole
            _game.uiRenderer.DrawCircle(cx, cy, holeRadius, new Vector3(0.05f), 1.0f);

            if (_game.t_seedsInside > 0)
            {
                float seedRad = Math.Min(holeRadius * 0.9f, (_game.t_seedsInside / 100f) * holeRadius);
                _game.uiRenderer.DrawTexturedCircle(cx, cy, seedRad, _game.uiRenderer.TexSeeds, Vector3.One, 1.0f, _game.t_millRotation * 0.4f);
            }
            if (_game.t_flourInside > 0)
            {
                float flourRad = Math.Min(holeRadius * 0.95f, (_game.t_flourInside / 200f) * holeRadius);
                _game.uiRenderer.DrawTexturedCircle(cx, cy, flourRad, _game.uiRenderer.TexFlour, Vector3.One, 0.9f, -_game.t_millRotation * 0.2f);
            }

            // 6. Handle
            Vector2 handlePos = new Vector2(
                cx + MathF.Cos(_game.t_millRotation) * (millRadius - 30f),
                cy + MathF.Sin(_game.t_millRotation) * (millRadius - 30f)
            );
            _game.uiRenderer.DrawTexturedCircle(handlePos.X + 4, handlePos.Y + 4, 20f, _game.uiRenderer.TexWood, new Vector3(0.3f), 1.0f, _game.t_millRotation);
            _game.uiRenderer.DrawTexturedCircle(handlePos.X, handlePos.Y, 20f, _game.uiRenderer.TexWood, Vector3.One, 1.0f, _game.t_millRotation);

            // --- HUD ---
            float scale = 3.0f;
            float hudW = 182 * scale;
            float hudH = 22 * scale;
            float hudX = cx - hudW / 2;
            float hudY = winY + winH + 10;

            _game.uiRenderer.RenderQuad(hudX, hudY, hudW, hudH, _game.uiRenderer.TexHotbar, Vector3.One, 1.0f, new Vector2(1, 1));
            float selX = hudX + (3 * scale) + (_game.selectedHotbarSlot * 20 * scale);
            float selY = hudY + (3 * scale);
            _game.uiRenderer.DrawRect(selX, selY, 16 * scale, 16 * scale, new Vector3(1, 1, 1), 0.25f);

            for (int i = 0; i < InventorySystem.HOTBAR_SIZE; i++)
            {
                ItemStack stack = _game.inventory.GetStack(i);
                float ix = hudX + (3 * scale) + (i * 20 * scale);
                float iy = hudY + (3 * scale);
                if (stack != null)
                {
                    _game.uiRenderer.RenderIcon3D(ix, iy, 16 * scale, stack, _game.globalTextureArray);
                    if (stack.Count > 1) { _game.textRenderer.UpdateText(stack.Count.ToString()); _game.textRenderer.Render(ix, iy + (8 * scale), 0.5f, _game.uiRenderer.GetProjection()); }
                }
            }

            if (_game.inventory.DragStack != null)
            {
                _game.uiRenderer.RenderDraggedItem(_game.inventory.DragStack, _game.MouseState.Position.X, _game.MouseState.Position.Y, _game.textRenderer, _game.globalTextureArray);
            }
        }

        private void HandleTomolkaInventoryInput()
        {
            float sw = _game.Size.X; float sh = _game.Size.Y;
            float cx = sw / 2; float cy = sh / 2;

            // Новые размеры окна
            float winW = 860; float winH = 540;
            float winX = cx - winW / 2; float winY = cy - winH / 2;

            // Новые позиции слотов
            float slotSize = 80;
            float inX = winX + 70; float inY = cy - slotSize / 2;
            float outX = winX + winW - 70 - slotSize; float outY = cy - slotSize / 2;

            Vector2 m = _game.MouseState.Position;
            int hoveredType = -1;
            int hoveredIndex = -1;

            float scale = 3.0f;
            float hudW = 182 * scale;
            float hudH = 22 * scale;
            float hudX = cx - hudW / 2;
            float hudY = winY + winH + 10; // Под окном


            for (int i = 0; i < 9; i++)
            {
                float sx = hudX + (3 * scale) + (i * 20 * scale);
                if (m.X >= sx && m.X < sx + (16 * scale) && m.Y >= hudY && m.Y < hudY + (16 * scale))
                {
                    hoveredType = 0; hoveredIndex = i;
                }
            }

            if (m.X >= inX && m.X < inX + slotSize && m.Y >= inY && m.Y < inY + slotSize) { hoveredType = 3; hoveredIndex = 0; }
            if (m.X >= outX && m.X < outX + slotSize && m.Y >= outY && m.Y < outY + slotSize) { hoveredType = 4; hoveredIndex = 0; }

            bool leftClick = _game.MouseState.IsButtonPressed(MouseButton.Left);
            bool rightClick = _game.MouseState.IsButtonPressed(MouseButton.Right);

            _game.lastHoverType = hoveredType;
            _game.lastHoverIdx = hoveredIndex;

            if (leftClick || rightClick)
            {
                if (hoveredType == 0)
                {
                    _game.audio.PlayClick();
                    _game.ProcessSlotClickMethod(_game.inventory.Slots, hoveredIndex, leftClick, rightClick);
                }
                else if (hoveredType == 3)
                {
                    _game.audio.PlayClick();
                    ItemStack[] arr = new ItemStack[] { _game.tomolkaInput };
                    _game.ProcessSlotClickMethod(arr, 0, leftClick, rightClick);
                    _game.tomolkaInput = arr[0];
                }
                else if (hoveredType == 4)
                {
                    _game.audio.PlayClick();
                    ItemStack[] arr = new ItemStack[] { _game.tomolkaOutput };
                    _game.ProcessSlotClickMethod(arr, 0, leftClick, rightClick);
                    _game.tomolkaOutput = arr[0];
                }
            }
        }
    }
}

