using OpenTK.Windowing.Common;
using OpenTK.Windowing.GraphicsLibraryFramework;
using OpenTK.Mathematics;
using System;
using System.Collections.Generic;

namespace EarthBound.States
{
    public class MultiplayerMenuState : IGameState
    {
        private readonly Game _game;

        public MultiplayerMenuState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
        }

        public void Render(FrameEventArgs args)
        {
            _game.ApplyPendingServerBrowserResultsMethod();

            _game.uiRenderer.Prepare();
            _game.uiRenderer.DrawTiledBackground(_game.Size.X, _game.Size.Y);
            _game.textRenderer.UpdateText($"Multiplayer  [{_game.localPlayerNickname}]");
            _game.textRenderer.Render((_game.Size.X / 2) - 220, 50, 1.0f, _game.uiRenderer.GetProjection());

            float ly = 150;
            float lw = 700;
            float lx = (_game.Size.X - lw) / 2;

            for (int i = 0; i < _game.multiplayerServers.Count; i++)
            {
                float y = ly + (i * 90);
                ServerBrowserEntry s = _game.multiplayerServers[i];
                bool sel = (i == _game.selectedServerIndex);

                _game.uiRenderer.DrawRect(lx, y, lw, 80, sel ? new Vector3(0.58f, 0.58f, 0.58f) : new Vector3(0.28f, 0.28f, 0.28f), 1.0f);

                float[] iconVerts = {
                    lx + 5,  y + 5,   0, 1, 0,
                    lx + 75, y + 5,   1, 1, 0,
                    lx + 75, y + 75,  1, 0, 0,
                    lx + 5,  y + 75,  0, 0, 0
                };

                _game.uiRenderer.RenderQuadCustomVerts(iconVerts, _game.uiRenderer.TexBackground, new Vector3(0.8f, 0.8f, 0.8f), 1f);

                string name = s.Name.Length > 28 ? s.Name.Substring(0, 28) + "..." : s.Name;
                string line1 = $"{name}";
                string line2 = $"{s.PingMs} ms   {s.PlayerCount} plr   seed {s.Seed}";
                string line3 = $"{s.Host}:{s.Port}   {s.Source}";
                _game.textRenderer.UpdateText($"{line1}\n{line2}\n{line3}");
                _game.textRenderer.Render(lx + 90, y + 10, 0.36f, _game.uiRenderer.GetProjection());

                Vector2 m = _game.MouseState.Position;
                if (m.X >= lx && m.X <= lx + lw && m.Y >= y && m.Y <= y + 80 && _game.MouseState.IsButtonPressed(MouseButton.Left))
                {
                    if (_game.selectedServerIndex == i && (_game.TimeSinceStartMethod() - _game.lastClickTime) < 0.5f) _game.TryJoinSelectedServerMethod();
                    else { _game.selectedServerIndex = i; _game.lastClickTime = _game.TimeSinceStartMethod(); }
                }
            }

            float inputX = lx;
            float inputY = _game.Size.Y - 200;
            float inputW = 420;
            _game.uiRenderer.DrawRect(inputX, inputY, inputW, 50, new Vector3(0f), 0.72f);
            _game.textRenderer.UpdateText("Host:Port  " + _game.manualServerInput + (_game.isTypingManualServer ? "_" : ""));
            _game.textRenderer.Render(inputX + 10, inputY + 12, 0.45f, _game.uiRenderer.GetProjection());

            if (_game.MouseState.IsButtonPressed(MouseButton.Left))
            {
                Vector2 m = _game.MouseState.Position;
                _game.isTypingManualServer = (m.X > inputX && m.X < inputX + inputW && m.Y > inputY && m.Y < inputY + 50);
            }

            if (_game.DrawButtonMethod(_game.isRefreshingServers ? "Refreshing..." : "Refresh", lx + 440, _game.Size.Y - 200, 120, 50) && !_game.isRefreshingServers)
                _game.StartMultiplayerBrowserRefreshMethod();

            if (_game.DrawButtonMethod("Add manually", lx + 580, _game.Size.Y - 200, 180, 50))
            {
                if (!string.IsNullOrWhiteSpace(_game.manualServerInput) && !_game.manualServerEntries.Contains(_game.manualServerInput))
                {
                    _game.manualServerEntries.Add(_game.manualServerInput);
                    _game.StartMultiplayerBrowserRefreshMethod();
                }
            }

            if (_game.DrawButtonMethod("Back", 20, 20, 100, 40)) _game.SetState(GameState.MainMenu);
        }

        public void OnTextInput(TextInputEventArgs e)
        {
            if (_game.isTypingManualServer) _game.manualServerInput += (char)e.Unicode;
        }

        public void OnKeyDown(KeyboardKeyEventArgs e)
        {
            if (e.Key == Keys.Backspace)
            {
                if (_game.isTypingManualServer && _game.manualServerInput.Length > 0)
                    _game.manualServerInput = _game.manualServerInput.Substring(0, _game.manualServerInput.Length - 1);
            }
        }
    }
}

