using OpenTK.Windowing.Common;
using OpenTK.Windowing.GraphicsLibraryFramework;
using OpenTK.Mathematics;
using System;

namespace EarthBound.States
{
    public class CreateWorldState : IGameState
    {
        private readonly Game _game;

        public CreateWorldState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
        }

        public void Render(FrameEventArgs args)
        {
            _game.uiRenderer.Prepare();
            _game.uiRenderer.DrawTiledBackground(_game.Size.X, _game.Size.Y);
            _game.textRenderer.UpdateText("Create World");
            _game.textRenderer.Render((_game.Size.X / 2) - 150, 50, 1.0f, _game.uiRenderer.GetProjection());

            float cx = (_game.Size.X - 400) / 2;
            _game.uiRenderer.DrawRect(cx, 200, 400, 50, new Vector3(0), 0.7f);
            _game.textRenderer.UpdateText(_game.inputWorldName + (_game.isTypingName ? "_" : ""));
            _game.textRenderer.Render(cx + 10, 210, 0.5f, _game.uiRenderer.GetProjection());

            _game.uiRenderer.DrawRect(cx, 300, 400, 50, new Vector3(0), 0.7f);
            _game.textRenderer.UpdateText("Seed: " + _game.inputSeed + (_game.isTypingSeed ? "_" : ""));
            _game.textRenderer.Render(cx + 10, 310, 0.5f, _game.uiRenderer.GetProjection());

            Vector2 m = _game.MouseState.Position;
            if (_game.MouseState.IsButtonPressed(MouseButton.Left))
            {
                _game.isTypingName = (m.X > cx && m.X < cx + 400 && m.Y > 200 && m.Y < 250);
                _game.isTypingSeed = (m.X > cx && m.X < cx + 400 && m.Y > 300 && m.Y < 350);
            }

            if (_game.DrawButtonMethod("Create", cx, 400, 400, 50))
            {
                // СЕКРЕТНАЯ АКТИВАЦИЯ DEV MODE
                if (_game.inputWorldName == "walter" && _game.inputSeed == "water" && !Settings.DevModeEnabled)
                {
                    Settings.DevModeEnabled = true;
                    Settings.Save();
                    _game.inputWorldName = "DevWorld142512r";
                    _game.inputSeed = new Random().Next().ToString();
                    _game.notifSystem.Add("Developer Mode", "Dev Mode Enabled! Press F2 in game.", NotifIcon.Custom);
                }
                else
                {
                    int s = string.IsNullOrEmpty(_game.inputSeed) ? new Random().Next() : (int.TryParse(_game.inputSeed, out int ps) ? ps : _game.inputSeed.GetHashCode());
                    SaveManager.CreateWorld(_game.inputWorldName, s);
                    _game.savedWorlds = SaveManager.GetWorlds();
                    _game.LoadWorldMethod(_game.savedWorlds.Count - 1);
                }
            }
            if (_game.DrawButtonMethod("Cancel", cx, 470, 400, 50)) _game.SetState(GameState.WorldSelect);
        }

        public void OnTextInput(TextInputEventArgs e)
        {
            if (_game.isTypingName) _game.inputWorldName += (char)e.Unicode;
            if (_game.isTypingSeed) _game.inputSeed += (char)e.Unicode;
        }

        public void OnKeyDown(KeyboardKeyEventArgs e)
        {
            if (e.Key == Keys.Backspace)
            {
                if (_game.isTypingName && _game.inputWorldName.Length > 0) _game.inputWorldName = _game.inputWorldName.Substring(0, _game.inputWorldName.Length - 1);
                if (_game.isTypingSeed && _game.inputSeed.Length > 0) _game.inputSeed = _game.inputSeed.Substring(0, _game.inputSeed.Length - 1);
            }
        }
    }
}

