using OpenTK.Windowing.Common;
using OpenTK.Mathematics;
using System;

namespace EarthBound.States
{
    public class SettingsState : IGameState
    {
        private readonly Game _game;

        public SettingsState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
        }

        public void Render(FrameEventArgs args)
        {
            _game.uiRenderer.Prepare();

            // Background rendering based on previous state
            if (_game.previousStateMethod == GameState.MainMenu)
            {
                _game.uiRenderer.DrawTiledBackground(_game.Size.X, _game.Size.Y);
            }
            else
            {
                _game.uiRenderer.DrawRect(0, 0, _game.Size.X, _game.Size.Y, new Vector3(0), 0.7f);
            }

            _game.textRenderer.UpdateText("Settings");
            _game.textRenderer.Render((_game.Size.X / 2) - 100, 30, 1.0f, _game.uiRenderer.GetProjection());

            float padding = 50;
            float leftPanelW = 220;
            float rightPanelX = padding + leftPanelW + 20;
            float rightPanelW = _game.Size.X - rightPanelX - padding;
            float itemY = padding + 80;

            // Left Panel (Tabs)
            _game.uiRenderer.DrawRect(padding, padding + 60, leftPanelW, _game.Size.Y - padding * 2 - 60, new Vector3(0), 0.5f);

            float tabY = padding + 80;
            if (_game.DrawTabButtonMethod("Graphics", padding + 10, tabY, leftPanelW - 20, 40, _game.activeSettingsTab == 0)) _game.activeSettingsTab = 0; tabY += 45;
            if (_game.DrawTabButtonMethod("Window", padding + 10, tabY, leftPanelW - 20, 40, _game.activeSettingsTab == 1)) _game.activeSettingsTab = 1; tabY += 45;
            if (_game.DrawTabButtonMethod("Gameplay", padding + 10, tabY, leftPanelW - 20, 40, _game.activeSettingsTab == 2)) _game.activeSettingsTab = 2; tabY += 45;
            if (_game.DrawTabButtonMethod("Controls", padding + 10, tabY, leftPanelW - 20, 40, _game.activeSettingsTab == 3)) _game.activeSettingsTab = 3; tabY += 45;
            if (_game.DrawTabButtonMethod("Audio", padding + 10, tabY, leftPanelW - 20, 40, _game.activeSettingsTab == 4)) _game.activeSettingsTab = 4; tabY += 45;
            if (_game.DrawTabButtonMethod("UI", padding + 10, tabY, leftPanelW - 20, 40, _game.activeSettingsTab == 5)) _game.activeSettingsTab = 5;

            // Right Panel (Content)
            _game.uiRenderer.DrawRect(rightPanelX, padding + 60, rightPanelW, _game.Size.Y - padding * 2 - 60, new Vector3(0), 0.3f);

            // Bottom Buttons
            if (_game.DrawButtonMethod("Apply", _game.Size.X - 320, _game.Size.Y - 50, 140, 40))
            {
                Settings.Save();
                _game.ApplySettingsLogicMethod();
            }
            if (_game.DrawButtonMethod("Back", _game.Size.X - 160, _game.Size.Y - 50, 140, 40))
            {
                Settings.Save();
                _game.ApplySettingsLogicMethod();
                _game.SetState(_game.previousStateMethod);
            }

            itemY = padding + 80;

            if (_game.activeSettingsTab == 0) // GRAPHICS
            {
                _game.DrawSettingBoxMethod("Render Distance", $"View distance: {Settings.RenderDistance} chunks.", rightPanelX + 30, itemY, rightPanelW - 60, 80);
                _game.DrawSettingSliderMethod(Settings.RenderDistance, Settings.MinRenderDistance, Settings.MaxRenderDistance, rightPanelX + rightPanelW - 250, itemY + 15, true, (v) => Settings.RenderDistance = (int)v);
                itemY += 100;

                _game.DrawSettingBoxMethod("Clouds", "Cloud quality and style", rightPanelX + 30, itemY, rightPanelW - 60, 110);
                float cbX = rightPanelX + 60; float cbY = itemY + 65;
                if (_game.DrawSettingCheckboxMethod("3D Clouds", cbX, cbY, Settings.CloudMode == 2)) Settings.CloudMode = 2;
                if (_game.DrawSettingCheckboxMethod("2D Clouds", cbX + 160, cbY, Settings.CloudMode == 1)) Settings.CloudMode = 1;
                if (_game.DrawSettingCheckboxMethod("Off", cbX + 320, cbY, Settings.CloudMode == 0)) Settings.CloudMode = 0;
                itemY += 125;
            }
            else if (_game.activeSettingsTab == 1) // WINDOW
            {
                string[] winModes = { "Windowed", "Borderless", "Fullscreen" };
                _game.DrawCycleButtonMethod("Mode", winModes, ref Settings.WindowMode, rightPanelX + 30, itemY, 400, 50); itemY += 80;

                string[] resModes = { "800x600", "1280x720", "1600x900", "1920x1080" };
                _game.DrawCycleButtonMethod("Resolution", resModes, ref Settings.ResolutionIndex, rightPanelX + 30, itemY, 400, 50); itemY += 80;

                _game.DrawSettingBoxMethod("Max FPS", $"Current: {(Settings.MaxFPS == 0 ? "Unlimited" : Settings.MaxFPS.ToString())}", rightPanelX + 30, itemY, rightPanelW - 60, 80);
                _game.DrawSettingSliderMethod(Settings.MaxFPS, 0, 240, rightPanelX + rightPanelW - 250, itemY + 15, true, (v) => Settings.MaxFPS = (int)v);
            }
            else if (_game.activeSettingsTab == 2) // GAMEPLAY
            {
                _game.DrawSettingBoxMethod("Field of View", $"FOV: {(int)Settings.FOV}", rightPanelX + 30, itemY, rightPanelW - 60, 80);
                _game.DrawSettingSliderMethod(Settings.FOV, 50f, 120f, rightPanelX + rightPanelW - 250, itemY + 15, true, (v) => Settings.FOV = v); // Разрешили FOV до 120
                itemY += 100;

                _game.DrawSettingBoxMethod("View Bobbing", "Camera sway while walking", rightPanelX + 30, itemY, rightPanelW - 60, 110);
                if (_game.DrawSettingCheckboxMethod("Enable Bobbing", rightPanelX + 60, itemY + 65, Settings.ViewBobbing)) { Settings.ViewBobbing = !Settings.ViewBobbing; Settings.Save(); }
                itemY += 130;
            }
            else if (_game.activeSettingsTab == 3) // CONTROLS
            {
                _game.DrawSettingBoxMethod("Sensitivity", $"Speed: {Settings.Sensitivity:0.0}", rightPanelX + 30, itemY, rightPanelW - 60, 80);
                _game.DrawSettingSliderMethod(Settings.Sensitivity, 0.1f, 2.0f, rightPanelX + rightPanelW - 250, itemY + 15, false, (v) => Settings.Sensitivity = v);
                itemY += 100;

                _game.DrawSettingBoxMethod("Invert Mouse", "Change mouse axis directions", rightPanelX + 30, itemY, rightPanelW - 60, 110);
                if (_game.DrawSettingCheckboxMethod("Invert Y", rightPanelX + 60, itemY + 65, Settings.InvertMouseY)) Settings.InvertMouseY = !Settings.InvertMouseY;
                if (_game.DrawSettingCheckboxMethod("Invert X", rightPanelX + 220, itemY + 65, Settings.InvertMouseX)) Settings.InvertMouseX = !Settings.InvertMouseX;
                itemY += 130;
            }
            else if (_game.activeSettingsTab == 4) // AUDIO
            {
                _game.DrawSettingBoxMethod("Master Volume", $"{(int)(Settings.MasterVolume * 100)}%", rightPanelX + 30, itemY, rightPanelW - 60, 80);
                _game.DrawSettingSliderMethod(Settings.MasterVolume, 0.0f, 1.0f, rightPanelX + rightPanelW - 250, itemY + 15, false, (v) => Settings.MasterVolume = v); itemY += 100;

                _game.DrawSettingBoxMethod("Music Volume", $"{(int)(Settings.MusicVolume * 100)}%", rightPanelX + 30, itemY, rightPanelW - 60, 80);
                _game.DrawSettingSliderMethod(Settings.MusicVolume, 0.0f, 1.0f, rightPanelX + rightPanelW - 250, itemY + 15, false, (v) => Settings.MusicVolume = v); itemY += 100;

                _game.DrawSettingBoxMethod("SFX Volume", $"{(int)(Settings.SoundVolume * 100)}%", rightPanelX + 30, itemY, rightPanelW - 60, 80);
                _game.DrawSettingSliderMethod(Settings.SoundVolume, 0.0f, 1.0f, rightPanelX + rightPanelW - 250, itemY + 15, false, (v) => Settings.SoundVolume = v);
            }
            else if (_game.activeSettingsTab == 5) // UI
            {
                string[] uiScales = new string[] { "Small", "Medium", "Big" };
                _game.DrawCycleButtonMethod("UI Scale", uiScales, ref Settings.UIScaleIndex, rightPanelX + 30, itemY, 400, 50);
            }
        }

        public void OnTextInput(TextInputEventArgs e) { }
        public void OnKeyDown(KeyboardKeyEventArgs e) { }
    }
}

