using OpenTK.Windowing.Common;
using OpenTK.Mathematics;
using OpenTK.Windowing.GraphicsLibraryFramework;
using System;
using System.Collections.Generic;

namespace EarthBound.States
{
    public class LicenseMenuState : IGameState
    {
        private readonly Game _game;

        public LicenseMenuState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
        }

        public void Render(FrameEventArgs args)
        {
            _game.uiRenderer.Prepare();
            _game.uiRenderer.DrawTiledBackground(_game.Size.X, _game.Size.Y);

            // --- ЗАГОЛОВОК ---
            string header = "LICENSES & ATTRIBUTION";
            float headerWidth = _game.textRenderer.UpdateText(header);
            _game.textRenderer.Render((_game.Size.X - headerWidth) / 2, 30, 1.0f, _game.uiRenderer.GetProjection());

            // --- КОНТЕЙНЕР (БОКС) ---
            float boxMarginX = 100;
            float boxTop = 100;
            float boxBottom = 100;

            float boxX = boxMarginX;
            float boxY = boxTop;
            float boxW = _game.Size.X - (boxMarginX * 2);
            float boxH = _game.Size.Y - boxTop - boxBottom;

            _game.uiRenderer.DrawRect(boxX, boxY, boxW, boxH, new Vector3(0, 0, 0), 0.5f);

            // --- СКРОЛЛ ---
            float scrollSpeed = 30f;
            _game.licenseScroll += _game.MouseState.ScrollDelta.Y * scrollSpeed;
            if (_game.licenseScroll > 0) _game.licenseScroll = 0;

            float contentY = boxY + 20 + _game.licenseScroll;
            float contentWidth = boxW - 40;
            float startX = boxX + 20;
            float totalHeight = 20;

            // --- SCISSOR TEST (ОБРЕЗКА) ---
            GL.Enable(EnableCap.ScissorTest);
            int sY = (int)(_game.ClientSize.Y - (boxY + boxH)); // Исправленный расчет Y
            GL.Scissor((int)boxX, sY, (int)boxW, (int)boxH);

            foreach (var file in _game.licenseFiles)
            {
                string[] lines = file.Content.Split('\n');
                float blockHeight = 40 + (lines.Length * 20) + 20;

                // Рисуем только видимое
                if (contentY + blockHeight > boxY && contentY < boxY + boxH)
                {
                    // 1. ЗАГОЛОВОК
                    _game.uiRenderer.DrawRect(startX, contentY, contentWidth, 30, new Vector3(0.3f), 0.9f);
                    _game.textRenderer.UpdateText(file.Name);
                    _game.textRenderer.Render(startX + 10, contentY + 5, 0.4f, _game.uiRenderer.GetProjection());

                    // 2. ФОН ТЕКСТА
                    float bodyHeight = (lines.Length * 20) + 10;
                    _game.uiRenderer.DrawRect(startX, contentY + 30, contentWidth, bodyHeight, new Vector3(0.1f), 0.8f);

                    // 3. ТЕКСТ
                    float textY = contentY + 35;
                    foreach (var line in lines)
                    {
                        if (textY > boxY - 20 && textY < boxY + boxH)
                        {
                            string fittedLine = _game.FitTextToWidthMethod(line, contentWidth - 20, 0.35f);
                            _game.textRenderer.UpdateText(fittedLine);
                            _game.textRenderer.Render(startX + 10, textY, 0.35f, _game.uiRenderer.GetProjection());
                        }
                        textY += 20;
                    }
                }

                contentY += blockHeight;
                totalHeight += blockHeight;
            }

            GL.Disable(EnableCap.ScissorTest);
            // -----------------------------

            // --- ОГРАНИЧЕНИЕ СКРОЛЛА (ВОЗВРАЩЕНО) ---
            float minScroll = -(totalHeight - boxH + 20);
            if (totalHeight < boxH) minScroll = 0;
            if (_game.licenseScroll < minScroll) _game.licenseScroll = minScroll;

            // --- КНОПКА BACK (ВОЗВРАЩЕНА) ---
            if (_game.DrawButtonMethod("Back", (_game.Size.X - 200) / 2, _game.Size.Y - 100, 200, 50))
            {
                _game.SetState(GameState.MainMenu);
            }
        }

        public void OnTextInput(TextInputEventArgs e) { }
        public void OnKeyDown(KeyboardKeyEventArgs e) { }
    }
}

