using OpenTK.Windowing.Common;
using OpenTK.Windowing.GraphicsLibraryFramework;

namespace EarthBound.States
{
    public class UIRedactorState : IGameState
    {
        private readonly Game _game;

        public UIRedactorState(Game game)
        {
            _game = game;
        }

        public void Enter()
        {
            _game.CursorState = CursorState.Normal;
        }

        public void Exit()
        {
        }

        public void Update(FrameEventArgs args)
        {
        }

        public void Render(FrameEventArgs args)
        {
            _game.uiEditor.UpdateAndRender(_game.uiRenderer, _game.textRenderer, _game.globalTextureArray, _game.Size.X, _game.Size.Y, (float)args.Time);
        }

        public void OnTextInput(TextInputEventArgs e)
        {
            _game.uiEditor.ProcessTextInput((char)e.Unicode);
        }

        public void OnKeyDown(KeyboardKeyEventArgs e)
        {
            if (e.Key == Keys.Backspace)
            {
                _game.uiEditor.ProcessBackspace();
            }
            if (e.Key == Keys.Delete)
            {
                _game.uiEditor.DeleteSelected(); // Удаление на кнопку Delete
            }
        }
    }
}

