1013         public void ProcessSlotClickMethod(ItemStack[] array, int idx, bool left, bool right)
1014             ItemStack slot = array[idx];
1015             ItemStack hand = inventory.DragStack;
1016 
1017             if (isLeft)
1018             {
1019                 // ЛКМ: Свап / Взять / Положить всё
1020                 if (hand == null && slot != null)
1021                 {
1022                     inventory.DragStack = slot;
1023                     array[idx] = null;
1024                 }
1025                 else if (hand != null && slot == null)
1026                 {
1027                     array[idx] = hand;
1028                     inventory.DragStack = null;
1029                 }
1030                 else if (hand != null && slot != null)
1031                 {
1032                     if (hand.Type == slot.Type)
1033                     {
1034                         int space = ItemStack.GetMaxStack(slot.Type) - slot.Count;
1035                         int toAdd = Math.Min(space, hand.Count);
1036                         slot.Count += toAdd;
1037                         hand.Count -= toAdd;
1038                         if (hand.Count <= 0) inventory.DragStack = null;
1039                     }
1040                     else
1041                     {
1042                         // Swap
1043                         array[idx] = hand;
1044                         inventory.DragStack = slot;
1045                     }
1046                 }
1047             }
1048             else if (isRight)
1049             {
1050                 // ПКМ
1051                 if (hand == null && slot != null)
1052                 {
1053                     // Взять половину
1054                     int take = (int)Math.Ceiling(slot.Count / 2.0);
1055                     inventory.DragStack = new ItemStack(slot.Type, take);
1056                     slot.Count -= take;
1057                     if (slot.Count <= 0) array[idx] = null;
1058                 }
1059                 else if (hand != null)
1060                 {
1061                     // Положить ОДИН
1062                     if (slot == null)
1063                     {
1064                         array[idx] = new ItemStack(hand.Type, 1);
1065                         hand.Count--;
1066                         if (hand.Count <= 0) inventory.DragStack = null;
1067                     }
1068                     else if (slot.Type == hand.Type && slot.Count < ItemStack.GetMaxStack(slot.Type))
1069                     {
1070                         slot.Count++;
1071                         hand.Count--;
1072                         if (hand.Count <= 0) inventory.DragStack = null;
1073                     }
1074                 }
1075             }
1076         }
