 790         public void ProcessSlotClickMethod(ItemStack[] array, int idx, bool left, bool right)
 791             ItemStack slot = array[idx];
 792             ItemStack hand = inventory.DragStack;
 793 
 794             if (isLeft)
 795             {
 796                 // ЛКМ: Свап / Взять / Положить всё
 797                 if (hand == null && slot != null)
 798                 {
 799                     inventory.DragStack = slot;
 800                     array[idx] = null;
 801                 }
 802                 else if (hand != null && slot == null)
 803                 {
 804                     array[idx] = hand;
 805                     inventory.DragStack = null;
 806                 }
 807                 else if (hand != null && slot != null)
 808                 {
 809                     if (hand.Type == slot.Type)
 810                     {
 811                         int space = ItemStack.GetMaxStack(slot.Type) - slot.Count;
 812                         int toAdd = Math.Min(space, hand.Count);
 813                         slot.Count += toAdd;
 814                         hand.Count -= toAdd;
 815                         if (hand.Count <= 0) inventory.DragStack = null;
 816                     }
 817                     else
 818                     {
 819                         // Swap
 820                         array[idx] = hand;
 821                         inventory.DragStack = slot;
 822                     }
 823                 }
 824             }
 825             else if (isRight)
 826             {
 827                 // ПКМ
 828                 if (hand == null && slot != null)
 829                 {
 830                     // Взять половину
 831                     int take = (int)Math.Ceiling(slot.Count / 2.0);
 832                     inventory.DragStack = new ItemStack(slot.Type, take);
 833                     slot.Count -= take;
 834                     if (slot.Count <= 0) array[idx] = null;
 835                 }
 836                 else if (hand != null)
 837                 {
 838                     // Положить ОДИН
