 934         private void RenderSelectionOutline(Vector3i pos)
 935         {
 936             BlockType type = world.GetBlock(new Vector3(pos.X, pos.Y, pos.Z));
 937             byte data = world.GetBlockData(pos);
 938             var boxes = EarthBound.World.Blocks.BlocksManager.GetBlock(type).GetBoundingBoxes(data);
 939 
 940             if (type == BlockType.SNOW_LAYER)
 941             {
 942                 int layers = (data & 7) + 1;
 943                 boxes.Clear();
 944                 boxes.Add(new AABB(new Vector3(-0.5f, -0.5f, -0.5f), new Vector3(0.5f, -0.5f + (layers * 0.125f), 0.5f)));
 945             }
 946 
 947             if (boxes.Count == 0) return;
 948 
 949             List<Vector3> verts = new List<Vector3>();
 950             float expand = 0.002f;
 951 
 952             foreach (var box in boxes)
 953             {
 954                 float x1 = pos.X + box.Min.X - expand;
 955                 float y1 = pos.Y + box.Min.Y - expand;
 956                 float z1 = pos.Z + box.Min.Z - expand;
 957                 float x2 = pos.X + box.Max.X + expand;
 958                 float y2 = pos.Y + box.Max.Y + expand;
 959                 float z2 = pos.Z + box.Max.Z + expand;
 960 
 961                 // Линии каркаса
 962                 Vector3 p1 = new Vector3(x1, y1, z1); Vector3 p2 = new Vector3(x2, y1, z1);
 963                 Vector3 p3 = new Vector3(x2, y1, z2); Vector3 p4 = new Vector3(x1, y1, z2);
 964                 Vector3 p5 = new Vector3(x1, y2, z1); Vector3 p6 = new Vector3(x2, y2, z1);
 965                 Vector3 p7 = new Vector3(x2, y2, z2); Vector3 p8 = new Vector3(x1, y2, z2);
 966 
 967                 verts.AddRange(new[] { p1, p2, p2, p3, p3, p4, p4, p1 }); // Низ
 968                 verts.AddRange(new[] { p5, p6, p6, p7, p7, p8, p8, p5 }); // Верх
 969                 verts.AddRange(new[] { p1, p5, p2, p6, p3, p7, p4, p8 }); // Стойки
 970             }
 971 
 972             shader.Bind();
 973             GL.Uniform4(GL.GetUniformLocation(shader.ID, "overlayColor"), new Vector4(0, 0, 0, 1));
 974 
 975             outlineVAO.Bind();
 976             GL.BindBuffer(BufferTarget.ArrayBuffer, outlineVBO.ID);
 977             GL.BufferData(BufferTarget.ArrayBuffer, verts.Count * Vector3.SizeInBytes, verts.ToArray(), BufferUsageHint.StreamDraw);
 978 
 979             Matrix4 model = Matrix4.Identity;
 980             GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "model"), true, ref model);
 981 
 982             GL.LineWidth(2.5f);
 983             GL.DrawArrays(PrimitiveType.Lines, 0, verts.Count);
 984             GL.LineWidth(1.0f);
 985 
 986             outlineVAO.Unbind();
 987             GL.Uniform4(GL.GetUniformLocation(shader.ID, "overlayColor"), Vector4.Zero);
 988         }
