1324         private void PerformSaveAndExit()
1325         {
1326             // Очищаем GPU буферы сущностей и предметов перед удалением мира
1327             if (world != null)
1328             {
1329                 foreach (var item in world.ItemEntities) item.Delete();
1330                 foreach (var ent in world.Entities)
1331                 {
1332                     if (ent is SlimeEntity slime) slime.Delete();
1333                     else if (ent is TntEntity tnt) tnt.Delete();
1334                     else if (ent is FallingBlockEntity fb) fb.Delete();
1335                     else if (ent is PigEntity pig) pig.Delete();
1336                 }
1337             }
1338 
1339             if (isMultiplayerSession)
1340             {
1341                 multiplayerClient?.Dispose();
1342                 multiplayerClient = null;
1343                 isMultiplayerSession = false;
1344             }
1345             else if (world != null && !string.IsNullOrEmpty(currentWorldFolder))
1346             {
1347                 GL.Clear(ClearBufferMask.ColorBufferBit | ClearBufferMask.DepthBufferBit);
1348                 shader.Bind();
1349 
1350                 Vector3 eyePos = camera.GetEyePosition();
1351                 bool underwater = world != null && world.IsWater(eyePos.X, eyePos.Y, eyePos.Z);
1352 
1353                 GL.Uniform3(
1354                     GL.GetUniformLocation(shader.ID, "fogColor"),
1355                     underwater
1356                         ? new Vector3(0, 0.1f, 0.4f)
1357                         : new Vector3(0.5f, 0.7f, 1f)
1358                 );
1359 
1360                 GL.Uniform1(
1361                     GL.GetUniformLocation(shader.ID, "fogDensity"),
1362         public void OpenMultiplayerMenuMethod()
1363                 );
1364 
1365                 Matrix4 model = Matrix4.Identity;
1366                 Matrix4 view = camera.GetViewMatrix();
1367                 Matrix4 projection = camera.GetProjectionMatrix();
1368 
1369                 GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "model"), true, ref model);
1370                 GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "view"), true, ref view);
1371                 GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "projection"), true, ref projection);
1372 
1373                 Matrix4 viewProj = view * projection;
1374                 world.RenderSolid(shader, viewProj, camera.position, globalTextureArray, hzbManager);
1375                 world.RenderTransparent(shader, viewProj, camera.position, globalTextureArray, hzbManager);
1376 
1377 
1378                 SaveManager.CaptureIcon(currentWorldFolder, Size.X, Size.Y);
1379 
1380                 PlayerData pd = new PlayerData();
