1394 
1395                 Console.WriteLine($"[GAME] Saving world to: {currentWorldFolder}");
1396                 world.SaveWorld(currentWorldFolder);
1397 
1398                 SaveManager.UpdateWorldData(currentWorldFolder, savedWorlds[selectedWorldIndex].Name, currentSeed, worldTime.CurrentTime, worldTime);
1399             }
1400 
