1434         private void RenderBreakOverlay(Vector3i pos, int stage)
1435         {
1436             if (stage < 0 || stage >= TextureData.BreakLayerIndices.Count) return;
1437             int layer = TextureData.BreakLayerIndices[stage];
1438 
1439             BlockType type = world.GetBlock(new Vector3(pos.X, pos.Y, pos.Z));
1440             byte data = world.GetBlockData(pos);
1441             var boxes = EarthBound.World.Blocks.BlocksManager.GetBlock(type).GetBoundingBoxes(data);
1442 
1443             if (type == BlockType.SNOW_LAYER)
1444             {
1445                 int layers = (data & 7) + 1;
1446                 boxes.Clear();
1447                 boxes.Add(new AABB(new Vector3(-0.5f, -0.5f, -0.5f), new Vector3(0.5f, -0.5f + (layers * 0.125f), 0.5f)));
1448             }
1449 
1450             List<Vector3> verts = new List<Vector3>();
1451             List<Vector3> uvs = new List<Vector3>();
1452             List<Vector3> colors = new List<Vector3>();
1453             List<Vector2> lights = new List<Vector2>();
1454 
1455             float expand = 0.003f;
1456 
1457             foreach (var box in boxes)
1458             {
1459                 float x1 = pos.X + box.Min.X - expand; float y1 = pos.Y + box.Min.Y - expand; float z1 = pos.Z + box.Min.Z - expand;
1460                 float x2 = pos.X + box.Max.X + expand; float y2 = pos.Y + box.Max.Y + expand; float z2 = pos.Z + box.Max.Z + expand;
1461 
1462                 // Добавляем 6 граней для каждой коробки
1463                 AddCrackFace(verts, uvs, x1, y1, z2, x2, y1, z2, x2, y2, z2, x1, y2, z2, layer); // Front
1464                 AddCrackFace(verts, uvs, x2, y1, z1, x1, y1, z1, x1, y2, z1, x2, y2, z1, layer); // Back
1465                 AddCrackFace(verts, uvs, x1, y1, z1, x1, y1, z2, x1, y2, z2, x1, y2, z1, layer); // Left
1466                 AddCrackFace(verts, uvs, x2, y1, z2, x2, y1, z1, x2, y2, z1, x2, y2, z2, layer); // Right
1467                 AddCrackFace(verts, uvs, x1, y2, z2, x2, y2, z2, x2, y2, z1, x1, y2, z1, layer); // Top
1468                 AddCrackFace(verts, uvs, x1, y1, z1, x2, y1, z1, x2, y1, z2, x1, y1, z2, layer); // Bottom
1469             }
1470 
1471             for (int i = 0; i < verts.Count; i++) { colors.Add(Vector3.One); lights.Add(new Vector2(15, 15)); }
1472 
1473             crackVAO.Bind();
1474             GL.BindBuffer(BufferTarget.ArrayBuffer, crackVBO.ID);
1475             GL.BufferData(BufferTarget.ArrayBuffer, verts.Count * Vector3.SizeInBytes, verts.ToArray(), BufferUsageHint.StreamDraw);
1476             GL.BindBuffer(BufferTarget.ArrayBuffer, crackUV.ID);
1477             GL.BufferData(BufferTarget.ArrayBuffer, uvs.Count * Vector3.SizeInBytes, uvs.ToArray(), BufferUsageHint.StreamDraw);
1478             GL.BindBuffer(BufferTarget.ArrayBuffer, crackColor.ID);
1479             GL.BufferData(BufferTarget.ArrayBuffer, colors.Count * Vector3.SizeInBytes, colors.ToArray(), BufferUsageHint.StreamDraw);
1480             GL.BindBuffer(BufferTarget.ArrayBuffer, crackLight.ID);
1481             GL.BufferData(BufferTarget.ArrayBuffer, lights.Count * Vector2.SizeInBytes, lights.ToArray(), BufferUsageHint.StreamDraw);
1482 
1483             shader.Bind();
1484             Matrix4 model = Matrix4.Identity;
1485             GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "model"), true, ref model);
1486             globalTextureArray.Bind();
1487             GL.Uniform1(GL.GetUniformLocation(shader.ID, "isCrack"), 1);
1488 
1489             GL.DrawArrays(PrimitiveType.Triangles, 0, verts.Count);
1490 
1491             crackVAO.Unbind();
1492             GL.Uniform1(GL.GetUniformLocation(shader.ID, "isCrack"), 0);
1493         }
