1495         private void AddCrackFace(List<Vector3> v, List<Vector3> uv, float x1, float y1, float z1, float x2, float y2, float z2, float x3, float y3, float z3, float x4, float y4, float z4, int layer)
1496         {
1497             v.Add(new Vector3(x1, y1, z1)); uv.Add(new Vector3(0, 0, layer));
1498             v.Add(new Vector3(x2, y2, z2)); uv.Add(new Vector3(1, 0, layer));
1499             v.Add(new Vector3(x3, y3, z3)); uv.Add(new Vector3(1, 1, layer));
1500 
1501             v.Add(new Vector3(x3, y3, z3)); uv.Add(new Vector3(1, 1, layer));
1502             v.Add(new Vector3(x4, y4, z4)); uv.Add(new Vector3(0, 1, layer));
1503             v.Add(new Vector3(x1, y1, z1)); uv.Add(new Vector3(0, 0, layer));
1504         }
