1511         private string FitTextToWidth(string text, float maxWidth, float scale)
1512         {
1513             if (string.IsNullOrEmpty(text)) return "";
1514 
1515             // Примерная ширина одного символа (зависит от шрифта TextRenderer)
1516             // У нас моноширинный шрифт, базовая ширина ~14-15 пикселей.
1517             float charWidth = 15.0f * scale;
1518 
1519             int maxChars = (int)(maxWidth / charWidth);
1520 
1521             if (text.Length <= maxChars) return text;
1522 
1523             // Если текст длиннее, обрезаем и добавляем "..."
1524             return text.Substring(0, Math.Max(0, maxChars - 3)) + "...";
1525         }
