1646         public void HandleLeftClick(float dt)
1647         {
1648             if (handSwing == 0) handSwing = 1.0f;
1649 
1650             // Логика зажигалки
1651             ItemStack held = inventory.GetStack(selectedHotbarSlot);
1652 
1653             // This part was inside IsButtonPressed, but HandleLeftClick is called when IsButtonDown.
1654             // I need to check if it was just pressed for the lighter logic.
1655             if (MouseState.IsButtonPressed(MouseButton.Left))
1656             {
1657                 if (held != null)
1658                 {
1659                     if (held.Type == BlockType.LIGHTER) { held.Type = BlockType.LIGHTER_ON; audio.PlayPlaceSound(BlockType.IRON_ORE, camera.position); return; }
1660                     else if (held.Type == BlockType.LIGHTER_ON) { held.Type = BlockType.LIGHTER; audio.PlayPlaceSound(BlockType.IRON_ORE, camera.position); return; }
1661                 }
1662 
1663                 // === COMBAT: БЬЁМ СУЩНОСТЕЙ ===
1664                 bool entityHit = false;
1665                 foreach (var ent in world.Entities)
1666                 {
1667                     if (ent is SlimeEntity slime && !slime.IsDead) // Проверяем слайма
1668                     {
1669                         Vector3 toEnt = slime.Position - camera.position;
1670                         float dist = toEnt.Length;
1671                         if (dist < 4.0f) // Радиус удара
1672                         {
1673                             toEnt.Normalize();
1674                             float dot = Vector3.Dot(camera.Front, toEnt);
1675                             if (dot > 0.85f) // Если смотрим прямо на него
1676                             {
1677                                 if (slime.HurtTimer <= 0)
1678                                 {
1679                                     slime.Health -= 5.0f; // Урон 5 ХП (всего 15)
1680                                     slime.HurtTimer = 0.5f; // Отключаем урон на 0.5 сек, заодно триггерим моргание
1681                                                             // ОТБРАСЫВАНИЕ!
1682                                     slime.Velocity = camera.Front * 5.0f + new Vector3(0, 5.0f, 0);
1683 
1684                                     audio.PlayHitSound("grass", slime.Position); // Шлепающий звук
1685 
1686                                     entityHit = true;
1687 
1688                                     if (slime.Health <= 0)
1689                                     {
1690                                         slime.IsDead = true;
1691                                         // Дроп с моба
1692                                         world.SpawnItem(slime.Position, BlockType.MUSHROOM_RED, 1);
1693                                         world.SpawnItem(slime.Position + new Vector3(0, 0.5f, 0), BlockType.MUSHROOM_BROWN, 1);
1694                                     }
1695                                 }
1696                             }
1697                         }
1698                     }
1699                 }
1700 
1701                 // Если мы кого-то ударили - мы не ломаем блоки в этот клик
1702                 if (entityHit) return;
1703             }
1704 
1705             RaycastResult hit = Physics.Raycast(camera.GetEyePosition(), camera.Front, 5.0f, world);
1706 
1707             if (hit.Hit)
1708             {
1709                 BlockType targetType = world.GetBlock(new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z));
1710 
1711                 // Тушим огонь сразу
1712                 if (targetType == BlockType.FIRE)
1713                 {
1714                     world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z, BlockType.AIR);
1715                     audio.PlayFootstep("grass", camera.position);
1716                     isBreaking = false;
1717                 }
1718                 else
1719                 {
1720                     // Обычное ломание
1721                     if (!isBreaking || breakingTarget != hit.BlockPos)
1722                     {
1723                         isBreaking = true;
1724                         breakingTarget = hit.BlockPos;
1725                         breakingTimer = 0;
1726                         hitSoundTimer = 0;
1727                     }
1728 
1729                     // ИСПОЛЬЗУЕМ НОВЫЙ МЕНЕДЖЕР
1730                     float hardness = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).Hardness;
1731                     ItemStack heldItem = inventory.GetStack(selectedHotbarSlot);
1732                     BlockType toolType = (heldItem != null) ? heldItem.Type : BlockType.AIR;
1733 
1734                     // Используем локальный метод (мы его добавили скриптом)
1735                     float speedMultiplier = GetMiningSpeed(toolType, targetType);
1736 
1737                     breakingTimer += dt * speedMultiplier;
1738                     // --- ЧАСТИЦЫ ПРЯМО ВО ВРЕМЯ ЛОМАНИЯ БЛОКА ---
1739                     if (new Random().NextDouble() < 0.35)
1740                     {
1741                         int layer = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).GetTextureLayer(Faces.FRONT, 0);
1742                         Vector3 blockColor = Vector3.One;
1743 
1744                         if (targetType == BlockType.GRASS || targetType == BlockType.LEAVES) blockColor = new Vector3(0.4f, 0.8f, 0.3f);
1745 
1746                         // ФИКС ЦЕНТРА: Убрали + 0.5f
1747                         Vector3 spawnPos = new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z)
1748                                            + new Vector3(hit.FaceNormal.X, hit.FaceNormal.Y, hit.FaceNormal.Z) * 0.5f;
1749 
1750                         particleEmitter.EmitDebris(spawnPos, layer, blockColor, 3);
1751                     }
1752 
1753                     hitSoundTimer -= dt;
1754                     if (hitSoundTimer <= 0)
1755                     {
1756                         string mat = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).SoundCategory;
1757                         // ФИКС ЦЕНТРА: Убрали + 0.5f
1758                         Vector3 hitPos = new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z);
1759                         audio.PlayHitSound(mat, hitPos);
1760                         hitSoundTimer = 0.25f;
1761                     }
1762 
1763                     if (breakingTimer >= hardness)
1764                     {
1765                         // --- ЛОГИКА МУЛЬТИ-БЛОКОВ (ЕЛКА) ---
1766                         if (targetType == BlockType.CHRISTMAS_TREE)
1767                         {
1768                             byte data = world.GetBlockData(hit.BlockPos);
1769                             if (data == 0) world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y + 1, hit.BlockPos.Z, BlockType.AIR);
1770                             else if (data == 1) world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y - 1, hit.BlockPos.Z, BlockType.AIR);
1771                         }
1772                         byte wData = 0;
1773                         if (targetType == BlockType.WHEAT_BLOCK) wData = world.GetBlockData(hit.BlockPos);
1774 
1775                         // --- BLOCK BREAK PARTICLES ---
1776                         int layer = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).GetTextureLayer(Faces.FRONT, 0);
1777                         Vector3 blockColor = Vector3.One;
1778                         if (targetType == BlockType.GRASS || targetType == BlockType.LEAVES) blockColor = new Vector3(0.4f, 0.8f, 0.3f);
1779 
1780                         // ФИКС ЦЕНТРА: Передаем точные координаты без смещений
1781                         Vector3 exactCenter = new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z);
1782                         particleEmitter.EmitBlockBreak(exactCenter, layer, blockColor);
1783 
1784                         // ТЕПЕРЬ УДАЛЯЕМ БЛОК
1785                         world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z, BlockType.AIR);
1786 
1787                         // --- NEW DROP LOGIC ---
1788                         BlockType dropType = targetType;
1789                         int dropCount = 1;
1790 
1791                         if (targetType == BlockType.COAL_ORE) dropType = BlockType.COAL;
1792                         else if (targetType == BlockType.DIAMOND_ORE) dropType = BlockType.DIAMOND;
1793                         else if (targetType == BlockType.IRON_ORE) dropType = BlockType.IRON_INGOT;
