1796                         else if (targetType == BlockType.TALL_GRASS || targetType == BlockType.TALL_GRASS_TOP)
1797                         {
1798                             dropType = BlockType.AIR; // Блок травы никогда не выпадает!
1799                                                       // Даем 10% шанс выбить семена пшеницы
1800                             if (new Random().NextDouble() < 0.1)
1801                                 world.SpawnItem(exactCenter, BlockType.WHEAT_SEED, 1);
1802                         }
1803                         else if (targetType == BlockType.GRASS || targetType == BlockType.FARMLAND)
1804                         {
