1103         private void PerformSaveAndExit()
1104         {
1105             // Очищаем GPU буферы сущностей и предметов перед удалением мира
1106             if (world != null)
1107             {
1108                 foreach (var item in world.ItemEntities) item.Delete();
1109                 foreach (var ent in world.Entities)
1110                 {
1111                     if (ent is SlimeEntity slime) slime.Delete();
1112                     else if (ent is TntEntity tnt) tnt.Delete();
1113                     else if (ent is FallingBlockEntity fb) fb.Delete();
1114                     else if (ent is PigEntity pig) pig.Delete();
1115                 }
1116             }
1117 
1118             if (isMultiplayerSession)
1119             {
1120                 multiplayerClient?.Dispose();
1121                 multiplayerClient = null;
1122                 isMultiplayerSession = false;
1123             }
1124             else if (world != null && !string.IsNullOrEmpty(currentWorldFolder))
1125             {
1126                 GL.Clear(ClearBufferMask.ColorBufferBit | ClearBufferMask.DepthBufferBit);
1127                 shader.Bind();
1128 
1129                 Vector3 eyePos = camera.GetEyePosition();
1130                 bool underwater = world != null && world.IsWater(eyePos.X, eyePos.Y, eyePos.Z);
1131 
1132                 GL.Uniform3(
1133                     GL.GetUniformLocation(shader.ID, "fogColor"),
1134                     underwater
1135                         ? new Vector3(0, 0.1f, 0.4f)
1136                         : new Vector3(0.5f, 0.7f, 1f)
1137                 );
1138 
1139                 GL.Uniform1(
1140                     GL.GetUniformLocation(shader.ID, "fogDensity"),
1141         public void OpenMultiplayerMenuMethod()
1142                 );
1143 
1144                 Matrix4 model = Matrix4.Identity;
1145                 Matrix4 view = camera.GetViewMatrix();
1146                 Matrix4 projection = camera.GetProjectionMatrix();
1147 
1148                 GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "model"), true, ref model);
1149                 GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "view"), true, ref view);
1150                 GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "projection"), true, ref projection);
1151 
1152                 Matrix4 viewProj = view * projection;
1153                 world.RenderSolid(shader, viewProj, camera.position, globalTextureArray, hzbManager);
1154                 world.RenderTransparent(shader, viewProj, camera.position, globalTextureArray, hzbManager);
1155 
1156 
1157                 SaveManager.CaptureIcon(currentWorldFolder, Size.X, Size.Y);
1158 
1159                 PlayerData pd = new PlayerData();
1160                 // --- SAVE BURNING STATE ---
1161                 pd.SetFromGame(camera, inventory, isBurning, burnTimer);
1162 
1163                 if (CurrentState == GameState.Dead)
1164                 {
1165                     Vector3 bodyPos = camera.GetPositionForSave(true);
1166                     pd.X = camera.position.X + world.GlobalOrigin.X;
1167                     pd.Y = camera.position.Y;
1168                     pd.Z = camera.position.Z + world.GlobalOrigin.Z;
