1175                 world.SaveWorld(currentWorldFolder);
1176 
1177                 SaveManager.UpdateWorldData(currentWorldFolder, savedWorlds[selectedWorldIndex].Name, currentSeed, worldTime.CurrentTime, worldTime);
1178             }
