1213         private void RenderBreakOverlay(Vector3i pos, int stage)
1214         {
1215             if (stage < 0 || stage >= TextureData.BreakLayerIndices.Count) return;
1216             int layer = TextureData.BreakLayerIndices[stage];
1217 
1218             BlockType type = world.GetBlock(new Vector3(pos.X, pos.Y, pos.Z));
1219             byte data = world.GetBlockData(pos);
1220             var boxes = EarthBound.World.Blocks.BlocksManager.GetBlock(type).GetBoundingBoxes(data);
1221 
1222             if (type == BlockType.SNOW_LAYER)
1223             {
1224                 int layers = (data & 7) + 1;
1225                 boxes.Clear();
1226                 boxes.Add(new AABB(new Vector3(-0.5f, -0.5f, -0.5f), new Vector3(0.5f, -0.5f + (layers * 0.125f), 0.5f)));
1227             }
1228 
1229             List<Vector3> verts = new List<Vector3>();
1230             List<Vector3> uvs = new List<Vector3>();
1231             List<Vector3> colors = new List<Vector3>();
1232             List<Vector2> lights = new List<Vector2>();
1233 
1234             float expand = 0.003f;
1235 
1236             foreach (var box in boxes)
1237             {
1238                 float x1 = pos.X + box.Min.X - expand; float y1 = pos.Y + box.Min.Y - expand; float z1 = pos.Z + box.Min.Z - expand;
1239                 float x2 = pos.X + box.Max.X + expand; float y2 = pos.Y + box.Max.Y + expand; float z2 = pos.Z + box.Max.Z + expand;
1240 
1241                 // Добавляем 6 граней для каждой коробки
1242                 AddCrackFace(verts, uvs, x1, y1, z2, x2, y1, z2, x2, y2, z2, x1, y2, z2, layer); // Front
1243                 AddCrackFace(verts, uvs, x2, y1, z1, x1, y1, z1, x1, y2, z1, x2, y2, z1, layer); // Back
1244                 AddCrackFace(verts, uvs, x1, y1, z1, x1, y1, z2, x1, y2, z2, x1, y2, z1, layer); // Left
1245                 AddCrackFace(verts, uvs, x2, y1, z2, x2, y1, z1, x2, y2, z1, x2, y2, z2, layer); // Right
1246                 AddCrackFace(verts, uvs, x1, y2, z2, x2, y2, z2, x2, y2, z1, x1, y2, z1, layer); // Top
1247                 AddCrackFace(verts, uvs, x1, y1, z1, x2, y1, z1, x2, y1, z2, x1, y1, z2, layer); // Bottom
1248             }
1249 
1250             for (int i = 0; i < verts.Count; i++) { colors.Add(Vector3.One); lights.Add(new Vector2(15, 15)); }
1251 
1252             crackVAO.Bind();
1253             GL.BindBuffer(BufferTarget.ArrayBuffer, crackVBO.ID);
1254             GL.BufferData(BufferTarget.ArrayBuffer, verts.Count * Vector3.SizeInBytes, verts.ToArray(), BufferUsageHint.StreamDraw);
1255             GL.BindBuffer(BufferTarget.ArrayBuffer, crackUV.ID);
1256             GL.BufferData(BufferTarget.ArrayBuffer, uvs.Count * Vector3.SizeInBytes, uvs.ToArray(), BufferUsageHint.StreamDraw);
1257             GL.BindBuffer(BufferTarget.ArrayBuffer, crackColor.ID);
1258             GL.BufferData(BufferTarget.ArrayBuffer, colors.Count * Vector3.SizeInBytes, colors.ToArray(), BufferUsageHint.StreamDraw);
1259             GL.BindBuffer(BufferTarget.ArrayBuffer, crackLight.ID);
1260             GL.BufferData(BufferTarget.ArrayBuffer, lights.Count * Vector2.SizeInBytes, lights.ToArray(), BufferUsageHint.StreamDraw);
1261 
1262             shader.Bind();
1263             Matrix4 model = Matrix4.Identity;
1264             GL.UniformMatrix4(GL.GetUniformLocation(shader.ID, "model"), true, ref model);
1265             globalTextureArray.Bind();
1266             GL.Uniform1(GL.GetUniformLocation(shader.ID, "isCrack"), 1);
1267 
1268             GL.DrawArrays(PrimitiveType.Triangles, 0, verts.Count);
1269 
1270             crackVAO.Unbind();
1271             GL.Uniform1(GL.GetUniformLocation(shader.ID, "isCrack"), 0);
1272         }
