1290         private string FitTextToWidth(string text, float maxWidth, float scale)
1291         {
1292             if (string.IsNullOrEmpty(text)) return "";
1293 
1294             // Примерная ширина одного символа (зависит от шрифта TextRenderer)
1295             // У нас моноширинный шрифт, базовая ширина ~14-15 пикселей.
1296             float charWidth = 15.0f * scale;
1297 
1298             int maxChars = (int)(maxWidth / charWidth);
1299 
1300             if (text.Length <= maxChars) return text;
1301 
1302             // Если текст длиннее, обрезаем и добавляем "..."
1303             return text.Substring(0, Math.Max(0, maxChars - 3)) + "...";
1304         }
