1425         public void HandleLeftClick(float dt)
1426         {
1427             if (handSwing == 0) handSwing = 1.0f;
1428 
1429             // Логика зажигалки
1430             ItemStack held = inventory.GetStack(selectedHotbarSlot);
1431 
1432             // This part was inside IsButtonPressed, but HandleLeftClick is called when IsButtonDown.
1433             // I need to check if it was just pressed for the lighter logic.
1434             if (MouseState.IsButtonPressed(MouseButton.Left))
1435             {
1436                 if (held != null)
1437                 {
1438                     if (held.Type == BlockType.LIGHTER) { held.Type = BlockType.LIGHTER_ON; audio.PlayPlaceSound(BlockType.IRON_ORE, camera.position); return; }
1439                     else if (held.Type == BlockType.LIGHTER_ON) { held.Type = BlockType.LIGHTER; audio.PlayPlaceSound(BlockType.IRON_ORE, camera.position); return; }
1440                 }
1441 
1442                 // === COMBAT: БЬЁМ СУЩНОСТЕЙ ===
1443                 bool entityHit = false;
1444                 foreach (var ent in world.Entities)
1445                 {
1446                     if (ent is SlimeEntity slime && !slime.IsDead) // Проверяем слайма
1447                     {
1448                         Vector3 toEnt = slime.Position - camera.position;
1449                         float dist = toEnt.Length;
1450                         if (dist < 4.0f) // Радиус удара
1451                         {
1452                             toEnt.Normalize();
1453                             float dot = Vector3.Dot(camera.Front, toEnt);
1454                             if (dot > 0.85f) // Если смотрим прямо на него
1455                             {
1456                                 if (slime.HurtTimer <= 0)
1457                                 {
1458                                     slime.Health -= 5.0f; // Урон 5 ХП (всего 15)
1459                                     slime.HurtTimer = 0.5f; // Отключаем урон на 0.5 сек, заодно триггерим моргание
1460                                                             // ОТБРАСЫВАНИЕ!
1461                                     slime.Velocity = camera.Front * 5.0f + new Vector3(0, 5.0f, 0);
1462 
1463                                     audio.PlayHitSound("grass", slime.Position); // Шлепающий звук
1464 
1465                                     entityHit = true;
1466 
1467                                     if (slime.Health <= 0)
1468                                     {
1469                                         slime.IsDead = true;
1470                                         // Дроп с моба
1471                                         world.SpawnItem(slime.Position, BlockType.MUSHROOM_RED, 1);
1472                                         world.SpawnItem(slime.Position + new Vector3(0, 0.5f, 0), BlockType.MUSHROOM_BROWN, 1);
1473                                     }
1474                                 }
1475                             }
1476                         }
1477                     }
1478                 }
1479 
1480                 // Если мы кого-то ударили - мы не ломаем блоки в этот клик
1481                 if (entityHit) return;
1482             }
1483 
1484             RaycastResult hit = Physics.Raycast(camera.GetEyePosition(), camera.Front, 5.0f, world);
1485 
1486             if (hit.Hit)
1487             {
1488                 BlockType targetType = world.GetBlock(new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z));
1489 
1490                 // Тушим огонь сразу
1491                 if (targetType == BlockType.FIRE)
1492                 {
1493                     world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z, BlockType.AIR);
1494                     audio.PlayFootstep("grass", camera.position);
1495                     isBreaking = false;
1496                 }
1497                 else
1498                 {
1499                     // Обычное ломание
1500                     if (!isBreaking || breakingTarget != hit.BlockPos)
1501                     {
1502                         isBreaking = true;
1503                         breakingTarget = hit.BlockPos;
1504                         breakingTimer = 0;
1505                         hitSoundTimer = 0;
1506                     }
1507 
1508                     // ИСПОЛЬЗУЕМ НОВЫЙ МЕНЕДЖЕР
1509                     float hardness = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).Hardness;
1510                     ItemStack heldItem = inventory.GetStack(selectedHotbarSlot);
1511                     BlockType toolType = (heldItem != null) ? heldItem.Type : BlockType.AIR;
1512 
1513                     // Используем локальный метод (мы его добавили скриптом)
1514                     float speedMultiplier = GetMiningSpeed(toolType, targetType);
1515 
1516                     breakingTimer += dt * speedMultiplier;
1517                     // --- ЧАСТИЦЫ ПРЯМО ВО ВРЕМЯ ЛОМАНИЯ БЛОКА ---
1518                     if (new Random().NextDouble() < 0.35)
1519                     {
1520                         int layer = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).GetTextureLayer(Faces.FRONT, 0);
1521                         Vector3 blockColor = Vector3.One;
1522 
1523                         if (targetType == BlockType.GRASS || targetType == BlockType.LEAVES) blockColor = new Vector3(0.4f, 0.8f, 0.3f);
1524 
1525                         // ФИКС ЦЕНТРА: Убрали + 0.5f
1526                         Vector3 spawnPos = new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z)
1527                                            + new Vector3(hit.FaceNormal.X, hit.FaceNormal.Y, hit.FaceNormal.Z) * 0.5f;
1528 
1529                         particleEmitter.EmitDebris(spawnPos, layer, blockColor, 3);
1530                     }
1531 
1532                     hitSoundTimer -= dt;
1533                     if (hitSoundTimer <= 0)
1534                     {
1535                         string mat = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).SoundCategory;
1536                         // ФИКС ЦЕНТРА: Убрали + 0.5f
1537                         Vector3 hitPos = new Vector3(hit.BlockPos.X, hit.BlockPos.Y, hit.BlockPos.Z);
1538                         audio.PlayHitSound(mat, hitPos);
1539                         hitSoundTimer = 0.25f;
1540                     }
1541 
1542                     if (breakingTimer >= hardness)
1543                     {
1544                         // --- ЛОГИКА МУЛЬТИ-БЛОКОВ (ЕЛКА) ---
1545                         if (targetType == BlockType.CHRISTMAS_TREE)
1546                         {
1547                             byte data = world.GetBlockData(hit.BlockPos);
1548                             if (data == 0) world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y + 1, hit.BlockPos.Z, BlockType.AIR);
1549                             else if (data == 1) world.SetBlock(hit.BlockPos.X, hit.BlockPos.Y - 1, hit.BlockPos.Z, BlockType.AIR);
1550                         }
1551                         byte wData = 0;
1552                         if (targetType == BlockType.WHEAT_BLOCK) wData = world.GetBlockData(hit.BlockPos);
1553 
1554                         // --- BLOCK BREAK PARTICLES ---
1555                         int layer = EarthBound.World.Blocks.BlocksManager.GetBlock(targetType).GetTextureLayer(Faces.FRONT, 0);
1556                         Vector3 blockColor = Vector3.One;
1557                         if (targetType == BlockType.GRASS || targetType == BlockType.LEAVES) blockColor = new Vector3(0.4f, 0.8f, 0.3f);
