269         private static WindowIcon LoadWindowIcon(string path)
270         {
271             if (!File.Exists(path))
272             {
273                 Console.WriteLine($"[ICON ERROR] Файл не найден: {path}");
274                 return null;
275             }
276 
277             try
278             {
279                 // Используем System.Drawing.Bitmap (он умеет читать .ico)
280                 using (var bitmap = new System.Drawing.Bitmap(path))
281                 {
282                     // Блокируем биты изображения для чтения
283                     var data = bitmap.LockBits(
284                         new System.Drawing.Rectangle(0, 0, bitmap.Width, bitmap.Height),
285                         System.Drawing.Imaging.ImageLockMode.ReadOnly,
286                         System.Drawing.Imaging.PixelFormat.Format32bppArgb);
287 
288                     int byteCount = data.Stride * data.Height;
289                     byte[] bytes = new byte[byteCount];
290 
291                     // Копируем сырые байты из Bitmap в массив
292                     System.Runtime.InteropServices.Marshal.Copy(data.Scan0, bytes, 0, byteCount);
293 
294                     bitmap.UnlockBits(data);
295 
296                     // ВАЖНО: System.Drawing грузит как BGRA, а OpenTK нужно RGBA.
297                     // Меняем местами Синий (B) и Красный (R) каналы.
298                     for (int i = 0; i < bytes.Length; i += 4)
299                     {
300                         byte b = bytes[i];
301                         byte r = bytes[i + 2];
302 
303                         bytes[i] = r;     // R
304                         bytes[i + 2] = b; // B
305                     }
306 
307                     // Создаем картинку для OpenTK
308                     var iconImage = new OpenTK.Windowing.Common.Input.Image(bitmap.Width, bitmap.Height, bytes);
309                     return new WindowIcon(iconImage);
310                 }
311             }
312             catch (Exception e)
313             {
314                 Console.WriteLine($"[ICON ERROR] Ошибка загрузки иконки: {e.Message}");
315                 return null;
316             }
317         }
