319         private void RenderPerfOverlay()
320         {
321             if (world == null) return;
322 
323             // Обновляем строки только раз в 10 кадров — рендер каждый кадр, текст нет
324             _perfOverlayFrame++;
325             bool refresh = (_perfOverlayFrame % 10 == 0);
326 
327             float sw = Size.X;
328             float panelW = 420f;
329             float panelX = sw - panelW - 10f;
330             float panelY = 10f;
331             float lineH = 34f;
332             float textScale = 0.38f;
333 
334             var proj = uiRenderer.GetProjection(); // один раз
335 
336             int totalLines = 16;
337             float totalH = totalLines * lineH + 16f;
