371             ("Frustum cull", $"{_perfCullingMs:0.00} ms",     ColorFor(_perfCullingMs,     1f,    3f,    6f)),
372             ("Terrain gen",  $"{_perfTerrainGenMs:0.00} ms",  ColorFor(_perfTerrainGenMs,  50f,   150f,  300f)),
373             ("Lighting",     $"{_perfLightMs:0.00} ms",       ColorFor(_perfLightMs,       30f,   100f,  200f)),
374             ("Mesh build",   $"{_perfMeshMs:0.00} ms",        ColorFor(_perfMeshMs,        20f,   80f,   200f)),
375             ("Render (CPU)", $"{_perfRenderMs:0.00} ms",      ColorFor(_perfRenderMs,      8f,    16f,   33f)),
376             ("---", "", Vector3.Zero),
377             ($"FPS: {fps}  Chunks: {world.ActiveChunksList.Count}/{world.Chunks.Count}", "", Vector3.One),
378             ($"DrawCalls  solid:{_perfDrawCallsSolid}  water:{_perfDrawCallsWater}", "", Vector3.One),
379             ($"Threads  gen:{world.DbgActiveGen}  remesh:{world.DbgActiveRemesh}", "", Vector3.One),
380             ($"Upload avg:{world._avgUploadMs:0.00}ms  max/frame:{world._maxUploadsPerFrame}", "", Vector3.One),
381             ($"Server {serverDbg.Mode}  ticks:{serverDbg.TickCount}  in:{serverDbg.ProcessedIncomingPackets}", "", Vector3.One),
382             ($"Net tx/rx client:{serverDbg.ClientConnection.PacketsSent}/{serverDbg.ClientConnection.PacketsReceived} server:{serverDbg.ServerConnection.PacketsSent}/{serverDbg.ServerConnection.PacketsReceived}", "", Vector3.One),
383                 };
384             }
385 
386             float valX = panelX + panelW - 115f;
387             foreach (var (text, val, col) in _perfLines)
388             {
389                 if (text == "---")
390                 {
391                     uiRenderer.DrawRect(panelX, curY + lineH * 0.4f, panelW, 1,
392                         new Vector3(0.4f, 0.4f, 0.4f), 0.8f);
393                     curY += lineH * 0.6f;
394                     continue;
395                 }
396 
397                 textRenderer.UpdateText(text);
398                 textRenderer.Render(panelX + 4, curY, textScale, proj);
399 
400                 if (val != "")
401                 {
402                     uiRenderer.DrawRect(valX - 16, curY + 3, 10, 16, col, 1f);
403                     textRenderer.UpdateText(val);
404                     textRenderer.Render(valX, curY, textScale, proj);
405                 }
406 
407                 curY += lineH;
408             }
409         }
