411         private void RenderFrameGraph()
412         {
413             uiRenderer.Prepare();
414 
415             float barWidth = 4.0f;
416             float startX = 20.0f;
417             float startY = Size.Y - 40.0f; // Рисуем снизу вверх
418             float scaleY = 3.0f; // 1 миллисекунда = 3 пикселя на экране
419 
420             // Фон графика
421             uiRenderer.DrawRect(startX - 5, startY - (50 * scaleY), (GRAPH_SIZE * barWidth) + 10, (50 * scaleY) + 5, new Vector3(0, 0, 0), 0.6f);
422 
423             for (int i = 0; i < GRAPH_SIZE; i++)
424             {
425                 int idx = (historyIndex + i) % GRAPH_SIZE;
426                 float upd = historyUpdate[idx];
427                 float rnd = historyRender[idx];
428 
429                 float x = startX + (i * barWidth);
430 
431                 // Защита от слишком длинных полосок
432                 if (upd > 50f) upd = 50f;
433                 if (rnd > 50f) rnd = 50f;
434 
435                 // Синяя полоска - Update (Логика)
436                 float hUpd = upd * scaleY;
437                 uiRenderer.DrawRect(x, startY - hUpd, barWidth - 1, hUpd, new Vector3(0.2f, 0.4f, 1.0f), 1.0f);
438 
439                 // Красная полоска - Render (Отрисовка) ставится поверх синей
440                 float hRnd = rnd * scaleY;
441                 uiRenderer.DrawRect(x, startY - hUpd - hRnd, barWidth - 1, hRnd, new Vector3(1.0f, 0.2f, 0.2f), 1.0f);
442             }
443 
444             // Рисуем линию 60 FPS (16.6 мс)
445             float y60 = startY - (16.6f * scaleY);
446             uiRenderer.DrawRect(startX, y60, GRAPH_SIZE * barWidth, 2, new Vector3(0.0f, 1.0f, 0.0f), 0.8f);
447 
448             // Рисуем линию 30 FPS (33.3 мс)
449             float y30 = startY - (33.3f * scaleY);
450             uiRenderer.DrawRect(startX, y30, GRAPH_SIZE * barWidth, 2, new Vector3(1.0f, 1.0f, 0.0f), 0.8f);
451 
452             // Текст-пояснения
453             textRenderer.UpdateText("60 FPS");
454             textRenderer.Render(startX + (GRAPH_SIZE * barWidth) + 10, y60 - 8, 0.3f, uiRenderer.GetProjection());
455 
456             textRenderer.UpdateText("30 FPS");
457             textRenderer.Render(startX + (GRAPH_SIZE * barWidth) + 10, y30 - 8, 0.3f, uiRenderer.GetProjection());
458         }
459         private Vector3 FindSafeSpawn()
460         {
461             // Ищем по спирали от центра мира
462             for (int radius = 0; radius < 100; radius += 4)
463             {
464                 for (int x = -radius; x <= radius; x += 4)
465                 {
466                     for (int z = -radius; z <= radius; z += 4)
467                     {
468                         // Ищем только по периметру текущего квадрата
469                         if (Math.Abs(x) != radius && Math.Abs(z) != radius) continue;
470 
471                         // Сканируем высоту (начиная выше уровня моря!)
472                         for (int y = 120; y > TerrainGenerator.OceanLevel; y--)
473                         {
474                             BlockType b = world.GetBlock(new Vector3(x, y, z));
475                             // Ищем твердый блок
476                             if (b != BlockType.AIR && b != BlockType.WATER && b != BlockType.LEAVES && b != BlockType.LOG)
477                             {
478                                 BlockType up1 = world.GetBlock(new Vector3(x, y + 1, z));
479                                 BlockType up2 = world.GetBlock(new Vector3(x, y + 2, z));
480 
481                                 // Если над нами 2 блока воздуха — место найдено!
482                                 if (up1 == BlockType.AIR && up2 == BlockType.AIR)
483                                 {
484                                     return new Vector3(x + 0.5f, y + 1.5f, z + 0.5f);
485                                 }
486                             }
487                         }
488                     }
489                 }
490             }
491             // Если вся загруженная зона — море, спавним высоко, парашют спасет
492             return new Vector3(0.5f, 100f, 0.5f);
493         }
