703         protected override void OnUpdateFrame(FrameEventArgs args)
704         {
705             frameTimer.Restart();
706             base.OnUpdateFrame(args);
707             // --- FLOATING ORIGIN (ПЛАВАЮЩАЯ ТОЧКА ОТСЧЕТА) ---
708             if (world != null && (CurrentState == GameState.Playing || CurrentState == GameState.DevMenu || isDebugCam))
709             {
710                 Vector3i shift = Vector3i.Zero;
711                 int limit = 2000; // Уходим дальше 2000 - возвращаем мир в центр
712 
713                 if (camera.position.X > limit) shift.X = limit;
714                 else if (camera.position.X < -limit) shift.X = -limit;
715 
716                 if (camera.position.Z > limit) shift.Z = limit;
717                 else if (camera.position.Z < -limit) shift.Z = -limit;
718 
719                 if (shift != Vector3i.Zero)
720                 {
721                     camera.position -= new Vector3(shift.X, 0, shift.Z);
722                     camera.ResetFallState();
723                     if (isDebugCam) debugCamera.position -= new Vector3(shift.X, 0, shift.Z);
724 
725                     world.ShiftOrigin(shift);
726                     weatherRenderer.ResetParticles();
727                     cloudRenderer.CloudOffset.X -= shift.X;
728                     cloudRenderer.CloudOffset.Y -= shift.Z;
729                 }
730             }
731             bool isMenu = (CurrentState != GameState.Playing && CurrentState != GameState.Paused && CurrentState != GameState.InventoryOpen && CurrentState != GameState.Dead);
732             audio.UpdateMusic((float)args.Time, isMenu, Settings.MusicVolume);
733 
734             // --- TICK SYSTEM LOGIC (С ЗАЩИТОЙ ОТ СПИРАЛИ СМЕРТИ) ---
735             accumulatedTime += args.Time;
736 
737             // ФИКС: Если игра зависла (например, при загрузке или из-за винды), 
738             // не пытаемся просчитать 500 тиков за раз. Сбрасываем лишнее время!
739             if (accumulatedTime > 0.5)
740             {
741                 accumulatedTime = 0.5; // Максимум 10 тиков за один кадр
742             }
743 
744             while (accumulatedTime >= TIME_PER_TICK)
745             {
746                 GameTick();
747                 accumulatedTime -= TIME_PER_TICK;
748             }
749 
750             // Подсчет FPS и TPS
751             oneSecondTimer += args.Time;
752             frames++;
753             if (oneSecondTimer >= 1.0)
754             {
755                 fps = frames;
756                 tps = tickCounter;
757 
758                 // ВОЗВРАЩАЕМ ВЫВОД В КОНСОЛЬ
759                 double avgUpdate = frames > 0 ? totalUpdateTimeMs / frames : 0;
760                 double avgRender = frames > 0 ? totalRenderTimeMs / frames : 0;
761                 // Записываем статистику в advanced_log.txt раз в 5 сек
762                 EarthBound.Diagnostics.AdvancedProfiler.Update(fps, tps, camera.position);
763                 Console.WriteLine($"[PERFORMANCE] FPS: {fps} | TPS: {tps} | Update: {avgUpdate:0.00}ms | Render(CPU): {avgRender:0.00}ms");
764 
765                 totalUpdateTimeMs = 0;
766                 totalRenderTimeMs = 0;
767             // --- INPUT MANAGEMENT ---
768             _inputManager.Update((float)args.Time);
769             {
770                 camera.position = new Vector3(camera.position.X, 240, camera.position.Z);
771                 camera.velocity = Vector3.Zero;
772                 camera.ResetFallState();
773                 isBurning = false;
774                 burnTimer = 0;
775             }
776 
777 
778             float dt = (float)args.Time;
779             _lastDt = dt;
780             multiplayerClient?.Pump();
781 
782 
783             _gameStateManager.Update(args);
784         }
