319         private void RenderPerfOverlay()
320         {
321             if (world == null) return;
322 
323             // Обновляем строки только раз в 10 кадров — рендер каждый кадр, текст нет
324             _perfOverlayFrame++;
325             bool refresh = (_perfOverlayFrame % 10 == 0);
326 
327             float sw = Size.X;
328             float panelW = 420f;
329             float panelX = sw - panelW - 10f;
330             float panelY = 10f;
331             float lineH = 34f;
332             float textScale = 0.38f;
333 
334             var proj = uiRenderer.GetProjection(); // один раз
335 
336             int totalLines = 16;
337             float totalH = totalLines * lineH + 16f;
338 
339             uiRenderer.Prepare();
340             uiRenderer.DrawRect(panelX - 8, panelY - 6, panelW + 16, totalH,
341                 new Vector3(0f, 0f, 0f), 0.72f);
342 
343             float curY = panelY + 4f;
344 
345             // Заголовок — всегда
346             textRenderer.UpdateText("── PERF OVERLAY (F7) ──");
347             textRenderer.Render(panelX + 4, curY, 0.40f, proj);
348             curY += lineH;
349 
350             Vector3 ColorFor(double ms, float g, float y, float r)
351             {
352                 if (ms <= g) return new Vector3(0.2f, 1f, 0.3f);
353                 if (ms <= y) return new Vector3(1f, 0.85f, 0.1f);
354                 if (ms <= r) return new Vector3(1f, 0.3f, 0.1f);
355                 return new Vector3(0.5f, 0.5f, 0.5f);
356             }
357 
358             // Если надо обновить — пересобираем кэш строк
359             if (refresh || _perfLines == null)
360             {
361                 ServerDebugSnapshot serverDbg = gameServer != null
362                     ? gameServer.GetDebugSnapshot()
363                     : new ServerDebugSnapshot("None", 0, 0, 0, "-", "-", "-", "-", default, default);
364 
365                 _perfLines = new (string text, string val, Vector3 col)[]
366                 {
367             ("Frame total",  $"{_perfFrameMs:0.00} ms",       ColorFor(_perfFrameMs,       16.6f, 33.3f, 50f)),
368             ("Update logic", $"{_perfUpdateMs:0.00} ms",      ColorFor(_perfUpdateMs,      10f,   20f,   33f)),
369             ("Chunk update", $"{_perfChunkUpdateMs:0.00} ms", ColorFor(_perfChunkUpdateMs, 3f,    8f,    15f)),
370             ("GL Upload",    $"{_perfUploadMs:0.00} ms",      ColorFor(_perfUploadMs,      2f,    5f,    10f)),
371             ("Frustum cull", $"{_perfCullingMs:0.00} ms",     ColorFor(_perfCullingMs,     1f,    3f,    6f)),
372             ("Terrain gen",  $"{_perfTerrainGenMs:0.00} ms",  ColorFor(_perfTerrainGenMs,  50f,   150f,  300f)),
373             ("Lighting",     $"{_perfLightMs:0.00} ms",       ColorFor(_perfLightMs,       30f,   100f,  200f)),
374             ("Mesh build",   $"{_perfMeshMs:0.00} ms",        ColorFor(_perfMeshMs,        20f,   80f,   200f)),
375             ("Render (CPU)", $"{_perfRenderMs:0.00} ms",      ColorFor(_perfRenderMs,      8f,    16f,   33f)),
376             ("---", "", Vector3.Zero),
377             ($"FPS: {fps}  Chunks: {world.ActiveChunksList.Count}/{world.Chunks.Count}", "", Vector3.One),
378             ($"DrawCalls  solid:{_perfDrawCallsSolid}  water:{_perfDrawCallsWater}", "", Vector3.One),
379             ($"Threads  gen:{world.DbgActiveGen}  remesh:{world.DbgActiveRemesh}", "", Vector3.One),
380             ($"Upload avg:{world._avgUploadMs:0.00}ms  max/frame:{world._maxUploadsPerFrame}", "", Vector3.One),
381             ($"Server {serverDbg.Mode}  ticks:{serverDbg.TickCount}  in:{serverDbg.ProcessedIncomingPackets}", "", Vector3.One),
382             ($"Net tx/rx client:{serverDbg.ClientConnection.PacketsSent}/{serverDbg.ClientConnection.PacketsReceived} server:{serverDbg.ServerConnection.PacketsSent}/{serverDbg.ServerConnection.PacketsReceived}", "", Vector3.One),
383                 };
