459         private Vector3 FindSafeSpawn()
460         {
461             // Ищем по спирали от центра мира
462             for (int radius = 0; radius < 100; radius += 4)
463             {
464                 for (int x = -radius; x <= radius; x += 4)
465                 {
466                     for (int z = -radius; z <= radius; z += 4)
467                     {
468                         // Ищем только по периметру текущего квадрата
469                         if (Math.Abs(x) != radius && Math.Abs(z) != radius) continue;
470 
471                         // Сканируем высоту (начиная выше уровня моря!)
472                         for (int y = 120; y > TerrainGenerator.OceanLevel; y--)
473                         {
474                             BlockType b = world.GetBlock(new Vector3(x, y, z));
475                             // Ищем твердый блок
476                             if (b != BlockType.AIR && b != BlockType.WATER && b != BlockType.LEAVES && b != BlockType.LOG)
477                             {
478                                 BlockType up1 = world.GetBlock(new Vector3(x, y + 1, z));
479                                 BlockType up2 = world.GetBlock(new Vector3(x, y + 2, z));
480 
481                                 // Если над нами 2 блока воздуха — место найдено!
482                                 if (up1 == BlockType.AIR && up2 == BlockType.AIR)
483                                 {
484                                     return new Vector3(x + 0.5f, y + 1.5f, z + 0.5f);
485                                 }
486                             }
487                         }
488                     }
489                 }
490             }
491             // Если вся загруженная зона — море, спавним высоко, парашют спасет
492             return new Vector3(0.5f, 100f, 0.5f);
493         }
