320         private Vector3 FindSafeSpawn()
321         {
322             // Ищем по спирали от центра мира
323             for (int radius = 0; radius < 100; radius += 4)
324             {
325                 for (int x = -radius; x <= radius; x += 4)
326                 {
327                     for (int z = -radius; z <= radius; z += 4)
328                     {
329                         // Ищем только по периметру текущего квадрата
330                         if (Math.Abs(x) != radius && Math.Abs(z) != radius) continue;
331 
332                         // Сканируем высоту (начиная выше уровня моря!)
333                         for (int y = 120; y > TerrainGenerator.OceanLevel; y--)
334                         {
335                             BlockType b = world.GetBlock(new Vector3(x, y, z));
336                             // Ищем твердый блок
337                             if (b != BlockType.AIR && b != BlockType.WATER && b != BlockType.LEAVES && b != BlockType.LOG)
338                             {
339                                 BlockType up1 = world.GetBlock(new Vector3(x, y + 1, z));
340                                 BlockType up2 = world.GetBlock(new Vector3(x, y + 2, z));
341 
342                                 // Если над нами 2 блока воздуха — место найдено!
343                                 if (up1 == BlockType.AIR && up2 == BlockType.AIR)
344                                 {
345                                     return new Vector3(x + 0.5f, y + 1.5f, z + 0.5f);
346                                 }
347                             }
348                         }
349                     }
350                 }
351             }
352             // Если вся загруженная зона — море, спавним высоко, парашют спасет
353             return new Vector3(0.5f, 100f, 0.5f);
354         }
