 54         // This method is identical to the one in InventoryOpenState, except for the craftW and craftSize calculation based on isWorkbench.
 55         // In a real project, this should be shared. For this refactoring, I'll duplicate it to keep states independent for now.
 56         private void HandleInventoryInput(bool isWorkbench)
 57         {
 58             int craftW = isWorkbench ? 3 : 2;
 59             int craftSize = craftW * craftW;
 60 
 61             float scale = _game.uiRenderer.Scale;
 62             float slotSize = 18 * scale;
 63 
 64             // 1. Координаты сетки инвентаря
 65             float gridW = 9 * slotSize;
 66             float gridH = 3 * slotSize;
 67             float gridStartX = (_game.Size.X - gridW) / 2;
 68             float gridStartY = (_game.Size.Y - gridH) / 2 + (20 * scale); // Сдвинули чуть вниз
 69 
 70             // 2. Координаты Хотбара
 71             float hbY = gridStartY + gridH + (5 * scale);
 72 
 73             // 3. Координаты Крафта
 74             float totalCraftW = (craftW * slotSize) + (isWorkbench ? (30 * scale) : (25 * scale)); // С учетом стрелки и результата
 75             float craftX = (_game.Size.X - totalCraftW) / 2;
 76             float craftY = gridStartY - (craftW * slotSize) - (15 * scale); // Над инвентарем
 77 
 78             // 3. Координаты Результата
 79             // Если это верстак, стрелка чуть дальше, если инвентарь - ближе
 80             float arrowXOffset = (isWorkbench) ? (3 * slotSize) + (10 * scale) : (2.5f * slotSize);
 81             float arrowX = craftX + arrowXOffset;
 82 
 83             float resX = arrowX + (25 * scale);
 84 
 85             // Подгонка высоты
 86             float resY;
 87             if (isWorkbench) resY = craftY + (1.0f * slotSize) - (2 * scale);
 88             else resY = craftY + (0.5f * slotSize) + (2 * scale); // +2 scale matching the render tweak
 89 
 90             // --- ХИТ ТЕСТ (КЛИКИ) ---
 91             Vector2 m = _game.MouseState.Position;
 92             int hoveredType = -1; // 0=Inv, 1=Craft, 2=Result
 93             int hoveredIndex = -1;
 94 
 95             // Inv Main
 96             for (int i = 9; i < 36; i++)
 97             {
 98                 int r = (i - 9) / 9; int c = (i - 9) % 9;
 99                 float sx = gridStartX + c * slotSize;
100                 float sy = gridStartY + r * slotSize;
101                 if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
102             }
103             // Inv Hotbar
104             for (int i = 0; i < 9; i++)
105             {
106                 float sx = gridStartX + i * slotSize;
107                 float sy = hbY;
108                 if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
109             }
110 
111             // Craft Grid
112             for (int y = 0; y < craftW; y++)
113             {
114                 for (int x = 0; x < craftW; x++)
115                 {
116                     int idx = y * craftW + x;
117                     float sx = craftX + x * slotSize;
118                     float sy = craftY + y * slotSize;
119                     if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 1; hoveredIndex = idx; }
120                 }
121             }
122 
123             // Result Slot
124             if (m.X >= resX && m.X < resX + slotSize && m.Y >= resY && m.Y < resY + slotSize) { hoveredType = 2; hoveredIndex = 0; }
125 
126             // --- ЛОГИКА (Нажатия) ---
127             bool leftClick = _game.MouseState.IsButtonPressed(MouseButton.Left);
128             bool rightClick = _game.MouseState.IsButtonPressed(MouseButton.Right);
129 
130             if (leftClick || rightClick)
131             {
132                 if (hoveredType == 0) // Inventory
133                 {
134                     _game.audio.PlayClick(); // ЗВУК ТУТ
135                     _game.ProcessSlotClickMethod(_game.inventory.Slots, hoveredIndex, leftClick, rightClick);
136                 }
137                 else if (hoveredType == 1) // Crafting
138                 {
139                     _game.audio.PlayClick(); // ЗВУК ТУТ
140                     _game.ProcessSlotClickMethod(_game.inventory.CraftingGrid, hoveredIndex, leftClick, rightClick);
141                     _game.inventory.CraftResult = CraftingSystem.CheckRecipe(_game.inventory.CraftingGrid, craftW);
142                 }
143                 else if (hoveredType == 2 && _game.inventory.CraftResult != null) // Result
144                 {
145                     if (leftClick || rightClick)
146                     {
147                         _game.audio.PlayClick(); // ЗВУК ТУТ
148 
149                         if (_game.inventory.DragStack == null ||
150                            (_game.inventory.DragStack.Type == _game.inventory.CraftResult.Type &&
151                             _game.inventory.DragStack.Count + _game.inventory.CraftResult.Count <= ItemStack.GetMaxStack(_game.inventory.CraftResult.Type)))
152                         {
153                             if (_game.inventory.DragStack == null)
154                                 _game.inventory.DragStack = new ItemStack(_game.inventory.CraftResult.Type, _game.inventory.CraftResult.Count);
155                             else
156                                 _game.inventory.DragStack.Count += _game.inventory.CraftResult.Count;
157 
158                             for (int i = 0; i < craftSize; i++)
159                             {
160                                 if (_game.inventory.CraftingGrid[i] != null)
161                                 {
162                                     _game.inventory.CraftingGrid[i].Count--;
163                                     if (_game.inventory.CraftingGrid[i].Count <= 0) _game.inventory.CraftingGrid[i] = null;
164                                 }
165                             }
166 
167                             _game.inventory.CraftResult = CraftingSystem.CheckRecipe(_game.inventory.CraftingGrid, craftW);
168                             _game.audio.PlayPlaceSound(_game.inventory.DragStack.Type, _game.camera.position);
169                         }
170                     }
171                 }
172             }
173 
174             _game.lastHoverType = hoveredType;
175             _game.lastHoverIdx = hoveredIndex;
176         }
177     }
