 47         private void UpdateTomolkaLogic(FrameEventArgs args)
 48         {
 49             float dt_t = (float)args.Time;
 50             if (dt_t > 0.1f) dt_t = 0.1f;
 51             var mouse_t = _game.MouseState;
 52             Vector2 mPos = mouse_t.Position;
 53 
 54             float sw = _game.Size.X; float sh = _game.Size.Y;
 55             float cx = sw / 2; float cy = sh / 2;
 56             float millRadius = 160f;
 57             float handleRadius = 25f;
 58 
 59             // 1. АВТО-ЗАГРУЗКА СЕМЯН
 60             if (_game.tomolkaInput != null && _game.tomolkaInput.Type == BlockType.WHEAT_SEED)
 61             {
 62                 _game.t_seedsInside += _game.tomolkaInput.Count * 25f;
 63                 _game.tomolkaInput = null;
 64                 _game.audio.PlayPlaceSound(BlockType.DIRT, _game.camera.position);
 65             }
 66             else if (_game.tomolkaInput != null)
 67             {
 68                 _game.world.SpawnItem(_game.camera.position, _game.tomolkaInput.Type, _game.tomolkaInput.Count);
 69                 _game.tomolkaInput = null;
 70             }
 71 
 72             // 2. ВРАЩЕНИЕ И ИНЕРЦИЯ (УВЕЛИЧЕНО СОПРОТИВЛЕНИЕ)
 73             Vector2 handlePos = new Vector2(
 74                 cx + MathF.Cos(_game.t_millRotation) * (millRadius - 30f),
 75                 cy + MathF.Sin(_game.t_millRotation) * (millRadius - 30f)
 76             );
 77 
 78             bool hoverHandle = Vector2.Distance(mPos, handlePos) < handleRadius * 1.5f;
 79 
 80             if (mouse_t.IsButtonPressed(MouseButton.Left) && hoverHandle)
 81             {
 82                 _game.t_draggingHandle = true;
 83                 _game.t_prevAngle = MathF.Atan2(mPos.Y - cy, mPos.X - cx);
 84             }
 85             if (mouse_t.IsButtonReleased(MouseButton.Left)) _game.t_draggingHandle = false;
 86 
 87             if (_game.t_draggingHandle)
 88             {
 89                 float currAngle = MathF.Atan2(mPos.Y - cy, mPos.X - cx);
 90                 float deltaAngle = currAngle - _game.t_prevAngle;
 91                 if (deltaAngle > MathF.PI) deltaAngle -= 2 * MathF.PI;
 92                 if (deltaAngle < -MathF.PI) deltaAngle += 2 * MathF.PI;
 93 
 94                 _game.t_millVelocity = deltaAngle / dt_t;
 95                 _game.t_prevAngle = currAngle;
 96             }
 97 
 98             // Применяем инерцию и СИЛЬНОЕ трение (0.85f вместо 0.95f)
 99             _game.t_millRotation += _game.t_millVelocity * dt_t;
100             _game.t_millVelocity *= 0.85f;
101 
102             float rotationSpeed = MathF.Abs(_game.t_millVelocity);
103 
104             // 3. ПОМОЛ МУКИ
105             if (rotationSpeed > 0.5f && _game.t_seedsInside > 0)
106             {
107                 float grindAmount = rotationSpeed * dt_t * 12.0f;
108                 grindAmount = Math.Min(grindAmount, _game.t_seedsInside);
109 
110                 _game.t_seedsInside -= grindAmount;
111                 _game.t_flourInside += grindAmount * 0.4f;
112                 float spillAmount = grindAmount * 0.6f;
113 
114                 if (spillAmount > 0 && new Random().NextDouble() < 0.4)
115                 {
116                     float spawnAngle = (float)new Random().NextDouble() * MathF.PI * 2;
117                     float spawnDist = millRadius + 5f + (float)new Random().NextDouble() * 50f;
118 
119                     _game.t_splats.Add(new Game.FlourSplat
120                     {
121                         Pos = new Vector2(cx + MathF.Cos(spawnAngle) * spawnDist, cy + MathF.Sin(spawnAngle) * spawnDist),
122                         Size = 15f + (float)new Random().NextDouble() * 30f,
123                         Rotation = (float)new Random().NextDouble() * MathF.PI * 2f,
124                         Amount = spillAmount * 4f
125                     });
126                 }
127 
128                 _game.t_grindSoundTimer -= dt_t;
129                 if (_game.t_grindSoundTimer <= 0)
130                 {
131                     float pitch = Math.Clamp(0.5f + (rotationSpeed / 15f), 0.6f, 1.8f);
132                     float volume = Math.Clamp(rotationSpeed / 10f, 0.1f, 1.0f);
133                     _game.audio.PlayUISound("assets/audio/footsteps/stone/1.ogg", pitch, volume * 0.6f);
134                     _game.t_grindSoundTimer = 0.25f / Math.Max(1f, rotationSpeed * 0.3f);
135                 }
136             }
137 
138             // 4. СБОР МУКИ (СТРОГО ТОЛЬКО В МЕШОК)
139             bool isCollecting = mouse_t.IsButtonDown(MouseButton.Left) && !_game.t_draggingHandle;
140 
141             // Жесткая проверка: собираем ТОЛЬКО если есть мешок
142             bool hasSack = _game.tomolkaOutput != null && _game.tomolkaOutput.Type == BlockType.LEATHER_SACK;
143             int spaceLeft = hasSack ? (5700 - _game.tomolkaOutput.Volume) : 0;
144 
145             if (isCollecting && hasSack && spaceLeft > 0)
146             {
147                 float mouseSpeed = mouse_t.Delta.Length / dt_t;
148                 bool collectedSomething = false;
149 
150                 for (int i = _game.t_splats.Count - 1; i >= 0; i--)
151                 {
152                     var splat = _game.t_splats[i];
153                     // Чуть увеличил радиус сбора, чтобы не надо было пиксельхантерством заниматься
154                     if (Vector2.Distance(mPos, splat.Pos) < splat.Size + 40f)
155                     {
156                         float collectRate = 400f * dt_t;
157                         float grabbed = Math.Min(collectRate, splat.Amount);
158                         grabbed = Math.Min(grabbed, spaceLeft - _game.t_flourFraction);
159 
160                         if (grabbed > 0)
161                         {
162                             splat.Amount -= grabbed;
163                             splat.Size -= grabbed * 0.15f;
164                             _game.t_flourFraction += grabbed;
165                             collectedSomething = true;
166                         }
167 
168                         if (splat.Amount <= 0 || splat.Size <= 0) _game.t_splats.RemoveAt(i);
169                     }
170                 }
171 
172                 if (collectedSomething)
173                 {
174                     int wholeFlour = (int)_game.t_flourFraction;
175                     if (wholeFlour > 0)
176                     {
177                         _game.tomolkaOutput.Volume += wholeFlour;
178                         _game.t_flourFraction -= wholeFlour;
179                     }
180 
181                     _game.t_powderSoundTimer -= dt_t;
182                     if (_game.t_powderSoundTimer <= 0)
183                     {
184                         float pitch = Math.Clamp(0.8f + (mouseSpeed / 2000f), 0.8f, 1.5f);
185                         float volume = Math.Clamp(mouseSpeed / 800f, 0.2f, 1.0f);
186                         _game.audio.PlayUISound("assets/audio/sfx/garden/powder.ogg", pitch, volume);
187                         _game.t_powderSoundTimer = 0.4f;
188                     }
189                 }
190             }
191         }
