 8     public class CreateWorldState : IGameState
 9     {
10         private readonly Game _game;
11 
12         public CreateWorldState(Game game)
13         {
14             _game = game;
15         }
16 
17         public void Enter()
18         {
19             _game.CursorState = CursorState.Normal;
20         }
21 
