30         public void Render(FrameEventArgs args)
31         {
32             _game.uiRenderer.Prepare();
33             _game.uiRenderer.DrawTiledBackground(_game.Size.X, _game.Size.Y);
34             _game.textRenderer.UpdateText("Create World");
35             _game.textRenderer.Render((_game.Size.X / 2) - 150, 50, 1.0f, _game.uiRenderer.GetProjection());
36 
37             float cx = (_game.Size.X - 400) / 2;
38             _game.uiRenderer.DrawRect(cx, 200, 400, 50, new Vector3(0), 0.7f);
39             _game.textRenderer.UpdateText(_game.inputWorldName + (_game.isTypingName ? "_" : ""));
40             _game.textRenderer.Render(cx + 10, 210, 0.5f, _game.uiRenderer.GetProjection());
41 
42             _game.uiRenderer.DrawRect(cx, 300, 400, 50, new Vector3(0), 0.7f);
43             _game.textRenderer.UpdateText("Seed: " + _game.inputSeed + (_game.isTypingSeed ? "_" : ""));
44             _game.textRenderer.Render(cx + 10, 310, 0.5f, _game.uiRenderer.GetProjection());
45 
46             Vector2 m = _game.MouseState.Position;
47             if (_game.MouseState.IsButtonPressed(MouseButton.Left))
48             {
49                 _game.isTypingName = (m.X > cx && m.X < cx + 400 && m.Y > 200 && m.Y < 250);
50                 _game.isTypingSeed = (m.X > cx && m.X < cx + 400 && m.Y > 300 && m.Y < 350);
51             }
52 
53             if (_game.DrawButtonMethod("Create", cx, 400, 400, 50))
54             {
55                 // СЕКРЕТНАЯ АКТИВАЦИЯ DEV MODE
56                 if (_game.inputWorldName == "walter" && _game.inputSeed == "water" && !Settings.DevModeEnabled)
57                 {
58                     Settings.DevModeEnabled = true;
59                     Settings.Save();
60                     _game.inputWorldName = "DevWorld142512r";
61                     _game.inputSeed = new Random().Next().ToString();
62                     _game.notifSystem.Add("Developer Mode", "Dev Mode Enabled! Press F2 in game.", NotifIcon.Custom);
63                 }
64                 else
65                 {
66                     int s = string.IsNullOrEmpty(_game.inputSeed) ? new Random().Next() : (int.TryParse(_game.inputSeed, out int ps) ? ps : _game.inputSeed.GetHashCode());
67                     SaveManager.CreateWorld(_game.inputWorldName, s);
68                     _game.savedWorlds = SaveManager.GetWorlds();
69                     _game.LoadWorldMethod(_game.savedWorlds.Count - 1);
70                 }
71             }
72             if (_game.DrawButtonMethod("Cancel", cx, 470, 400, 50)) _game.SetState(GameState.WorldSelect);
73         }
74 
75         public void OnTextInput(TextInputEventArgs e)
76         {
77             if (_game.isTypingName) _game.inputWorldName += (char)e.Unicode;
78             if (_game.isTypingSeed) _game.inputSeed += (char)e.Unicode;
79         }
80 
81         public void OnKeyDown(KeyboardKeyEventArgs e)
82         {
83             if (e.Key == Keys.Backspace)
84             {
85                 if (_game.isTypingName && _game.inputWorldName.Length > 0) _game.inputWorldName = _game.inputWorldName.Substring(0, _game.inputWorldName.Length - 1);
86                 if (_game.isTypingSeed && _game.inputSeed.Length > 0) _game.inputSeed = _game.inputSeed.Substring(0, _game.inputSeed.Length - 1);
87             }
88         }
89     }
