 10     public class InventoryOpenState : IGameState
 11     {
 12         private readonly Game _game;
 13 
 14         public InventoryOpenState(Game game)
 15         {
 16             _game = game;
 17         }
 18 
 19         public void Enter()
 20         {
 21             _game.CursorState = CursorState.Normal;
 22             _game.craftW = 2; // Inventory uses 2x2 craft grid
 23         }
 24 
 25         public void Exit()
 26         {
 27         }
 28 
 29         public void Update(FrameEventArgs args)
 30         {
 31             if (_game.KeyboardState.IsKeyPressed(Keys.E) || _game.KeyboardState.IsKeyPressed(Keys.Escape))
 32             {
 33                 _game.SetState(GameState.Playing);
 34                 return;
 35             }
 36 
 37             HandleInventoryInput(false); // false means not workbench
 38         }
 39 
 40         public void Render(FrameEventArgs args)
 41         {
 42             _game.RenderGameMethod();
 43 
 44             _game.uiRenderer.Prepare();
 45             // Рисуем инвентарь с крафтом 2x2
 46             _game.uiRenderer.RenderInventory(_game.inventory, _game.selectedHotbarSlot, true, _game.textRenderer, _game.ClientSize.X, _game.ClientSize.Y, _game.globalTextureArray, _game.lastHoverType, _game.lastHoverIdx);
 47 
 48             if (_game.inventory.DragStack != null)
 49             {
 50                 _game.uiRenderer.RenderDraggedItem(_game.inventory.DragStack, _game.MouseState.Position.X, _game.MouseState.Position.Y, _game.textRenderer, _game.globalTextureArray);
 51             }
 52         }
 53 
 54         private void HandleInventoryInput(bool isWorkbench)
 55         {
 56             int craftW = isWorkbench ? 3 : 2;
 57             int craftSize = craftW * craftW;
 58 
 59             float scale = _game.uiRenderer.Scale;
 60             float slotSize = 18 * scale;
 61 
 62             // 1. Координаты сетки инвентаря
 63             float gridW = 9 * slotSize;
 64             float gridH = 3 * slotSize;
 65             float gridStartX = (_game.Size.X - gridW) / 2;
 66             float gridStartY = (_game.Size.Y - gridH) / 2 + (20 * scale); // Сдвинули чуть вниз
 67 
 68             // 2. Координаты Хотбара
 69             float hbY = gridStartY + gridH + (5 * scale);
 70 
 71             // 3. Координаты Крафта
 72             float totalCraftW = (craftW * slotSize) + (isWorkbench ? (30 * scale) : (25 * scale)); // С учетом стрелки и результата
 73             float craftX = (_game.Size.X - totalCraftW) / 2;
 74             float craftY = gridStartY - (craftW * slotSize) - (15 * scale); // Над инвентарем
 75 
 76             // 3. Координаты Результата
 77             // Если это верстак, стрелка чуть дальше, если инвентарь - ближе
 78             float arrowXOffset = (isWorkbench) ? (3 * slotSize) + (10 * scale) : (2.5f * slotSize);
 79             float arrowX = craftX + arrowXOffset;
 80 
 81             float resX = arrowX + (25 * scale);
 82 
 83             // Подгонка высоты
 84             float resY;
 85             if (isWorkbench) resY = craftY + (1.0f * slotSize) - (2 * scale);
 86             else resY = craftY + (0.5f * slotSize) + (2 * scale); // +2 scale matching the render tweak
 87 
 88             // --- ХИТ ТЕСТ (КЛИКИ) ---
 89             Vector2 m = _game.MouseState.Position;
 90             int hoveredType = -1; // 0=Inv, 1=Craft, 2=Result
 91             int hoveredIndex = -1;
 92 
 93             // Inv Main
 94             for (int i = 9; i < 36; i++)
 95             {
 96                 int r = (i - 9) / 9; int c = (i - 9) % 9;
 97                 float sx = gridStartX + c * slotSize;
 98                 float sy = gridStartY + r * slotSize;
 99                 if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
100             }
101             // Inv Hotbar
102             for (int i = 0; i < 9; i++)
103             {
104                 float sx = gridStartX + i * slotSize;
105                 float sy = hbY;
106                 if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 0; hoveredIndex = i; }
107             }
108 
109             // Craft Grid
110             for (int y = 0; y < craftW; y++)
111             {
112                 for (int x = 0; x < craftW; x++)
113                 {
114                     int idx = y * craftW + x;
115                     float sx = craftX + x * slotSize;
116                     float sy = craftY + y * slotSize;
117                     if (m.X >= sx && m.X < sx + slotSize && m.Y >= sy && m.Y < sy + slotSize) { hoveredType = 1; hoveredIndex = idx; }
118                 }
119             }
120 
121             // Result Slot
122             if (m.X >= resX && m.X < resX + slotSize && m.Y >= resY && m.Y < resY + slotSize) { hoveredType = 2; hoveredIndex = 0; }
123 
124             // --- ЛОГИКА (Нажатия) ---
125             bool leftClick = _game.MouseState.IsButtonPressed(MouseButton.Left);
126             bool rightClick = _game.MouseState.IsButtonPressed(MouseButton.Right);
127 
128             if (leftClick || rightClick)
129             {
130                 if (hoveredType == 0) // Inventory
131                 {
132                     _game.audio.PlayClick(); // ЗВУК ТУТ
133                     _game.ProcessSlotClickMethod(_game.inventory.Slots, hoveredIndex, leftClick, rightClick);
134                 }
135                 else if (hoveredType == 1) // Crafting
136                 {
137                     _game.audio.PlayClick(); // ЗВУК ТУТ
138                     _game.ProcessSlotClickMethod(_game.inventory.CraftingGrid, hoveredIndex, leftClick, rightClick);
139                     _game.inventory.CraftResult = CraftingSystem.CheckRecipe(_game.inventory.CraftingGrid, craftW);
140                 }
141                 else if (hoveredType == 2 && _game.inventory.CraftResult != null) // Result
142                 {
143                     if (leftClick || rightClick)
144                     {
145                         _game.audio.PlayClick(); // ЗВУК ТУТ
146 
147                         if (_game.inventory.DragStack == null ||
148                            (_game.inventory.DragStack.Type == _game.inventory.CraftResult.Type &&
149                             _game.inventory.DragStack.Count + _game.inventory.CraftResult.Count <= ItemStack.GetMaxStack(_game.inventory.CraftResult.Type)))
150                         {
151                             if (_game.inventory.DragStack == null)
152                                 _game.inventory.DragStack = new ItemStack(_game.inventory.CraftResult.Type, _game.inventory.CraftResult.Count);
153                             else
154                                 _game.inventory.DragStack.Count += _game.inventory.CraftResult.Count;
155 
156                             for (int i = 0; i < craftSize; i++)
157                             {
158                                 if (_game.inventory.CraftingGrid[i] != null)
159                                 {
160                                     _game.inventory.CraftingGrid[i].Count--;
161                                     if (_game.inventory.CraftingGrid[i].Count <= 0) _game.inventory.CraftingGrid[i] = null;
162                                 }
163                             }
164 
165                             _game.inventory.CraftResult = CraftingSystem.CheckRecipe(_game.inventory.CraftingGrid, craftW);
166                             _game.audio.PlayPlaceSound(_game.inventory.DragStack.Type, _game.camera.position);
167                         }
168                     }
169                 }
170             }
171 
172             _game.lastHoverType = hoveredType;
173             _game.lastHoverIdx = hoveredIndex;
174         }
175         public void OnTextInput(TextInputEventArgs e) { }
176         public void OnKeyDown(KeyboardKeyEventArgs e) { }
177     }
178 }

