329         private void HandleTomolkaInventoryInput()
330         {
331             float sw = _game.Size.X; float sh = _game.Size.Y;
332             float cx = sw / 2; float cy = sh / 2;
333 
334             // Новые размеры окна
335             float winW = 860; float winH = 540;
336             float winX = cx - winW / 2; float winY = cy - winH / 2;
337 
338             // Новые позиции слотов
339             float slotSize = 80;
340             float inX = winX + 70; float inY = cy - slotSize / 2;
341             float outX = winX + winW - 70 - slotSize; float outY = cy - slotSize / 2;
342 
343             Vector2 m = _game.MouseState.Position;
344             int hoveredType = -1;
345             int hoveredIndex = -1;
346 
347             float scale = 3.0f;
348             float hudW = 182 * scale;
349             float hudH = 22 * scale;
350             float hudX = cx - hudW / 2;
351             float hudY = winY + winH + 10; // Под окном
352 
353 
354             for (int i = 0; i < 9; i++)
355             {
356                 float sx = hudX + (3 * scale) + (i * 20 * scale);
357                 if (m.X >= sx && m.X < sx + (16 * scale) && m.Y >= hudY && m.Y < hudY + (16 * scale))
358                 {
359                     hoveredType = 0; hoveredIndex = i;
360                 }
361             }
362 
363             if (m.X >= inX && m.X < inX + slotSize && m.Y >= inY && m.Y < inY + slotSize) { hoveredType = 3; hoveredIndex = 0; }
364             if (m.X >= outX && m.X < outX + slotSize && m.Y >= outY && m.Y < outY + slotSize) { hoveredType = 4; hoveredIndex = 0; }
365 
366             bool leftClick = _game.MouseState.IsButtonPressed(MouseButton.Left);
367             bool rightClick = _game.MouseState.IsButtonPressed(MouseButton.Right);
368 
369             _game.lastHoverType = hoveredType;
370             _game.lastHoverIdx = hoveredIndex;
371 
372             if (leftClick || rightClick)
373             {
374                 if (hoveredType == 0)
375                 {
376                     _game.audio.PlayClick();
377                     _game.ProcessSlotClickMethod(_game.inventory.Slots, hoveredIndex, leftClick, rightClick);
378                 }
379                 else if (hoveredType == 3)
