 45             // Рисуем верстак 3x3
 46             _game.uiRenderer.RenderWorkbench(_game.inventory, _game.textRenderer, _game.ClientSize.X, _game.ClientSize.Y, _game.globalTextureArray, _game.lastHoverType, _game.lastHoverIdx);
 47 
 48             if (_game.inventory.DragStack != null)
 49             {
 50                 _game.uiRenderer.RenderDraggedItem(_game.inventory.DragStack, _game.MouseState.Position.X, _game.MouseState.Position.Y, _game.textRenderer, _game.globalTextureArray);
 51             }
