309         private Vector3 FindSafeSpawn()
310         {
311             // Ищем по спирали от центра мира
312             for (int radius = 0; radius < 100; radius += 4)
313             {
314                 for (int x = -radius; x <= radius; x += 4)
315                 {
316                     for (int z = -radius; z <= radius; z += 4)
317                     {
318                         // Ищем только по периметру текущего квадрата
319                         if (Math.Abs(x) != radius && Math.Abs(z) != radius) continue;
320 
321                         // Сканируем высоту (начиная выше уровня моря!)
322                         for (int y = 120; y > TerrainGenerator.OceanLevel; y--)
323                         {
324                             BlockType b = world.GetBlock(new Vector3(x, y, z));
325                             // Ищем твердый блок
326                             if (b != BlockType.AIR && b != BlockType.WATER && b != BlockType.LEAVES && b != BlockType.LOG)
327                             {
328                                 BlockType up1 = world.GetBlock(new Vector3(x, y + 1, z));
329                                 BlockType up2 = world.GetBlock(new Vector3(x, y + 2, z));
330 
331                                 // Если над нами 2 блока воздуха — место найдено!
332                                 if (up1 == BlockType.AIR && up2 == BlockType.AIR)
333                                 {
334                                     return new Vector3(x + 0.5f, y + 1.5f, z + 0.5f);
335                                 }
336                             }
337                         }
338                     }
339                 }
340             }
341             // Если вся загруженная зона — море, спавним высоко, парашют спасет
342             return new Vector3(0.5f, 100f, 0.5f);
343         }
