538                     break;
539                 case ServerStateSnapshotPacket snapshot:
540                     _lastClientSnapshot = $"tick={snapshot.ServerTick} chunks={snapshot.ActiveChunks}/{snapshot.LoadedChunks} pos={snapshot.EchoedPlayerPosition.X:0.0},{snapshot.EchoedPlayerPosition.Y:0.0},{snapshot.EchoedPlayerPosition.Z:0.0}";
