553         protected override void OnUpdateFrame(FrameEventArgs args)
554         {
555             frameTimer.Restart();
556             base.OnUpdateFrame(args);
557             // --- FLOATING ORIGIN (ПЛАВАЮЩАЯ ТОЧКА ОТСЧЕТА) ---
558             if (world != null && (CurrentState == GameState.Playing || CurrentState == GameState.DevMenu || isDebugCam))
559             {
560                 Vector3i shift = Vector3i.Zero;
561                 int limit = 2000; // Уходим дальше 2000 - возвращаем мир в центр
562 
563                 if (camera.position.X > limit) shift.X = limit;
564                 else if (camera.position.X < -limit) shift.X = -limit;
565 
566                 if (camera.position.Z > limit) shift.Z = limit;
567                 else if (camera.position.Z < -limit) shift.Z = -limit;
568 
569                 if (shift != Vector3i.Zero)
570                 {
571                     camera.position -= new Vector3(shift.X, 0, shift.Z);
572                     camera.ResetFallState();
573                     if (isDebugCam) debugCamera.position -= new Vector3(shift.X, 0, shift.Z);
574 
575                     world.ShiftOrigin(shift);
576                     weatherRenderer.ResetParticles();
577                     cloudRenderer.CloudOffset.X -= shift.X;
578                     cloudRenderer.CloudOffset.Y -= shift.Z;
579                 }
580             }
581             bool isMenu = (CurrentState != GameState.Playing && CurrentState != GameState.Paused && CurrentState != GameState.InventoryOpen && CurrentState != GameState.Dead);
582             audio.UpdateMusic((float)args.Time, isMenu, Settings.MusicVolume);
583 
584             // --- TICK SYSTEM LOGIC (С ЗАЩИТОЙ ОТ СПИРАЛИ СМЕРТИ) ---
585             accumulatedTime += args.Time;
586 
587             // ФИКС: Если игра зависла (например, при загрузке или из-за винды), 
588             // не пытаемся просчитать 500 тиков за раз. Сбрасываем лишнее время!
589             if (accumulatedTime > 0.5)
590             {
591                 accumulatedTime = 0.5; // Максимум 10 тиков за один кадр
592             }
593 
594             while (accumulatedTime >= TIME_PER_TICK)
595             {
596                 GameTick();
597                 accumulatedTime -= TIME_PER_TICK;
598             }
599 
600             // Подсчет FPS и TPS
601             oneSecondTimer += args.Time;
602             frames++;
603             if (oneSecondTimer >= 1.0)
604             {
605                 fps = frames;
606                 tps = tickCounter;
607 
608                 // ВОЗВРАЩАЕМ ВЫВОД В КОНСОЛЬ
609                 double avgUpdate = frames > 0 ? totalUpdateTimeMs / frames : 0;
610                 double avgRender = frames > 0 ? totalRenderTimeMs / frames : 0;
611                 // Записываем статистику в advanced_log.txt раз в 5 сек
612                 EarthBound.Diagnostics.AdvancedProfiler.Update(fps, tps, camera.position);
613                 Console.WriteLine($"[PERFORMANCE] FPS: {fps} | TPS: {tps} | Update: {avgUpdate:0.00}ms | Render(CPU): {avgRender:0.00}ms");
614 
615                 totalUpdateTimeMs = 0;
616                 totalRenderTimeMs = 0;
617             // --- INPUT MANAGEMENT ---
618             _inputManager.Update((float)args.Time);
619             {
620                 camera.position = new Vector3(camera.position.X, 240, camera.position.Z);
621                 camera.velocity = Vector3.Zero;
622                 camera.ResetFallState();
623                 isBurning = false;
624                 burnTimer = 0;
625             }
626 
627 
628             float dt = (float)args.Time;
629             _lastDt = dt;
630             multiplayerClient?.Pump();
631 
632 
633             _gameStateManager.Update(args);
634         }
635 
636     }
637 }
