18         public void EnsureConnected(string playerName)
19         {
20             if (_helloSent) return;
21             _endpoint.Send(new ClientHelloPacket(playerName, protocolVersion: 1));
22             _helloSent = true;
23         }
24 
25         public void SendPlayerInput(long clientTick, Camera camera, byte stateFlags)
26         {
27             _endpoint.Send(new PlayerInputPacket(clientTick, camera.position, camera.velocity, camera.Front, stateFlags));
28         }
