30         public void SendChunkInterest(Vector3 playerPosition, int renderDistance)
31         {
32             int cx = (int)MathF.Floor(playerPosition.X / World.Chunk.SIZE);
33             int cz = (int)MathF.Floor(playerPosition.Z / World.Chunk.SIZE);
34             _endpoint.Send(new ChunkInterestPacket(cx, cz, renderDistance));
35         }
36 
37         public void DrainIncomingPackets(Action<Networking.INetworkPacket> handler)
38         {
39             while (_endpoint.TryReceive(out Networking.INetworkPacket packet))
40                 handler(packet);
41         }
