 1 using System.Collections.Concurrent;
 2 
 3 namespace EarthBound.Server.Networking
 4 {
 5     public sealed class LoopbackNetworkEndpoint
 6     {
 7         private readonly ConcurrentQueue<NetworkPacketEnvelope> _inbound;
 8         private readonly ConcurrentQueue<NetworkPacketEnvelope> _remoteInbound;
 9 
10         private long _packetsSent;
11         private long _packetsReceived;
12         private long _bytesSent;
13         private long _bytesReceived;
14         private string _lastSentPacket = "-";
15         private string _lastReceivedPacket = "-";
16 
17         internal LoopbackNetworkEndpoint(string role, ConcurrentQueue<NetworkPacketEnvelope> inbound, ConcurrentQueue<NetworkPacketEnvelope> remoteInbound)
18         {
19             Role = role;
20             _inbound = inbound;
21             _remoteInbound = remoteInbound;
22         }
23 
24         public string Role { get; }
25 
26         public void Send(INetworkPacket packet)
27         {
28             NetworkPacketEnvelope envelope = NetworkPacketCodec.Serialize(packet);
29             _remoteInbound.Enqueue(envelope);
30             _packetsSent++;
31             _bytesSent += envelope.Payload.Length;
32             _lastSentPacket = packet.Kind.ToString();
33         }
34 
35         public bool TryReceive(out INetworkPacket packet)
36         {
37             if (_inbound.TryDequeue(out NetworkPacketEnvelope envelope))
38             {
39                 _packetsReceived++;
40                 _bytesReceived += envelope.Payload.Length;
41                 _lastReceivedPacket = envelope.Kind.ToString();
42                 packet = NetworkPacketCodec.Deserialize(envelope);
43                 return true;
44             }
45 
46             packet = null;
47             return false;
48         }
49 
50         public NetworkConnectionDebugSnapshot GetDebugSnapshot()
51         {
52             return new NetworkConnectionDebugSnapshot(
53                 Role,
54                 _packetsSent,
55                 _packetsReceived,
56                 _bytesSent,
57                 _bytesReceived,
58                 _inbound.Count,
59                 _lastSentPacket,
60                 _lastReceivedPacket);
61         }
62 
63         public static (LoopbackNetworkEndpoint server, LoopbackNetworkEndpoint client) CreatePair()
64         {
65             var serverInbound = new ConcurrentQueue<NetworkPacketEnvelope>();
66             var clientInbound = new ConcurrentQueue<NetworkPacketEnvelope>();
67 
68             return (
69                 new LoopbackNetworkEndpoint("Server", serverInbound, clientInbound),
70                 new LoopbackNetworkEndpoint("Client", clientInbound, serverInbound));
71         }
72     }
73 }

