 5 namespace EarthBound.Server.Networking
 6 {
 7     public static class NetworkPacketCodec
 8     {
 9         public static NetworkPacketEnvelope Serialize(INetworkPacket packet)
10         {
11             using MemoryStream stream = new MemoryStream();
12             using BinaryWriter writer = new BinaryWriter(stream);
13             packet.Write(writer);
14             return new NetworkPacketEnvelope(packet.Kind, stream.ToArray());
15         }
16 
17         public static INetworkPacket Deserialize(NetworkPacketEnvelope envelope)
18         {
19             using MemoryStream stream = new MemoryStream(envelope.Payload);
20             using BinaryReader reader = new BinaryReader(stream);
21 
22             return envelope.Kind switch
23             {
24                 NetworkPacketKind.ClientHello => ClientHelloPacket.Read(reader),
25                 NetworkPacketKind.PlayerInput => PlayerInputPacket.Read(reader),
26                 NetworkPacketKind.ChunkInterest => ChunkInterestPacket.Read(reader),
27                 NetworkPacketKind.ServerHeartbeat => ServerHeartbeatPacket.Read(reader),
28                 NetworkPacketKind.ServerStateSnapshot => ServerStateSnapshotPacket.Read(reader),
29                 _ => throw new InvalidOperationException($"Unknown packet kind: {envelope.Kind}")
30             };
31         }
32     }
33 }

