223                 byte[] pixels = new byte[size * size * 4];
224                 GL.ReadPixels(x, y, size, size, OpenTK.Graphics.OpenGL4.PixelFormat.Bgra, PixelType.UnsignedByte, pixels);
225 
226                 // Создаем битмап сразу в формате 32bpp
227                 using (Bitmap rawBmp = new Bitmap(size, size, System.Drawing.Imaging.PixelFormat.Format32bppArgb))
