245                         g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.HighQuality;
246                         g.PixelOffsetMode = System.Drawing.Drawing2D.PixelOffsetMode.HighQuality;
247                         g.DrawImage(rawBmp, 0, 0, 64, 64);
