  1 using OpenTK.Windowing.Common;
  2 using OpenTK.Mathematics;
  3 using EarthBound.World;
  4 using EarthBound.World.Blocks;
  5 using EarthBound.Audio;
  6 using System;
  7 
  8 namespace EarthBound.States
  9 {
 10     public class PlayingState : IGameState
 11     {
 12         private readonly Game _game;
 13 
 14         public PlayingState(Game game)
 15         {
 16             _game = game;
 17         }
 18 
 19         public void Enter()
 20         {
 21             _game.CursorState = CursorState.Grabbed;
 22             _game.camera.ResetMouse();
 23         }
 24 
 25         public void Exit()
 26         {
 27         }
 28 
 29         public void Update(FrameEventArgs args)
 30         {
 31             float dt = (float)args.Time;
 32 
 33             if (_game.IsFocused && _game.CursorState == CursorState.Grabbed)
 34             {
 35                 // Check Fall Damage from Camera
 36                 // 1. Урон от падения
 37                 if (_game.camera.PendingDamage > 0)
 38                 {
 39                     _game.ApplyDamage(_game.camera.PendingDamage);
 40                     _game.camera.PendingDamage = 0;
 41 
 42                     if (_game.playerHealth <= 0)
 43                     {
 44                         _game.playerHealth = 0;
 45                         _game.CurrentState = GameState.Dead;
 46                         _game.CursorState = CursorState.Normal;
 47                     }
 48                 }
 49 
 50                 // --- ВОДА И ВСПЛЕСКИ (Теперь всегда проверяется!) ---
 51                 float rSplash = 0.25f;
 52                 bool feetInWater = _game.world.IsWater(_game.camera.position.X, _game.camera.position.Y + 0.2f, _game.camera.position.Z) ||
 53                                    _game.world.IsWater(_game.camera.position.X - rSplash, _game.camera.position.Y + 0.2f, _game.camera.position.Z - rSplash) ||
 54                                    _game.world.IsWater(_game.camera.position.X + rSplash, _game.camera.position.Y + 0.2f, _game.camera.position.Z + rSplash);
 55                 bool eyesInWater = _game.world.IsWater(_game.camera.position.X, _game.camera.position.Y + 1.8f, _game.camera.position.Z);
 56                 bool isInLiquid = feetInWater || eyesInWater;
 57                 // Средняя точка погружения (для плавности намокания)
 58                 bool waistInWater = _game.world.IsWater(_game.camera.position.X, _game.camera.position.Y + 1.0f, _game.camera.position.Z);
 59 
 60                 // ---- СИСТЕМА ПРОМОКАНИЯ И СУШКИ ИГРОКА ----
 61                 if (isInLiquid)
 62                 {
 63                     _game.camera.WaterTimer += dt;
 64                     if (_game.camera.WaterTimer > 0.15f) // 0.1-0.2 секундная задержка перед началом намокания
 65                     {
 66                         float wetSpeed = 0.1f;
 67                         if (eyesInWater) wetSpeed = 1.0f;        // Полное погружение -> промокает за 1 секунду
 68                         else if (waistInWater) wetSpeed = 0.5f;   // По пояс в воде -> намокание за 2 секунды
 69                         else if (feetInWater) wetSpeed = 0.25f;   // Ноги в воде -> намокание за 4 секунды
 70 
 71                         _game.camera.Wetness = MathHelper.Clamp(_game.camera.Wetness + wetSpeed * dt, 0.0f, 1.0f);
 72                     }
 73                 }
 74                 else
 75                 {
 76                     _game.camera.WaterTimer = 0.0f; // Сбрасываем таймер входа в воду
 77 
 78                     int px = (int)MathF.Floor(_game.camera.position.X);
 79                     int pz = (int)MathF.Floor(_game.camera.position.Z);
 80                     int py = (int)MathF.Floor(_game.camera.position.Y);
 81                     int groundY = _game.world.GetHighestSolidBlockY(px, pz);
 82                     bool hasRoof = groundY > py + 1;
 83 
 84                     if (_game.worldTime.RainIntensity > 0.01f && !hasRoof)
 85                     {
 86                         // Игрок промокает под дождем
 87                         _game.camera.Wetness = MathHelper.Clamp(_game.camera.Wetness + 0.08f * _game.worldTime.RainIntensity * dt, 0.0f, 1.0f);
 88                     }
 89                     else
 90                     {
 91                         // Естественное высыхание в сухом месте
 92                         float drySpeed = 0.015f;
 93 
 94                         // Быстрая сушка возле огня или лавы (в радиусе 3 блоков)
 95                         bool nearHeat = false;
 96                         int rRange = 3;
 97                         for (int dx = -rRange; dx <= rRange && !nearHeat; dx++)
 98                             for (int dy = -rRange; dy <= rRange && !nearHeat; dy++)
 99                                 for (int dz = -rRange; dz <= rRange; dz++)
100                                 {
101                                     BlockType b = _game.world.GetBlock(new Vector3(px + dx, py + dy, pz + dz));
102                                     if (b == BlockType.FIRE || b == BlockType.LAVA)
103                                     {
104                                         nearHeat = true;
105                                         break;
106                                     }
107                                 }
108 
109                         if (nearHeat)
110                         {
111                             drySpeed = 0.25f; // Около огня сохнет в 15 раз быстрее
112                         }
113 
114                         _game.camera.Wetness = MathHelper.Clamp(_game.camera.Wetness - drySpeed * dt, 0.0f, 1.0f);
115                     }
116                 }
117                 // Срабатывает при меньшей скорости падения (-2.0f)
118                 if (isInLiquid && !_game.wasInWater && _game.camera.velocity.Y < -2.0f)
119                 {
120                     // Множитель скорости увеличен с 0.3f до 1.5f (чем быстрее летел, тем ОГРОМНЕЕ всплеск)
121                     _game.particleEmitter.EmitSplash(_game.camera.position + new Vector3(0, 0.5f, 0), Math.Abs(_game.camera.velocity.Y) * 1.5f);
122                     _game.audio.PlayFootstep("water", _game.camera.position, 1.0f);
123                 }
124                 _game.wasInWater = isInLiquid;
125 
126                 // 2. Логика Огня и Лавы
127                 Vector3 pPos = _game.camera.position;
128                 BlockType feetBlock = _game.world.GetBlock(pPos);
129                 BlockType legBlock = _game.world.GetBlock(new Vector3(pPos.X, pPos.Y - 1, pPos.Z));
130 
131                 bool inWater = feetBlock == BlockType.WATER || legBlock == BlockType.WATER;
132 
133                 // Если мы в воде, мы в безопасности, огонь тушится мгновенно
134                 if (inWater)
135                 {
136                     if (_game.isBurning)
137                     {
138                         _game.isBurning = false;
139                         _game.burnTimer = 0;
140                         _game.audio.PlayFootstep("water", pPos); // Звук пшшш сыграет ОДИН раз
141                     }
142                 }
143                 else
144                 {
145                     if (feetBlock == BlockType.LAVA || legBlock == BlockType.LAVA)
146                     {
147                         _game.isBurning = true;
148                         _game.burnTimer = 10.0f;
149                         if (_game.hitSoundTimer <= 0) { _game.ApplyDamage(4.0f); _game.hitSoundTimer = 0.5f; }
150                     }
151                     else if (feetBlock == BlockType.FIRE || legBlock == BlockType.FIRE)
152                     {
153                         _game.isBurning = true;
154                         _game.burnTimer = 5.0f;
155                     }
156                 }
157 
158                 if (_game.isBurning)
159                 {
160                     _game.burnTimer -= dt;
161                     if (_game.burnTimer <= 0) _game.isBurning = false;
162                     if (_game.totalTicks % 20 == 0) _game.ApplyDamage(1.0f);
163                 }
164 
165                 // 3. Обновление камеры и аудио (Камера должна быть плавной, оставляем в Update)
166                 if (_game.isDebugCam)
167                 {
168                     bool oldNoClip = Settings.NoClip;
169                     Settings.NoClip = true; // Форсируем полет (без гравитации)
170                     _game.debugCamera.Update(_game.KeyboardState, _game.MouseState, args, null, false);
171                     Settings.NoClip = oldNoClip;
172                 }
173                 else
174                 {
175                     _game.camera.Update(_game.KeyboardState, _game.MouseState, args, _game.world, false);
176                 }
177 
178                 // Правильный математический расчет вектора "Макушки" (Up) для 3D эмбиента
179                 Vector3 camRight = Vector3.Normalize(Vector3.Cross(_game.camera.Front, Vector3.UnitY));
180                 if (camRight.LengthSquared < 0.001f) camRight = Vector3.UnitX; // Защита от NaN, если смотрим строго вниз
181                 Vector3 camUp = Vector3.Normalize(Vector3.Cross(camRight, _game.camera.Front));
182 
183                 // Поднимаем уши на уровень глаз! (иначе звук ручьев будет казаться выше нас)
184                 _game.audio.UpdateListener(_game.camera.GetEyePosition(), _game.camera.Front, camUp);
185 
186                 Vector3 headPos = _game.camera.GetEyePosition();
187                 int headSunLight = _game.world.GetSunLight((int)headPos.X, (int)headPos.Y, (int)headPos.Z);
188                 int headBlockLight = _game.world.GetBlockLight((int)headPos.X, (int)headPos.Y, (int)headPos.Z);
189 
190                 // Вычисляем, насколько светло сейчас голове игрока
191                 float ambientSun = (headSunLight / 15.0f) * _game.worldTime.GlobalLight.X;
192                 float ambientBlock = headBlockLight / 15.0f;
193                 float currentHeadLight = Math.Max(ambientSun, ambientBlock);
194 
195                 // Если вышли на свет - слепнем (привыкаем) быстро. Если зашли в тьму - привыкаем медленно.
196                 float adaptSpeed = (currentHeadLight > _game.eyeAdaptation) ? 3.0f : 0.4f;
197                 _game.eyeAdaptation = MathHelper.Lerp(_game.eyeAdaptation, currentHeadLight, dt * adaptSpeed);
198                 // Обновляем логику облаков
199                 if (Settings.CloudMode == 2)
200                 {
201                     _game.cloudRenderer.Update(dt, _game.camera.position, _game.worldTime.WindStrength, _game.worldTime.WindDir);
202                 }
203 
204                 // 4. ЗВУК ПРИЗЕМЛЕНИЯ
205                 if (_game.camera.JustLanded)
206                 {
207                     _game.camera.JustLanded = false;
208 
209                     // Если зажат пробел, мы УЖЕ подпрыгнули на долю блока. 
210                     // Проверяем прямо под ногами (-0.1f), а если там воздух — проверяем ниже (-1.1f)
211                     Vector3 checkPos = _game.camera.position - new Vector3(0, 0.1f, 0);
212                     BlockType bLand = _game.world.GetBlock(checkPos);
213 
214                     if (bLand == BlockType.AIR || bLand == BlockType.WATER || bLand == BlockType.FIRE)
215                     {
216                         checkPos = _game.camera.position - new Vector3(0, 1.1f, 0);
217                         bLand = _game.world.GetBlock(checkPos);
218                     }
219 
220                     if (bLand != BlockType.AIR && bLand != BlockType.WATER)
221                     {
222                         string mat = EarthBound.World.Blocks.BlocksManager.GetBlock(bLand).SoundCategory;
223                         _game.audio.PlayFootstep(mat, _game.camera.position, 0.5f, 1.2f);
224                     }
225                 }
226 
227                 // 5. FOOTSTEP SOUNDS
228                 if (_game.camera.WalkDistance > _game.nextStepDistance)
229                 {
230                     _game.nextStepDistance = _game.camera.WalkDistance + 1.5f;
231                     bool feetInWater = _game.world.IsWater(_game.camera.position.X, _game.camera.position.Y - 0.5f, _game.camera.position.Z);
232 
233                     // Убираем костыль! camera.position — это УЖЕ координаты ног. Если вычесть 1.6, звук играл глубоко под землей.
234                     Vector3 feetPos = _game.camera.position;
235 
236                     if (feetInWater)
237                     {
238                         _game.audio.PlayFootstep("water", feetPos, 1.0f);
239                     }
240                     else
241                     {
242                         Vector3 underFeet = _game.camera.position - new Vector3(0, 0.1f, 0);
243                         BlockType bType = _game.world.GetBlock(underFeet);
244 
245                         if (bType == BlockType.AIR || bType == BlockType.WATER || bType == BlockType.FIRE)
246                         {
247                             Vector3 below = _game.camera.position - new Vector3(0, 1.1f, 0);
248                             bType = _game.world.GetBlock(below);
249                         }
250 
251                         if (bType != BlockType.AIR && bType != BlockType.WATER)
252                         {
253                             string mat = EarthBound.World.Blocks.BlocksManager.GetBlock(bType).SoundCategory;
254                             _game.audio.PlayFootstep(mat, feetPos, 1.0f);
255                         }
256                     }
257                 }
258 
259                 // --- MUSIC LOGIC ---
260                 _game.musicTimer -= dt;
261                 if (_game.musicTimer <= 0)
262                 {
263                     // ИСПОЛЬЗУЕМ НОВЫЙ МЕТОД (0.35f - это базовая громкость трека)
264                     _game.audio.PlayGameMusic("assets/audio/music/minecraft_track (1).ogg", 0.35f);
265                     _game.musicTimer = 300f + (float)new Random().NextDouble() * 300f;
266                 }
267 
268                 // --- WATER AMBIENCE LOGIC (Continuous) ---
269                 _game.waterAmbienceTimer += dt;
270                 if (_game.waterAmbienceTimer > 0.2f)
271                 {
272                     _game.waterAmbienceTimer = 0;
273                     int waterSourceCount = 0;
274                     int waterFlowCount = 0;
275                     int lavaCount = 0; // Считаем лаву
276                     int radius = 4;
277                     Vector3 closestLava = _game.camera.position;
278                     float minDist = 999f;
279 
280                     int px = (int)_game.camera.position.X; int py = (int)_game.camera.position.Y; int pz = (int)_game.camera.position.Z;
281 
282                     for (int x = -radius; x <= radius; x++)
283                         for (int y = -2; y <= 2; y++)
284                             for (int z = -radius; z <= radius; z++)
285                             {
286                                 BlockType b = _game.world.GetBlock(new Vector3(px + x, py + y, pz + z));
287                                 if (b == BlockType.WATER)
288                                 {
289                                     byte data = _game.world.GetBlockData(new Vector3(px + x, py + y, pz + z));
290                                     if (data == 8 || data == 0) waterSourceCount++; else waterFlowCount++;
291                                 }
292                                 else if (b == BlockType.LAVA)
293                                 {
294                                     lavaCount++;
295                                     float d = new Vector3(x, y, z).Length;
296                                     if (d < minDist) { minDist = d; closestLava = new Vector3(px + x, py + y, pz + z); }
297                                 }
298                             }
299                     _game.audio.UpdateWaterStream(_game.currentStreamVol, _game.camera.position);
300                     _game.audio.UpdateWaterAmbience(Math.Clamp(waterSourceCount / 20.0f, 0.0f, 0.5f));
301                     _game.currentStreamVol = Math.Clamp(waterFlowCount / 5.0f, 0.0f, 0.8f);
302 
303                     // Эмбиент лавы
304                     _game.audio.UpdateLavaAmbience(lavaCount > 0 ? 0.6f : 0.0f, closestLava);
305                 }
306 
307                 // Чанки обновляем каждый кадр для плавности загрузки
308                 _game.world.UpdateChunksAroundPlayer(_game.camera.position, _game.camera.Front, Settings.RenderDistance);
309 
310                 // --- RAIN AMBIENCE LOGIC ---
311                 if (_game.worldTime.RainIntensity > 0.01f)
312                 {
313                     int px = (int)MathF.Floor(_game.camera.position.X);
314                     int pz = (int)MathF.Floor(_game.camera.position.Z);
315                     int py = (int)MathF.Floor(_game.camera.position.Y);
316                     float temp = _game.world.Generator.GetTemperature(px, pz);
317 
318                     if (temp >= 0.35f)
319                     {
320                         // Целевая громкость = реальная плотность частиц дождя × интенсивность
321                         float rainDensity = _game.weatherRenderer.GetRainDensityNorm();
322                         float splashNorm = rainDensity * _game.worldTime.RainIntensity;
323                         // Плавный lerp: нарастает медленно (как и количество частиц), убывает чуть быстрее
324                         float lerpUp = dt * 0.15f;  // медленно нарастаем — синхронно с партиклами
325                         float lerpDown = dt * 0.4f;
326                         _game.rainSoundAccumulator = _game.rainSoundAccumulator < splashNorm
327                             ? Math.Min(_game.rainSoundAccumulator + lerpUp, splashNorm)
328                             : Math.Max(_game.rainSoundAccumulator - lerpDown, splashNorm);
329 
330                         int groundY = _game.world.GetHighestSolidBlockY(px, pz);
331                         bool hasRoof = groundY > py + 1;
332 
333                         // Позиция звука — фиксированная точка над землёй, не двигается с игроком каждый кадр
334                         // Lerp к новой позиции медленно — убирает "бегающий звук"
335                         Vector3 targetSoundPos = hasRoof
336                             ? new Vector3(px, py + 8f, pz)
337                             : new Vector3(px, groundY + 0.5f, pz);
338 
339                         float targetVol = hasRoof
340                             ? 0.15f * _game.rainSoundAccumulator
341                             : _game.rainSoundAccumulator;
342 
343                         _game.audio.UpdateRainAmbience(targetVol, targetSoundPos);
344                     }
345                     else
346                     {
347                         // Снег — плавно сбрасываем аккумулятор
348                         _game.rainSoundAccumulator = Math.Max(_game.rainSoundAccumulator - dt * 0.15f, 0f);
349                         _game.audio.UpdateRainAmbience(0.0f, _game.camera.position);
350                     }
351                 }
352                 else
353                 {
354                     // Дождь кончился — плавно сбрасываем
355                     _game.rainSoundAccumulator = Math.Max(_game.rainSoundAccumulator - dt * 0.1f, 0f);
356                     if (_game.rainSoundAccumulator > 0.01f)
357                         _game.audio.UpdateRainAmbience(_game.rainSoundAccumulator * 0.5f, _game.camera.position);
358                     else
359                         _game.audio.UpdateRainAmbience(0.0f, _game.camera.position);
360                 }
361 
362                 // Время обновляем плавно для неба
363                 _game.worldTime.Update(dt);
364 
365                 // Обновление физического симулятора воздушных потоков ветра
366                 if (_game.windEngine != null)
367                 {
368                     _game.windEngine.Update(dt, _game.camera.position, _game.world, _game.worldTime.WindStrength, _game.worldTime.WindDir);
369                 }
370 
371                 // --- ТАЙМЕР ГОРЯЩЕГО ВЕДРА В ИНВЕНТАРЕ ---
372                 for (int i = 0; i < 9; i++)
373                 {
374                     _game.inventory.ConsumeItem(i, 1); // Ведро сгорело
375                     _game.audio.PlaySteamSound(_game.camera.position);
376                 }
377             }
378         }
